1	/**
2	 * Shared types for the per-game one-click mod installers (lib/mods/installers/*).
3	 *
4	 * Shape of an install, for every family that uses this engine:
5	 *
6	 *   detect   — look at the server (through a GuestFs) and find WHERE mods go
7	 *              and what game version / loader it actually runs. If the loader
8	 *              the mod needs isn't there, stop here with a plain reason.
9	 *   resolve  — ask the mod's own source for the right build for THIS server
10	 *              (loader + game version), and walk its required dependencies.
11	 *              Declared incompatibilities come back too.
12	 *   download — lib/mods/safe-fetch.ts (allowlisted https, size cap, checksum),
13	 *              from the NX Labs local mirror first when it holds the file.
14	 *   place    — pure: bytes → the exact files to write (archives unpacked by
15	 *              lib/mods/archive.ts with traversal/symlink protection).
16	 *   apply    — lib/mods/engine.ts: conflict check, backup, staged write,
17	 *              rollback on failure, per-server state file on the guest.
18	 *
19	 * None of this ever reports success for a change it did not make.
20	 */
21	import type { Fetcher, Hashes } from "./safe-fetch";
22	import type { GuestFs } from "./guest-fs";
23	
24	/** What the catalogue (GameMod) knows about a mod. Never trusted for paths. */
25	export type CatalogFacts = {
26	  id: string;
27	  gameFamily: string;
28	  slug: string;
29	  name: string;
30	  source: string;
31	  sourceId: string | null;
32	  url: string | null;
33	  category: string;
34	  appliesToVariant: string | null;
35	  loaders: string[];
36	  gameVersions: string[];
37	  serverSide: string | null;
38	};
39	
40	/** What the DB knows about the server (the guest is asked separately in detect). */
41	export type ServerFacts = {
42	  id: string;
43	  family: string;
44	  variant: string | null;
45	  /** VERSION pinned in the server's game config, when it's a real version. */
46	  pinnedVersion: string | null;
47	  config: Record<string, unknown> | null;
48	};
49	
50	export type Layout = {
51	  /** Directory everything for this game lives under; ownership reference. */
52	  base: string;
53	  /** Named target directories (plugins, mods, datapacks, …). */
54	  dirs: Record<string, string>;
55	  /** The game version the server really runs, when it can be read. */
56	  gameVersion: string | null;
57	  /** Loader/flavour actually present (e.g. "oxide" vs "carbon"). */
58	  flavour?: string | null;
59	};
60	
61	export type RemoteFile = {
62	  url: string;
63	  filename: string;
64	  size: number | null;
65	  hashes: Hashes;
66	  /** Lets the NX Labs mirror find its copy (lib/mods/mirror.ts). */
67	  mirrorKey?: { source: string; projectId: string | null; versionId: string | null };
68	  headers?: Record<string, string>;
69	};
70	
71	export type ResolvedPackage = {
72	  /** Unique per server state, e.g. "modrinth:P7dR8mSH", "thunderstore:ValheimModding-Jotunn". */
73	  key: string;
74	  name: string;
75	  version: string;
76	  versionId?: string | null;
77	  file: RemoteFile;
78	  /** Installer-defined placement strategy ("plugin-jar", "mod-jar", "datapack", "bepinex", …). */
79	  placement: string;
80	  /** Keys this package needs. */
81	  requires: string[];
82	  /** Keys that must NOT be installed alongside this one (declared upstream). */
83	  incompatible: { key: string; name: string }[];
84	  /** Bytes already fetched during resolve (e.g. a uMod .cs read for its // Requires: header). */
85	  prefetched?: Buffer;
86	  /** True for the mod the customer asked for; false for pulled-in dependencies. */
87	  root: boolean;
88	};
89	
90	export type Resolution = {
91	  /** Dependency-first order; the last element is the root. */
92	  packages: ResolvedPackage[];
93	  notes: string[];
94	};
95	
96	export type PlacedFile = {
97	  /** Absolute guest path (built with joinUnder — never from raw upstream strings). */
98	  path: string;
99	  data: Buffer;
100	  /** "replace": a file we may overwrite (backed up first), e.g. modpack config overrides. */
101	  overwrite?: "refuse" | "backup";
102	};
103	
104	export type Compat =
105	  | { verdict: "ok"; detail: string }
106	  | { verdict: "mismatch"; detail: string }
107	  | { verdict: "unknown"; detail: string; reason?: "no-list" | "server-unpinned" }
108	  | { verdict: "unsupported"; detail: string };
109	
110	export type InstallerCtx = {
111	  server: ServerFacts;
112	  layout: Layout;
113	  fetcher: Fetcher;
114	};
115	
116	export interface FamilyInstaller {
117	  family: string;
118	  /** GameMod.source values this installer handles. */
119	  sources: readonly string[];
120	  /** One plain sentence: the real mechanism ("Paper plugin jar into plugins/"). */
121	  mechanism: string;
122	  /** Changes only take effect after a restart (TShock, BepInEx…) vs hot-load (Oxide). */
123	  restartRequired: boolean;
124	  /** Catalogue-only compatibility for THIS server (no network) — drives the badge. */
125	  compat(mod: CatalogFacts, server: ServerFacts): Compat;
126	  detect(fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout | { error: string }>;
127	  resolve(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }>;
128	  place(pkg: ResolvedPackage, bytes: Buffer, ctx: InstallerCtx): Promise<PlacedFile[] | { error: string }>;
129	  /** Files an older Nxeon installer placed for this mod before the engine existed. */
130	  legacyPaths?(mod: CatalogFacts, layout: Layout): string[];
131	  /** Post-change config sync (e.g. Factorio mod-list.json). Return files to write. */
132	  configure?(fs: GuestFs, layout: Layout, enabled: { key: string; name: string; version: string }[], all: { key: string; name: string }[]): Promise<PlacedFile[]>;
133	  /** Native enable/disable (config flag) instead of moving files aside. */
134	  nativeToggle?: boolean;
135	  /** Resolve needs the server's real game version (read on the guest when not pinned). */
136	  versionSensitive?: boolean;
137	}
138	
139	export type OpOk = {
140	  ok: true;
141	  version?: string;
142	  restartRequired: boolean;
143	  /** Human list of what changed ("installed LuckPerms 5.5.71", "added dependency Fabric API"). */
144	  changed: string[];
145	  notes: string[];
146	};
147	export type OpResult = OpOk | { ok: false; error: string };
