376	/** Remove a catalogue mod; dependencies go only when nothing else needs them. */
377	export async function uninstall(installer: FamilyInstaller, mod: CatalogFacts, server: ServerFacts, deps: EngineDeps): Promise<OpResult> {
378	  const fs = deps.fs;
379	  try {
380	    await deps.progress?.("Checking your server", 10);
381	    const layout = await detectOrFail(installer, fs, server, mod);
382	    const state = await loadState(fs, server.family);
383	    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));
384	    const removed: string[] = [];
385	    const dropLegacy = async () => {
386	      for (const p of legacy) {
387	        if (ownerOf(state, p)) continue; // the engine owns it now — handled with the package
388	        if (await fs.stat(p)) {
389	          await fs.remove(p);
390	          removed.push(p);
391	        }
392	      }
393	    };
394	    if (!state.roots[mod.id]) {
395	      await dropLegacy();
396	      return {
397	        ok: true,
398	        restartRequired: removed.length > 0 && installer.restartRequired,
399	        changed: removed.length ? [`removed ${mod.name}`] : [],
400	        notes: removed.length ? [] : [`${mod.name} wasn't on the server (nothing to remove).`],
401	      };
402	    }
403	
404	    // Is this mod's package something ANOTHER installed mod needs?
405	    const rootKey = state.roots[mod.id].key;
406	    const blockers = Object.entries(state.roots)
407	      .filter(([id, r]) => id !== mod.id && r.key !== rootKey && state.packages[r.key]?.requires.includes(rootKey))
408	      .map(([, r]) => r.name);
409	    if (blockers.length) return { ok: false, error: `${blockers.join(", ")} need${blockers.length === 1 ? "s" : ""} ${mod.name} — remove ${blockers.length === 1 ? "it" : "them"} first.` };
410	
411	    await deps.progress?.(`Removing ${mod.name}`, 50);
412	    await dropLegacy();
413	    delete state.roots[mod.id];
414	    const gone: string[] = [];
415	    for (const p of Object.values(state.packages)) {
416	      p.roots = p.roots.filter((r) => r !== mod.id);
417	      // A package another mod still installed as its own root stays.
418	      const stillRoot = Object.values(state.roots).some((r) => r.key === p.key);
419	      if (p.roots.length === 0 && !stillRoot) gone.push(p.key);
420	    }
421	    for (const key of gone) {
422	      const p = state.packages[key];
423	      delete state.packages[key];
424	      for (const f of p.files) {
425	        if (ownerOf(state, f.path)) continue; // shared identical file still needed
426	        const at = p.disabled ? disabledPath(p.key, f.path) : f.path;
427	        await fs.remove(at);
428	      }
429	      if (p.disabled) await fs.remove(`${DISABLED_DIR}/${safeKey(p.key)}`);
430	      await removeEmptyParents(fs, p.files.map((f) => f.path), layout);
431	      removed.push(p.name);
432	    }
433	    if (installer.configure) {
434	      for (const e of await installer.configure(fs, layout, enabledList(state), allList(state))) {
435	        if (!isWithin(layout.base, e.path)) continue;
436	        await fs.writeFile(`${e.path}.nxeon-part`, e.data);
437	        await fs.rename(`${e.path}.nxeon-part`, e.path);
438	      }
439	    }
440	    await saveState(fs, state);
441	    const extra = gone.length - 1;
442	    return {
443	      ok: true,
444	      restartRequired: installer.restartRequired,
445	      changed: [`removed ${mod.name}`, ...(extra > 0 ? [`also removed ${extra} dependenc${extra === 1 ? "y" : "ies"} nothing else needed`] : [])],
446	      notes: [],
447	    };
448	  } catch (e) {
449	    return failure(e);
450	  }
451	}
