453	/** Remove now-empty directories we created, never above the layout's named dirs. */
454	async function removeEmptyParents(fs: GuestFs, files: string[], layout: Layout) {
455	  const stops = new Set([layout.base, ...Object.values(layout.dirs)]);
456	  const dirs = new Set<string>();
457	  for (const f of files) {
458	    let d = f.split("/").slice(0, -1).join("/");
459	    while (d && !stops.has(d) && isWithin(layout.base, d)) {
460	      dirs.add(d);
461	      d = d.split("/").slice(0, -1).join("/");
462	    }
463	  }
464	  for (const d of [...dirs].sort((a, b) => b.length - a.length)) {
465	    if ((await fs.list(d)).length === 0) await fs.remove(d);
466	  }
467	}
