1	/**
2	 * Valheim — BepInEx plugins from Thunderstore.
3	 *
4	 * Server: lloesche/valheim-server (prisma/catalog.ts), `-v /opt/valheim/config:/config`.
5	 * With the BepInEx server type (`BEPINEX=true`, worker/game-config.ts) the image
6	 * itself copies /config/bepinex/plugins into its BepInEx install on every
7	 * start — that folder is the documented drop point, and the only one this
8	 * installer writes to. BepInEx loads plugin DLLs recursively, so each package
9	 * gets its own `<Namespace>-<Name>` folder (the r2modman/Thunderstore
10	 * convention), which is also what makes uninstall exact.
11	 *
12	 * Package layout (Thunderstore's documented structure): manifest.json,
13	 * icon.png, README.md at the root, and the payload either at the root, under
14	 * `plugins/`, or under `BepInEx/plugins/`. Everything that isn't plugin
15	 * payload is handled explicitly:
16	 *   - `config/` defaults are skipped (BepInEx writes a config on first run);
17	 *   - `patchers/`, `core/`, `monomod/` need BepInEx's preloader folders, which
18	 *     this server type doesn't sync from /config — such packages are refused
19	 *     with that reason rather than installed half-working;
20	 *   - BepInExPack (the loader itself) is never installed: the server image
21	 *     provides BepInEx.
22	 *
23	 * Dependencies come from the package's own declared list (exact versions, as
24	 * the author pinned them). Thunderstore publishes no file checksum in its API,
25	 * so downloads are size-capped, zip-validated and recorded with our own sha256.
26	 */
27	import { readZip, ArchiveError } from "../archive";
28	import { fetchJson } from "../safe-fetch";
29	import { joinUnder, isSafeSegment } from "../paths";
30	import type { CatalogFacts, Compat, FamilyInstaller, InstallerCtx, PlacedFile, ResolvedPackage, ServerFacts } from "../types";
31	
32	const TS = "https://thunderstore.io/api/experimental/package";
33	const VALHEIM_PLUGINS = "/opt/valheim/config/bepinex/plugins";
34	
35	type TsVersion = { namespace: string; name: string; version_number: string; full_name: string; download_url: string; dependencies: string[]; file_size?: number; is_active?: boolean };
36	type TsPackage = { namespace: string; name: string; full_name: string; is_deprecated?: boolean; latest: TsVersion };
37	
38	/** "Author-Name-1.2.3" → parts. Names may contain dashes? Thunderstore forbids them in name/namespace. */
39	export function parseDepString(s: string): { namespace: string; name: string; version: string } | null {
40	  const m = /^([A-Za-z0-9_]+)-([A-Za-z0-9_]+)-(\d+\.\d+\.\d+)$/.exec(s.trim());
41	  return m ? { namespace: m[1], name: m[2], version: m[3] } : null;
42	}
43	
44	export function isLoaderPack(namespace: string, name: string): boolean {
45	  return /bepinexpack/i.test(name) || (namespace === "denikson" && /bepinex/i.test(name));
46	}
47	
48	/**
49	 * Map a Thunderstore package's files to BepInEx plugin files under
50	 * `<pluginsDir>/<folder>/`. Pure; exported for the fixture tests.
51	 */
52	export function bepinexPlacement(entries: { path: string[]; dir: boolean; data: Buffer }[], pluginsDir: string, folder: string): PlacedFile[] | { error: string } {
53	  if (!isSafeSegment(folder)) return { error: "unsafe package folder name" };
54	  const META = new Set(["manifest.json", "icon.png", "readme.md", "changelog.md", "license", "license.md", "license.txt"]);
55	  const out: PlacedFile[] = [];
56	  for (const e of entries) {
57	    if (e.dir) continue;
58	    let segs = e.path;
59	    const lower = segs.map((s) => s.toLowerCase());
60	    if (segs.length === 1 && META.has(lower[0])) continue;
61	    if (lower[0] === "bepinex") { segs = segs.slice(1); lower.shift(); }
62	    const top = lower[0];
63	    if (["patchers", "core", "monomod"].includes(top)) {
64	      return { error: `this package needs BepInEx ${top}/ files, which this server type can't load from the plugins folder` };
65	    }
66	    if (top === "config") continue; // defaults: BepInEx generates the real config on first run
67	    if (top === "plugins") segs = segs.slice(1);
68	    if (segs.length === 0) continue;
69	    out.push({ path: joinUnder(pluginsDir, [folder, ...segs]), data: e.data });
70	  }
71	  return out;
72	}
