74	export const valheimInstaller: FamilyInstaller = {
75	  family: "valheim",
76	  sources: ["thunderstore"],
77	  mechanism: "BepInEx plugins from Thunderstore into /opt/valheim/config/bepinex/plugins/<Author-Name>/ (the image syncs them into BepInEx on start).",
78	  restartRequired: true,
79	
80	  compat(_mod: CatalogFacts, server: ServerFacts): Compat {
81	    if ((server.variant ?? "vanilla") !== "bepinex") {
82	      return { verdict: "mismatch", detail: "Mods need the BepInEx server type — switch it in Settings (your world is kept)." };
83	    }
84	    return { verdict: "unknown", reason: "no-list", detail: "Thunderstore doesn't publish a game-version list; mods load against the current Valheim build." };
85	  },
86	
87	  async detect(fs, server) {
88	    if ((server.variant ?? "vanilla") !== "bepinex") return { error: "Mods need the BepInEx server type. Switch to it in Settings (your world is kept), then install." };
89	    if ((await fs.stat("/opt/valheim/config"))?.type !== "dir") return { error: "Couldn't find this server's Valheim config folder — is the server fully set up?" };
90	    await fs.mkdirp(VALHEIM_PLUGINS);
91	    return { base: "/opt/valheim/config", dirs: { plugins: VALHEIM_PLUGINS }, gameVersion: null };
92	  },
93	
94	  async resolve(mod, ctx: InstallerCtx) {
95	    const id = (mod.sourceId ?? "").trim();
96	    const [ns, ...rest] = id.split("-");
97	    if (!ns || rest.length !== 1) return { error: "This Thunderstore entry has no valid Author-Name id." };
98	    const notes: string[] = [];
99	    const order: ResolvedPackage[] = [];
100	    const seen = new Set<string>();
101	    const visit = async (namespace: string, name: string, version: string | null, isRoot: boolean, depth: number): Promise<string | null> => {
102	      const k = `${namespace}-${name}`.toLowerCase();
103	      if (seen.has(k)) return null;
104	      seen.add(k);
105	      if (isLoaderPack(namespace, name)) {
106	        notes.push("BepInEx itself is provided by your server — not installed separately.");
107	        return null;
108	      }
109	      if (seen.size > 40) return "This mod pulls in more than 40 dependencies — too many for one click.";
110	      let v: TsVersion;
111	      try {
112	        if (version) v = await fetchJson<TsVersion>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/${encodeURIComponent(version)}/`);
113	        else {
114	          const p = await fetchJson<TsPackage>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/`);
115	          if (p.is_deprecated && isRoot) notes.push(`${p.full_name} is marked deprecated by its author.`);
116	          v = p.latest;
117	        }
118	      } catch {
119	        return isRoot ? `Couldn't find ${mod.name} on Thunderstore (it may have been removed).` : `${mod.name} needs ${namespace}-${name}${version ? ` ${version}` : ""}, which couldn't be found on Thunderstore.`;
120	      }
121	      const requires: string[] = [];
122	      if (depth < 6) {
123	        for (const d of v.dependencies ?? []) {
124	          const dep = parseDepString(d);
125	          if (!dep) return `${v.full_name} declares a dependency we can't parse (${d}).`;
126	          const e = await visit(dep.namespace, dep.name, dep.version, false, depth + 1);
127	          if (e) return e;
128	          if (!isLoaderPack(dep.namespace, dep.name)) requires.push(`thunderstore:${dep.namespace}-${dep.name}`);
129	        }
130	      }
131	      order.push({
132	        key: `thunderstore:${v.namespace}-${v.name}`,
133	        name: isRoot ? mod.name : `${v.namespace}-${v.name}`,
134	        version: v.version_number,
135	        versionId: v.full_name,
136	        file: { url: v.download_url, filename: `${v.full_name}.zip`, size: v.file_size ?? null, hashes: {}, mirrorKey: { source: "thunderstore", projectId: `${v.namespace}-${v.name}`, versionId: v.version_number } },
137	        placement: "bepinex",
138	        requires,
139	        incompatible: [],
140	        root: isRoot,
141	      });
142	      return null;
143	    };
144	    const err = await visit(ns, rest[0], null, true, 0);
145	    if (err) return { error: err };
146	    if (!order.length) return { error: `${mod.name} is the mod loader itself — your server already provides BepInEx.` };
147	    notes.push("Thunderstore doesn't publish checksums; downloads are size-capped and archive-checked.");
148	    return { packages: order, notes };
149	  },
150	
151	  async place(pkg, bytes, ctx) {
152	    let entries;
153	    try {
154	      entries = readZip(bytes);
155	    } catch (e) {
156	      return { error: `${pkg.name} isn't a valid Thunderstore package (${e instanceof ArchiveError ? e.message : "unreadable"}).` };
157	    }
158	    const folder = pkg.key.replace(/^thunderstore:/, "");
159	    const r = bepinexPlacement(entries, ctx.layout.dirs.plugins, folder);
160	    if ("error" in r) return { error: `${pkg.name}: ${r.error}.` };
161	    return r;
162	  },
163	
164	  legacyPaths(mod, layout) {
165	    // Pre-engine installer: whole package unzipped into plugins/nxeon-<slug>/.
166	    if (!/^[a-z0-9][a-z0-9._-]*$/i.test(mod.slug)) return [];
167	    return [`${layout.dirs.plugins}/nxeon-${mod.slug}`];
168	  },
169	};
