27	const MODRINTH = "https://api.modrinth.com/v2";
28	const PLUGIN_VARIANTS = ["paper", "purpur", "spigot", "bukkit", "folia"];
29	const MOD_VARIANTS = ["fabric", "quilt", "forge", "neoforge"];
