31	/** Which Modrinth loader tags a server variant can actually load, best first. */
32	export function acceptedLoaders(variant: string | null): string[] {
33	  switch ((variant ?? "vanilla").toLowerCase()) {
34	    case "paper": return ["paper", "spigot", "bukkit"];
35	    case "purpur": return ["purpur", "paper", "spigot", "bukkit"];
36	    case "spigot": return ["spigot", "bukkit"];
37	    case "bukkit": return ["bukkit"];
38	    case "folia": return ["folia"];
39	    case "fabric": return ["fabric"];
40	    case "quilt": return ["quilt", "fabric"];
41	    case "forge": return ["forge"];
42	    case "neoforge": return ["neoforge"];
43	    default: return [];
44	  }
45	}
46	
47	export function isPluginVariant(v: string | null) { return PLUGIN_VARIANTS.includes((v ?? "").toLowerCase()); }
48	export function isModVariant(v: string | null) { return MOD_VARIANTS.includes((v ?? "").toLowerCase()); }
