50	const CLIENT_ONLY_CATEGORIES = ["resource packs", "shaders", "resourcepack", "shader"];
51	
52	export function mcCompat(mod: CatalogFacts, server: ServerFacts): Compat {
53	  const cat = mod.category.toLowerCase();
54	  if (CLIENT_ONLY_CATEGORIES.includes(cat)) return { verdict: "unsupported", detail: "Resource packs and shaders run on players' own game, not on the server." };
55	  if (mod.serverSide === "unsupported") return { verdict: "unsupported", detail: "This is a client-side mod — it does nothing on a server." };
56	  const variant = (server.variant ?? "vanilla").toLowerCase();
57	  const loaders = mod.loaders.map((l) => l.toLowerCase());
58	  const accepted = acceptedLoaders(variant);
59	  const isPack = cat === "modpacks";
60	  const isDatapack = cat === "datapacks" || (loaders.length > 0 && loaders.every((l) => l === "datapack"));
61	  if (mod.appliesToVariant && mod.appliesToVariant !== variant && !accepted.includes(mod.appliesToVariant)) {
62	    return { verdict: "mismatch", detail: `Needs a ${mod.appliesToVariant} server — yours runs ${variant}. Change the server type in Settings.` };
63	  }
64	  if (!isDatapack && !isPack && loaders.length) {
65	    const ok = loaders.some((l) => accepted.includes(l)) || (loaders.includes("datapack"));
66	    if (!ok) {
67	      const want = loaders.filter((l) => [...PLUGIN_VARIANTS, ...MOD_VARIANTS].includes(l)).slice(0, 3).join(" / ") || loaders.slice(0, 3).join(" / ");
68	      return { verdict: "mismatch", detail: `Built for ${want} — your server runs ${variant}. Change the server type in Settings to use it.` };
69	    }
70	  }
71	  if (isPack && loaders.length && !loaders.some((l) => l === variant || accepted.includes(l))) {
72	    return { verdict: "mismatch", detail: `This modpack is built for ${loaders.slice(0, 2).join(" / ")} — your server runs ${variant}.` };
73	  }
74	  if (variant === "vanilla" && !isDatapack && !loaders.includes("datapack")) {
75	    return { verdict: "mismatch", detail: "Vanilla servers can only load datapacks. Switch to Paper (plugins) or Fabric/Forge (mods) in Settings." };
76	  }
77	  const gv = server.pinnedVersion;
78	  if (!mod.gameVersions.length) return { verdict: "unknown", reason: "no-list", detail: "The source doesn't publish a supported-version list — we check at install time." };
79	  if (!gv) return { verdict: "unknown", reason: "server-unpinned", detail: "Your server isn't pinned to a version; we'll read the real version at install time." };
80	  if (mod.gameVersions.includes(gv)) return { verdict: "ok", detail: `Supports ${gv} on ${variant}.` };
81	  return { verdict: "mismatch", detail: `No build listed for ${gv} — the source lists ${newest(mod.gameVersions) ?? "other versions"}.` };
82	}
