93	export function parseProperties(text: string): Record<string, string> {
94	  const out: Record<string, string> = {};
95	  for (const line of text.split(/\r?\n/)) {
96	    const t = line.trim();
97	    if (!t || t.startsWith("#")) continue;
98	    const i = t.indexOf("=");
99	    if (i > 0) out[t.slice(0, i).trim()] = t.slice(i + 1).trim();
100	  }
101	  return out;
102	}
103	
104	export function versionFromLog(log: string): string | null {
105	  const m = /Starting minecraft server version ([0-9][0-9A-Za-z.\-+ ]*?)\s*$/m.exec(log);
106	  return m ? m[1].trim() : null;
107	}
