109	async function detect(fs: GuestFs, server: ServerFacts): Promise<Layout | { error: string }> {
110	  let base: string | null = null;
111	  for (const c of ROOT_CANDIDATES) {
112	    if ((await fs.stat(`${c}/server.properties`))?.type === "file") { base = c; break; }
113	  }
114	  if (!base) return { error: "Couldn't find this server's Minecraft folder (no server.properties yet) — start the server once, then try again." };
115	  const props = parseProperties((await fs.readFile(`${base}/server.properties`, 1024 * 1024))?.toString("utf8") ?? "");
116	  const levelSegs = normalizeRel(props["level-name"] || "world");
117	  if (!levelSegs) return { error: "This server's level-name isn't a folder name we can safely write into." };
118	  let gameVersion = server.pinnedVersion;
119	  if (!gameVersion) {
120	    const log = await fs.readFile(`${base}/logs/latest.log`, 32 * 1024 * 1024);
121	    gameVersion = log ? versionFromLog(log.toString("utf8")) : null;
122	  }
123	  return {
124	    base,
125	    dirs: { plugins: `${base}/plugins`, mods: `${base}/mods`, datapacks: joinUnder(base, [...levelSegs, "datapacks"]), root: base },
126	    gameVersion,
127	    flavour: (server.variant ?? "vanilla").toLowerCase(),
128	  };
129	}
