149	/** Newest release first; beta/alpha only when nothing stable matches. */
150	export function pickModrinthVersion(versions: MrVersion[], loaders: string[], gameVersion: string | null): MrVersion | null {
151	  const ok = versions.filter((v) => (!loaders.length || v.loaders.some((l) => loaders.includes(l))) && (!gameVersion || v.game_versions.includes(gameVersion)) && v.files.length > 0);
152	  const rank = (v: MrVersion) => (v.version_type === "release" ? 0 : v.version_type === "beta" ? 1 : 2);
153	  // Best loader first (a Paper build over a Bukkit one over a datapack build).
154	  const lrank = (v: MrVersion) => (loaders.length ? Math.min(...v.loaders.map((l) => (loaders.includes(l) ? loaders.indexOf(l) : 99))) : 0);
155	  // Modrinth already returns newest first; keep that order within a rank.
156	  return ok.map((v, i) => ({ v, i })).sort((a, b) => lrank(a.v) - lrank(b.v) || rank(a.v) - rank(b.v) || a.i - b.i)[0]?.v ?? null;
157	}
