159	function placementFor(v: MrVersion, project: MrProject, variant: string): string {
160	  if (project.project_type === "modpack") return "mrpack";
161	  if (project.project_type === "datapack" || (v.loaders.length === 1 && v.loaders[0] === "datapack")) return "datapack";
162	  if (isPluginVariant(variant)) return "plugin-jar";
163	  if (isModVariant(variant)) return v.loaders.includes("datapack") && !v.loaders.some((l) => acceptedLoaders(variant).includes(l)) ? "datapack" : "mod-jar";
164	  return "datapack";
165	}
