167	async function resolveModrinth(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
168	  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
169	  const gv = ctx.layout.gameVersion;
170	  const notes: string[] = [];
171	  const out = new Map<string, ResolvedPackage>();
172	  const order: string[] = [];
173	  const seen = new Set<string>();
174	
175	  const visit = async (projectId: string, pinnedVersionId: string | null, depth: number, isRoot: boolean): Promise<string | null> => {
176	    if (seen.has(projectId)) return null;
177	    seen.add(projectId);
178	    if (out.size >= 40) return "This mod pulls in more than 40 dependencies — too many to install in one click.";
179	    let project: MrProject;
180	    try {
181	      project = await fetchJson<MrProject>(ctx.fetcher, `${MODRINTH}/project/${encodeURIComponent(projectId)}`);
182	    } catch {
183	      return isRoot ? `Couldn't find ${mod.name} on Modrinth (it may have been removed).` : `A required dependency (${projectId}) couldn't be found on Modrinth.`;
184	    }
185	    if (project.server_side === "unsupported") {
186	      if (isRoot) return `${project.title} is client-side only — it does nothing on a server.`;
187	      notes.push(`Skipped ${project.title}: client-side only.`);
188	      return null;
189	    }
190	    const isPack = project.project_type === "modpack";
191	    const isDp = project.project_type === "datapack";
192	    const loaders = isPack ? [] : isDp ? ["datapack"] : [...acceptedLoaders(variant), "datapack"];
193	    if (!isPack && !isDp && acceptedLoaders(variant).length === 0) {
194	      // Vanilla: datapack builds only.
195	      loaders.splice(0, loaders.length, "datapack");
196	    }
197	    if (!gv) return `Couldn't tell which Minecraft version this server runs — pin a version in Settings (or start the server once), then try again.`;
198	
199	    let v: MrVersion | null = null;
200	    if (pinnedVersionId) {
201	      try {
202	        const pv = await fetchJson<MrVersion>(ctx.fetcher, `${MODRINTH}/version/${encodeURIComponent(pinnedVersionId)}`);
203	        v = pickModrinthVersion([pv], isPack ? [] : loaders, gv);
204	      } catch { /* fall back to the newest compatible below */ }
205	    }
206	    if (!v) {
207	      const q = `${MODRINTH}/project/${encodeURIComponent(project.id)}/version?${loaders.length ? `loaders=${enc(loaders)}&` : ""}${gv ? `game_versions=${enc([gv])}` : ""}`;
208	      let versions: MrVersion[] = [];
209	      try {
210	        versions = await fetchJson<MrVersion[]>(ctx.fetcher, q);
211	      } catch {
212	        return `Modrinth didn't answer for ${project.title} — try again in a minute.`;
213	      }
214	      v = pickModrinthVersion(versions, isPack ? [] : loaders, gv);
215	    }
216	    if (!v) {
217	      const what = isPack ? "" : ` on ${variant}`;
218	      return isRoot
219	        ? `${project.title} has no build for Minecraft ${gv ?? "(unknown)"}${what} — nothing was installed.`
220	        : `${mod.name} needs ${project.title}, which has no build for Minecraft ${gv ?? "(unknown)"}${what} — nothing was installed.`;
221	    }
222	    if (isPack && !isRoot) return `${mod.name} depends on a modpack (${project.title}), which can't be installed as a dependency.`;
223	
224	    const placement = placementFor(v, project, variant);
225	    if (placement === "datapack" && !isDp && !v.loaders.includes("datapack") && !isRoot) {
226	      notes.push(`Skipped ${project.title}: no ${variant} build.`);
227	      return null;
228	    }
229	    const file = v.files.find((f) => f.primary) ?? v.files[0];
230	    const key = `modrinth:${project.id}`;
231	    const requires: string[] = [];
232	    const incompatible: { key: string; name: string }[] = [];
233	    if (depth < 6) {
234	      for (const d of v.dependencies) {
235	        if (!d.project_id && d.version_id) {
236	          try {
237	            const dv = await fetchJson<MrVersion>(ctx.fetcher, `${MODRINTH}/version/${encodeURIComponent(d.version_id)}`);
238	            d.project_id = dv.project_id;
239	          } catch { /* unresolvable; handled below */ }
240	        }
241	        if (!d.project_id) {
242	          if (d.dependency_type === "required") return `${project.title} requires a dependency Modrinth can't identify — nothing was installed.`;
243	          continue;
244	        }
245	        if (d.dependency_type === "incompatible") incompatible.push({ key: `modrinth:${d.project_id}`, name: d.project_id });
246	        if (d.dependency_type !== "required") continue;
247	        const err = await visit(d.project_id, d.version_id, depth + 1, false);
248	        if (err) return err;
249	        if (out.has(`modrinth:${d.project_id}`)) requires.push(`modrinth:${d.project_id}`);
250	      }
251	    }
252	    out.set(key, {
253	      key,
254	      name: project.title,
255	      version: v.version_number,
256	      versionId: v.id,
257	      file: { url: file.url, filename: file.filename, size: file.size ?? null, hashes: { sha1: file.hashes.sha1, sha512: file.hashes.sha512 }, mirrorKey: { source: "modrinth", projectId: project.id, versionId: v.id } },
258	      placement,
259	      requires,
260	      incompatible,
261	      root: isRoot,
262	    });
263	    order.push(key);
264	    return null;
265	  };
266	
267	  const err = await visit(mod.sourceId || mod.slug, null, 0, true);
268	  if (err) return { error: err };
269	  // `order` is post-order: dependencies before dependents, root last.
270	  const root = order[order.length - 1];
271	  const packages = order.filter((k) => k !== root).map((k) => out.get(k)!).concat(out.get(root)!);
272	  return { packages, notes };
273	}
