383	/** Check a modpack's declared loader + MC version against the server. */
384	export function checkMrpackDeps(deps: Record<string, string>, variant: string, gameVersion: string | null): string | null {
385	  const mc = deps["minecraft"];
386	  const loader = Object.entries(LOADER_DEP).find(([, k]) => k in deps)?.[0] ?? null;
387	  if (!loader) return "This modpack doesn't declare a mod loader we can run (Fabric, Quilt, Forge or NeoForge).";
