396	async function placeMrpack(pkg: ResolvedPackage, bytes: Buffer, ctx: InstallerCtx): Promise<PlacedFile[] | { error: string }> {
397	  const entries = fileMap(readZip(bytes));
398	  const idxRaw = entries.get("modrinth.index.json");
399	  if (!idxRaw) return { error: "This modpack file has no modrinth.index.json." };
400	  let idx: MrIndex;
401	  try {
402	    idx = JSON.parse(idxRaw.toString("utf8"));
403	  } catch {
404	    return { error: "This modpack's index isn't valid JSON." };
405	  }
406	  if (idx.formatVersion !== 1 || idx.game !== "minecraft") return { error: "Unsupported modpack format." };
407	  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
408	  const depErr = checkMrpackDeps(idx.dependencies ?? {}, variant, ctx.layout.gameVersion);
409	  if (depErr) return { error: depErr };
410	  const base = ctx.layout.base;
411	  const files = (idx.files ?? []).filter((f) => (f.env?.server ?? "required") !== "unsupported");
412	  if (files.length > MAX_PACK_FILES) return { error: `This modpack has ${files.length} server files — more than one click can safely handle.` };
413	  const declared = files.reduce((s, f) => s + (f.fileSize ?? 0), 0);
414	  if (declared > MAX_PACK_BYTES) return { error: `This modpack is ${Math.round(declared / 1048576)} MB of server files — over the ${MAX_PACK_BYTES / 1048576} MB one-click limit.` };
415	
416	  const out: PlacedFile[] = [];
417	  const seen = new Set<string>();
418	  for (const f of files) {
419	    const segs = normalizeRel(f.path);
420	    if (!segs) return { error: `This modpack lists an unsafe path (${String(f.path).slice(0, 80)}) — refused.` };
421	    if (!f.hashes?.sha1 && !f.hashes?.sha512) return { error: `This modpack lists ${f.path} without a checksum — refused.` };
422	    const url = (f.downloads ?? []).find((u) => {
423	      try { validateUrl(u, MRPACK_DL_HOSTS); return true; } catch { return false; }
424	    });
425	    if (!url) return { error: `${f.path} in this modpack is only available from a host we don't download from.` };
426	    const r = await ctx.fetcher(url, { maxBytes: 128 * 1024 * 1024, expect: { sha1: f.hashes.sha1, sha512: f.hashes.sha512 }, allow: MRPACK_DL_HOSTS });
427	    const path = joinUnder(base, segs);
428	    seen.add(path);
429	    out.push({ path, data: r.bytes });
430	  }
431	  // overrides/ then server-overrides/ (the latter wins), per the .mrpack spec.
432	  for (const prefix of ["overrides/", "server-overrides/"]) {
433	    for (const [name, data] of entries) {
434	      if (!name.startsWith(prefix)) continue;
435	      const rel = name.slice(prefix.length);
436	      if (!rel) continue;
437	      const path = joinUnder(base, rel);
438	      const i = out.findIndex((x) => x.path === path);
439	      const pf: PlacedFile = { path, data, overwrite: "backup" };
440	      if (i >= 0) out[i] = pf; else out.push(pf);
441	    }
442	  }
443	  void pkg;
444	  return out;
445	}
