449	/**
450	 * Jars and datapack zips are placed AS ONE FILE — we never extract them, so
451	 * their internal names (Java's `Outer$Inner.class`, `META-INF/versions/9/…`)
452	 * never touch the filesystem. They still have to BE what they claim: a real
453	 * ZIP container (an HTML error page or an installer .exe is refused), and a
454	 * datapack must carry a pack.mcmeta.
455	 */
456	export function placeJarOrDatapack(pkg: ResolvedPackage, bytes: Buffer, layout: Layout): PlacedFile[] | { error: string } {
457	  if (pkg.placement === "datapack") {
458	    const name = safeFileName(pkg.file.filename, [".zip"]);
459	    if (!name) return { error: `${pkg.name}'s file isn't a datapack .zip.` };
460	    let names: string[];
461	    try { names = zipEntryNames(bytes, JAR_LIMITS); } catch (e) { return { error: `${pkg.name}'s datapack is not a valid zip: ${(e as Error).message}` }; }
462	    if (!names.some((n) => /^([^/]+\/)?pack\.mcmeta$/.test(n))) return { error: `${pkg.name}'s zip has no pack.mcmeta — not a datapack.` };
463	    return [{ path: joinUnder(layout.dirs.datapacks, name), data: bytes }];
464	  }
465	  const name = safeFileName(pkg.file.filename, [".jar"]);
466	  if (!name) return { error: `${pkg.name}'s download isn't a .jar file — refused.` };
467	  let names: string[];
468	  try {
469	    names = zipEntryNames(bytes, JAR_LIMITS);
470	  } catch (e) {
471	    return { error: `${pkg.name}'s download isn't a valid jar (${e instanceof ArchiveError ? e.message : "unreadable"}) — refused.` };
472	  }
473	  if (pkg.placement === "plugin-jar" && !names.some((n) => /^(plugin|paper-plugin|bungee)\.yml$/.test(n))) {
474	    return { error: `${pkg.name}'s jar has no plugin.yml — it isn't a Bukkit/Paper plugin.` };
475	  }
476	  if (pkg.placement === "mod-jar" && !names.some((n) => /^(fabric\.mod\.json|quilt\.mod\.json|META-INF\/mods\.toml|META-INF\/neoforge\.mods\.toml|mcmod\.info)$/.test(n))) {
477	    return { error: `${pkg.name}'s jar has no Fabric/Quilt/Forge mod manifest — it isn't a server mod.` };
478	  }
479	  const dir = pkg.placement === "plugin-jar" ? layout.dirs.plugins : layout.dirs.mods;
480	  return [{ path: joinUnder(dir, name), data: bytes }];
481	}
