90	export async function gameUpdate(job: Job): Promise<void> {
91	  const server = await loadGameServer(job.serverId!);
92	  if (SANDBOX) {
93	    // No VM exists, so nothing can be proven. Say that, rather than simulating a
94	    // success message the production path is no longer willing to send.
95	    await notify(
96	      server.userId,
97	      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
98	      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
99	      `/dashboard/servers/${server.id}`
100	    );
101	    return;
102	  }
103	  const family = server.osTemplate.family as GameFamily;
104	  if (!GAME_FAMILIES.includes(family)) {
105	    throw new Error(`game update: ${server.hostname} is not a game server`);
106	  }
107	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
108	  const password = serverRootPassword(server);
109	  if (!connectionTarget(server) || !password) {
110	    throw new Error("game update: server has no IP/password yet");
111	  }
112	  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
113	  const href = `/dashboard/servers/${server.id}`;
114	
115	  // A real version bump, where one exists (lib/game-update-verify.ts autoUpdatePlan).
116	  const payload = (job.payload ?? {}) as { manual?: boolean };
117	  const values = validateConfig(server.gamePlan?.gameFamily ?? family, (server.gameConfig as Record<string, unknown> | null) ?? {});
118	  const plan = autoUpdatePlan({
119	    family: server.gamePlan?.gameFamily ?? family,
120	    variant: server.gameVariant ?? schemaFor(family)?.defaultVariant ?? null,
121	    config: values.ok ? values.values : null,
122	    curated: curatedVersionsFor(server.gamePlan?.gameFamily ?? family),
123	  });
124	  if (plan.kind === "bump" && (payload.manual || (server.autoUpdate && !AUTO_UPDATE_DISABLED))) {
125	    return versionBump(job, server, family, plan, values.ok ? values.values : {}, href);
126	  }
127	
128	  const remote = updateCommand(family);
129	  let stdout = "";
130	  let connError: string | null = null;
131	  try {
132	    // Host/port come from connectionTarget() (dedicated IP, or this server's
133	    // OWN node's public IP + its NAT-forwarded sshPort) — never the guest's
134	    // private bridge IP, which the worker has no route to for a non-primary node.
135	    const r = await withServerSsh(server, (conn) => sshExecOn(conn, remote, 600_000));
136	    stdout = r.stdout;
137	  } catch (e: any) {
138	    connError = scrub(String(e?.message ?? e));
139	  }
140	
141	  // A non-zero exit (or a connection failure) is meaningful, but the markers may
142	  // still have been printed before whatever went wrong — check for them
143	  // regardless of how we got here and let the verdict decide, rather than
144	  // discarding evidence. Absence of the end marker is ALWAYS treated as an
145	  // unproven run, exit code notwithstanding — a clean SSH exit is not evidence.
146	  if (connError || !/^NXGU:END$/m.test(stdout)) {
147	    const detail = connError ?? (scrub(stdout).trim() || "no output — the update did not run to completion");
148	    const reason = `game update failed: ${detail}`;
149	    await notifyFailureOnce(
150	      server.userId,
151	      server.id,
152	      `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
153	      `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
154	      href
155	    );
156	    throw new Error(reason);
157	  }
158	
159	  const facts = parseGameUpdateOutput(scrub(stdout));
160	  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });
161	
162	  if (!verdict.ok) {
163	    await notifyFailureOnce(
164	      server.userId,
165	      server.id,
166	      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
167	      verdict.reason,
168	      href
169	    );
170	    // Failing the job is the point: it puts the reason in Job.error and in the
171	    // admin job list instead of leaving a green tick over a dead server.
172	    throw new Error(`game update not verified: ${verdict.reason}`);
173	  }
174	
175	  // Only a real change is an event. This runs every 6 hours, so notifying on
176	  // every pass produced four "<game> updated on <host>" messages a day for a
177	  // server where nothing had been updated — the same erosion `notifyFailureOnce`
178	  // exists to prevent, and with a title that was not true.
179	  if (verdict.notify) await notify(server.userId, verdict.title, verdict.body, href);
180	  else console.log(`[game-update] ${server.hostname}: ${verdict.title} — ${verdict.body}`);
181	  await recordUpdateResult(server.id, `${verdict.title}.${plan.kind === "current" ? " Already on the newest supported version." : ""}`);
182	}
