196	/**
197	 * Move a pinned VERSION to the newest platform-supported one — safely.
198	 *
199	 *  1. Only when the game is RUNNING right now (a stopped server is left alone;
200	 *     updating it would mean starting it, which the owner did not ask for).
201	 *  2. World backup FIRST, into GAME_BACKUP_DIR (the same archive "Back up now"
202	 *     makes, downloadable from Manage → Worlds). No backup → no update.
203	 *  3. Apply through the family's verified real-apply path
204	 *     (worker/game-config.ts applyMinecraft/applyBedrock), which recreates the
205	 *     container on the new VERSION — and the right Java image for it.
206	 *  4. Verify the game really answers again (port check on the public path).
207	 *  5. If it does not: put the previous VERSION back the same way and say so —
208	 *     the backup taken in step 2 is named in the message for a full restore.
209	 * Every step is logged (AuditLog + GameRuntime.lastUpdateResult) and the
210	 * customer is told exactly what changed.
211	 */
212	async function versionBump(
213	  job: Job,
214	  server: LoadedServer,
215	  family: GameFamily,
216	  plan: Extract<AutoUpdatePlan, { kind: "bump" }>,
217	  values: Record<string, string | number | boolean>,
218	  href: string
219	): Promise<void> {
220	  const name = schemaFor(family)?.label ?? family;
221	  const spec = controlSpec(family);
222	  if (!spec) throw new Error(`game update: no control spec for ${family}`);
223	  const rt = (await db.server.findUnique({ where: { id: server.id }, select: RUNTIME_SERVER_SELECT })) as RuntimeServer | null;
224	  const pre = rt ? await probeGameRuntime(rt, { external: false }) : null;
225	  if (serviceRunning(pre?.probe) !== true) {
226	    const msg = `Skipped the ${name} update ${plan.from} → ${plan.to}: your server isn't running, and updating it would mean starting it. Start it and the next check will update it.`;
227	    await recordUpdateResult(server.id, msg);
228	    console.log(`[game-update] ${server.hostname}: ${msg}`);
229	    return;
230	  }
231	
232	  const backup = await createWorldBackup(server as unknown as SftpServer, spec, "pre-update").catch((e) => ({ ok: false as const, msg: String(e?.message ?? e) }));
233	  if (!backup.ok) {
234	    const msg = `Did NOT update ${name} ${plan.from} → ${plan.to}: the safety backup of your world failed (${backup.msg}). Nothing was changed.`;
235	    await recordUpdateResult(server.id, msg);
236	    await notifyFailureOnce(server.userId, server.id, `${name} update skipped on ${server.hostname}`, msg, href);
237	    throw new Error(`game update: pre-update backup failed: ${backup.msg}`);
238	  }
239	
240	  const setVersion = async (v: string) => {
241	    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
242	    const cfg = { ...((fresh?.gameConfig as Record<string, unknown> | null) ?? {}), VERSION: v };
243	    await db.server.update({ where: { id: server.id }, data: { gameConfig: cfg as any } });
244	  };
245	  const applyAndVerify = async (v: string) => {
246	    const out = await applyRealConfig(server as any, family, { ...values, VERSION: v });
247	    const port = await waitForGamePort(server as unknown as ControlServer, spec.powerStartTimeoutMs ?? 180_000, 5_000);
248	    return { out, up: out.ok && (port ? port.ok : true), portErr: port?.error ?? null };
249	  };
250	
251	  await setVersion(plan.to);
252	  const res = await applyAndVerify(plan.to).catch((e) => ({ out: { ok: false, applied: [], notes: [String(e?.message ?? e)] }, up: false, portErr: null }));
253	  const after = rt ? await probeGameRuntime(rt).catch(() => null) : null;
254	  if (after) await saveRuntime(server.id, after);
255	
256	  if (res.up) {
257	    const msg = `Updated ${name} from ${plan.from} to ${plan.to}, restarted and verified it's accepting connections. A backup of your world from just before the update is at ${backup.archive}.`;
258	    await recordUpdateResult(server.id, msg);
259	    await db.auditLog
260	      .create({ data: { userId: null, action: "gameserver.auto_update", detail: `${server.hostname} ${family} ${plan.from} -> ${plan.to} backup=${backup.archive}` } })
261	      .catch(() => {});
262	    await notify(server.userId, `${name} updated to ${plan.to} on ${server.hostname}`, msg, href);
263	    return;
264	  }
265	
266	  // Roll back the version.
267	  await setVersion(plan.from);
268	  const back = await applyAndVerify(plan.from).catch(() => ({ up: false }));
269	  const final = rt ? await probeGameRuntime(rt).catch(() => null) : null;
270	  if (final) await saveRuntime(server.id, final);
271	  const why = [...(res.out.notes ?? []), res.portErr ?? ""].filter(Boolean).join(" ").slice(0, 300);
272	  const msg = back.up
273	    ? `Tried to update ${name} from ${plan.from} to ${plan.to}, but it didn't come back online (${why || "no detail"}), so we put ${plan.from} back and it's running again. Your pre-update world backup is at ${backup.archive}.`
274	    : `Tried to update ${name} from ${plan.from} to ${plan.to}; it didn't come back online and restoring ${plan.from} didn't bring it back either. Our team has been alerted. Your pre-update world backup is at ${backup.archive}.`;
275	  await recordUpdateResult(server.id, msg);
276	  await db.auditLog
277	    .create({ data: { userId: null, action: "gameserver.auto_update_failed", detail: `${server.hostname} ${family} ${plan.from} -> ${plan.to} rolledBack=${back.up} backup=${backup.archive}` } })
278	    .catch(() => {});
279	  await notify(server.userId, `${name} update to ${plan.to} rolled back on ${server.hostname}`, msg, href);
280	  if (!back.up) {
281	    await notifyAdmins(`Game update left ${server.hostname} down`, msg, `/admin/servers/${server.id}`).catch(() => {});
282	  }
283	  // A retry would back up and try the same failing version again — never.
284	  await noRetry(job.id);
285	  throw new Error(`game update not verified: ${msg}`);
286	}
