288	/**
289	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
290	 * auto-update and has no job already in flight. Idempotent / safe to call on a
291	 * timer. Returns nothing; logs a summary.
292	 */
293	export async function gameUpdateSweep(): Promise<void> {
294	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
295	  const allCandidates = await db.server.findMany({
296	    where: {
297	      status: "RUNNING",
298	      autoUpdate: true,
299	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
300	    },
301	    select: { id: true, hostname: true, gameConfig: true, osTemplate: { select: { family: true } }, gameRuntime: { select: { intent: true } } },
302	  });
303	  if (allCandidates.length === 0) return;
304	
305	  // Skip a server whose game SERVICE the customer deliberately stopped through
306	  // the dashboard — see eligibleForUpdateSweep's doc comment. `Server.status`
307	  // (checked above) is the VM's power state and can't see this.
308	  // Also honour the recorded run intent (lib/game-runtime.ts) — `_serviceState`
309	  // is erased by older code paths; GameRuntime.intent is not.
310	  const candidates = allCandidates.filter((s) => eligibleForUpdateSweep(s.gameConfig) && s.gameRuntime?.intent !== "stopped");
311	  const skippedStopped = allCandidates.length - candidates.length;
312	
313	  let enqueued = 0;
314	  for (const s of candidates) {
315	    const inflight = await db.job.count({
316	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
317	    });
318	    if (inflight > 0) continue;
319	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
320	    enqueued++;
321	  }
322	  if (enqueued > 0 || skippedStopped > 0) {
323	    const checkOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
324	    console.log(
325	      `[game-update] sweep enqueued ${enqueued} job(s)` +
326	        (checkOnly > 0
327	          ? ` (${checkOnly} candidate(s) are families with no update source — those runs verify the unit is ` +
328	            `up and change nothing)`
329	          : "") +
330	        (skippedStopped > 0
331	          ? ` (${skippedStopped} candidate(s) skipped — game service deliberately stopped by the customer)`
332	          : "")
333	    );
334	  }
335	}
