/**
 * Version comparison + range matching for mod auto-update. Pure, no I/O.
 *
 * Mod version strings are not semver in the wild ("5.4.131", "0.5.8+1.20.1",
 * "fabric-0.92.2+1.20.1", "v2.1", "1.0.0-beta.3"). The comparator extracts the
 * first dotted numeric run (ignoring a leading loader/`v` prefix and anything
 * after `+`, which semver defines as build metadata), compares numerically,
 * and ranks a prerelease (`-beta.3`) below the same release. When the
 * provider gives a publish date, callers prefer that (see newer()).
 *
 * Range grammar accepted by satisfies() — a union of what the sources use:
 *   ""  "*"  "any"                 anything
 *   "1.2.3"  "=1.2.3"              exact (numeric parts)
 *   ">=1.2"  ">1.2"  "<=2"  "<2"   comparators
 *   "^1.2.3"  "~1.2.3"             npm-style caret/tilde (ficsit.app, semver)
 *   "1.2.x"  "1.x"  "1.21.*"       wildcard
 *   ">=1.0 <2.0"                   space-separated AND
 *   "a || b"                       OR
 * Thunderstore dependency strings ("Author-Name-1.2.3") are MINIMUMS — the
 * candidates loader turns them into ">=1.2.3" before they get here.
 */

export type ParsedVersion = { nums: number[]; pre: string | null; raw: string };

export function parseVersion(raw: string): ParsedVersion {
  const s = String(raw ?? "").trim();
  // Drop build metadata, then a leading non-numeric prefix ("v", "fabric-", "mc").
  const noBuild = s.split("+")[0];
  const m = /(\d+(?:\.\d+)*)(?:-([0-9A-Za-z.\-]+))?/.exec(noBuild);
  if (!m) return { nums: [], pre: null, raw: s };
  return { nums: m[1].split(".").map((n) => Number(n)), pre: m[2] ?? null, raw: s };
}

function cmpPre(a: string | null, b: string | null): number {
  if (a === b) return 0;
  if (a === null) return 1; // release > prerelease
  if (b === null) return -1;
  const pa = a.split(".");
  const pb = b.split(".");
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i];
    const y = pb[i];
    if (x === undefined) return -1;
    if (y === undefined) return 1;
    const nx = /^\d+$/.test(x) ? Number(x) : NaN;
    const ny = /^\d+$/.test(y) ? Number(y) : NaN;
    if (!Number.isNaN(nx) && !Number.isNaN(ny)) {
      if (nx !== ny) return nx < ny ? -1 : 1;
    } else if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

/** -1 / 0 / 1. Unparseable strings compare equal to each other and below anything numeric. */
export function compareVersions(a: string, b: string): number {
  const pa = parseVersion(a);
  const pb = parseVersion(b);
  if (!pa.nums.length && !pb.nums.length) return a === b ? 0 : a < b ? -1 : 1;
  if (!pa.nums.length) return -1;
  if (!pb.nums.length) return 1;
  for (let i = 0; i < Math.max(pa.nums.length, pb.nums.length); i++) {
    const x = pa.nums[i] ?? 0;
    const y = pb.nums[i] ?? 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return cmpPre(pa.pre, pb.pre);
}

export function isPrerelease(v: string): boolean {
  return parseVersion(v).pre !== null && /alpha|beta|rc|pre|snapshot|dev/i.test(parseVersion(v).pre ?? "");
}

type Cmp = { op: ">=" | ">" | "<=" | "<" | "="; v: string };

function expand(token: string): Cmp[] | null {
  const t = token.trim();
  if (!t || t === "*" || /^any$/i.test(t) || /^x$/i.test(t)) return [];
  let m = /^(>=|<=|>|<|=|==)\s*(.+)$/.exec(t);
  if (m) return [{ op: (m[1] === "==" ? "=" : m[1]) as Cmp["op"], v: m[2].trim() }];
  m = /^\^(.+)$/.exec(t);
  if (m) {
    const p = parseVersion(m[1]).nums;
    if (!p.length) return null;
    // ^1.2.3 → <2.0.0 ; ^0.2.3 → <0.3.0 ; ^0.0.3 → <0.0.4
    const i = p.findIndex((n) => n !== 0);
    const idx = i === -1 ? p.length - 1 : i;
    const upper = p.slice(0, idx + 1).map((n, k) => (k === idx ? n + 1 : n));
    return [{ op: ">=", v: m[1] }, { op: "<", v: upper.join(".") }];
  }
  m = /^~(.+)$/.exec(t);
  if (m) {
    const p = parseVersion(m[1]).nums;
    if (!p.length) return null;
    const upper = p.length >= 2 ? [p[0], p[1] + 1] : [p[0] + 1];
    return [{ op: ">=", v: m[1] }, { op: "<", v: upper.join(".") }];
  }
  if (/[xX*]/.test(t)) {
    const parts = t.split(".");
    const fixed: number[] = [];
    for (const part of parts) {
      if (/^[xX*]$/.test(part)) break;
      if (!/^\d+$/.test(part)) return null;
      fixed.push(Number(part));
    }
    if (!fixed.length) return [];
    const upper = fixed.map((n, k) => (k === fixed.length - 1 ? n + 1 : n));
    return [{ op: ">=", v: fixed.join(".") }, { op: "<", v: upper.join(".") }];
  }
  if (/^\d/.test(t) || /^v\d/i.test(t)) return [{ op: "=", v: t }];
  return null;
}

function test(v: string, c: Cmp): boolean {
  const r = compareVersions(v, c.v);
  switch (c.op) {
    case ">=": return r >= 0;
    case ">": return r > 0;
    case "<=": return r <= 0;
    case "<": return r < 0;
    case "=": return r === 0;
  }
}

/** Is `range` something satisfies() understands? */
export function isValidRange(range: string | null | undefined): boolean {
  if (range == null) return true;
  return String(range).split("||").every((alt) => splitAnd(alt).every((tok) => expand(tok) !== null));
}

function splitAnd(alt: string): string[] {
  // ">= 1.2" (Factorio puts a space after the operator) must stay one token.
  return alt.trim().replace(/(>=|<=|>|<|==|=)\s+/g, "$1").split(/[\s,]+/).filter(Boolean);
}

/** Does `version` satisfy `range`? An unparseable range is NOT satisfied (fail closed). */
export function satisfies(version: string, range: string | null | undefined): boolean {
  if (range == null || String(range).trim() === "") return true;
  return String(range).split("||").some((alt) => {
    const toks = splitAnd(alt);
    if (!toks.length) return true;
    return toks.every((tok) => {
      const cs = expand(tok);
      if (cs === null) return false;
      return cs.every((c) => test(version, c));
    });
  });
}

/**
 * Does a game-version list entry cover `gameVersion`? Exact match, or a
 * wildcard entry ("1.21.x"), or a range entry (">=1.20").
 */
export function gameVersionMatches(listed: string, gameVersion: string): boolean {
  const l = listed.trim();
  if (l === gameVersion) return true;
  if (/[xX*<>=^~|]/.test(l)) return satisfies(gameVersion, l);
  return false;
}

/** "a is newer than b" using publish time when both have one, else the version strings. */
export function newer(a: { version: string; publishedAt?: number | null }, b: { version: string; publishedAt?: number | null }): number {
  if (a.publishedAt != null && b.publishedAt != null && a.publishedAt !== b.publishedAt) return a.publishedAt > b.publishedAt ? 1 : -1;
  return compareVersions(a.version, b.version);
}

