/**
 * Mod auto-update — shared types (pure; no Prisma, no I/O).
 *
 * Vocabulary:
 *  - project key: the SAME key the install engine uses in the guest state file
 *    (lib/mods/engine.ts PkgState.key), e.g. "modrinth:P7dR8mSH",
 *    "thunderstore:ValheimModding-Jotunn", "hangar:luckperms".
 *  - universe: every candidate version the candidates loader found, per key.
 *  - installed: what the guest state file says is on disk now.
 */
import type { RemoteFile } from "../mods/types";

export type Mode = "OFF" | "NOTIFY" | "AUTO";
export const MODES: readonly Mode[] = ["OFF", "NOTIFY", "AUTO"];
export function isMode(v: unknown): v is Mode {
  return v === "OFF" || v === "NOTIFY" || v === "AUTO";
}

export type DepKind = "required" | "optional" | "incompatible" | "embedded";

export type DepSpec = {
  key: string;
  kind: DepKind;
  /** Version range (lib/mod-autoupdate/version.ts grammar). Null = any. */
  range?: string | null;
  /** A specific provider version id (Modrinth). Treated as a MINIMUM: that build or newer. */
  versionId?: string | null;
  name?: string | null;
};

export type CandidateVersion = {
  key: string;
  versionId: string;
  version: string;
  channel: "release" | "beta" | "alpha" | "snapshot";
  /** Game versions the source lists for this build. Empty = the source publishes none. */
  gameVersions: string[];
  /** Loaders the source lists (paper, fabric, forge, …). Empty = not stated. */
  loaders: string[];
  publishedAt?: number | null;
  deps: DepSpec[];
  /** Everything the install engine needs to fetch it (absent → can't be applied, only reported). */
  file?: RemoteFile | null;
  /** Install engine placement (plugin-jar, mod-jar, datapack, bepinex, …). */
  placement?: string | null;
  /** ModVersion row id when the NX Labs catalogue has this build (mirror fast path). */
  catalogRowId?: string | null;
};

export type ProjectInfo = {
  key: string;
  name: string;
  versions: CandidateVersion[];
  /** Project-level side flags, when the source publishes them (Modrinth). */
  clientSide?: string | null;
  serverSide?: string | null;
  categories?: string[];
  /** Modpacks are never auto-updated (they rewrite configs). */
  isModpack?: boolean;
  /** Source can't publish checksums (Thunderstore, Spiget) — said in the reason. */
  unverifiedSource?: boolean;
};

export type Universe = Record<string, ProjectInfo>;

export type InstalledPkg = {
  key: string;
  name: string;
  version: string;
  versionId: string | null;
  /** True when a catalogue mod (ServerMod row) installed this package as its root. */
  root: boolean;
  /** GameMod id when root. */
  modId?: string | null;
  pinned?: boolean;
  disabled?: boolean;
  requires?: string[];
};

export type Target = {
  family: string;
  /** Game version the server runs (Minecraft "1.21.1"); null = unknown / not versioned. */
  gameVersion: string | null;
  /** Variant / loader actually running ("paper", "fabric", "bepinex"). */
  loader: string | null;
  /** Loader tags a build may list and still load here, best first. Empty = don't check. */
  acceptedLoaders: string[];
  /** A build that lists NO game versions is refused (Minecraft mod loaders). */
  strictGameVersion: boolean;
  /** Offer beta/alpha builds (otherwise only when the installed one is already a prerelease). */
  allowPrerelease?: boolean;
};

export type DecisionAction =
  | "update" // a newer compatible version will be (or was) applied
  | "add-dependency" // a newly required dependency gets installed
  | "current" // already the newest compatible version
  | "pinned" // owner pinned; left alone
  | "held" // a newer version exists but can't be used (dependency conflict, …)
  | "no-compatible" // nothing (not even what's installed) is known compatible with the target
  | "unknown"; // the source told us nothing to decide with

export type Decision = {
  key: string;
  name: string;
  root: boolean;
  modId?: string | null;
  action: DecisionAction;
  from: string | null;
  to: string | null;
  toVersionId: string | null;
  /** One plain sentence a customer can read. */
  reason: string;
  /** The chosen build (for update / add-dependency), so the engine can apply it. */
  candidate?: CandidateVersion | null;
  /** Keys of the roots that pulled this package in. */
  requiredBy?: string[];
};

export type Plan = {
  target: Target;
  decisions: Decision[];
  /** Unresolvable constraints found while solving (also folded into decisions). */
  conflicts: string[];
  /** Number of solver iterations used (debug / tests). */
  steps: number;
};

