/**
 * Compatibility resolver for mod auto-update. PURE: no I/O, no clock, no
 * randomness — the same inputs always give the same plan, which is what lets
 * test/mod-autoupdate.test.ts pin down every decision.
 *
 * Input:  the server's Target (game + game version + loader), what is installed
 *         (from the guest state file), and the Universe of candidate versions
 *         the candidates loader found (catalogue + upstream).
 * Output: one Decision per installed package (and per newly needed
 *         dependency), each with a reason a customer can read.
 *
 * Rules, in priority order:
 *  1. Never downgrade (unless the caller asks): only versions >= what's installed are options.
 *  2. A build is a candidate only if it loads HERE: loader matches, the game
 *     version is listed (Minecraft mod loaders refuse builds that list none),
 *     and it's a release (prereleases only if already on one / opted in).
 *  3. Prefer the newest candidate of every root; walk REQUIRED dependencies
 *     transitively. Every dependent's range on a shared dependency must hold
 *     at once (diamonds): the dependency gets the newest version satisfying
 *     ALL of them. Declared incompatibilities, both directions, are conflicts.
 *  4. When a root's newest build can't be satisfied, step that root back one
 *     build and solve again (bounded); a root that can't move is held at what
 *     it has, with the conflict as its reason. "No compatible version" is an
 *     explicit outcome, never a silent skip.
 */
import { compareVersions, gameVersionMatches, isPrerelease, newer, satisfies } from "./version";
import type { CandidateVersion, Decision, DepSpec, InstalledPkg, Plan, Target, Universe } from "./types";

export type ResolveOptions = {
  allowDowngrade?: boolean;
  /** Bound on solve attempts across all roots (default 200). */
  maxSteps?: number;
  /** Only these root keys may change; every other root is kept. Default: all. */
  onlyKeys?: string[] | null;
};

export type CompatVerdict = { ok: true; detail: string; known: boolean } | { ok: false; detail: string };

/** Can this build load on this server? */
export function compatibility(v: CandidateVersion, target: Target, opts: { allowPre?: boolean } = {}): CompatVerdict {
  if (v.channel !== "release" && !opts.allowPre && !target.allowPrerelease) {
    return { ok: false, detail: `${v.version} is a ${v.channel} build` };
  }
  let known = true;
  if (target.acceptedLoaders.length && v.loaders.length) {
    const lo = v.loaders.map((l) => l.toLowerCase());
    if (!lo.some((l) => target.acceptedLoaders.includes(l))) {
      return { ok: false, detail: `${v.version} is built for ${lo.slice(0, 3).join("/")}, this server runs ${target.loader ?? "something else"}` };
    }
  } else if (target.acceptedLoaders.length && !v.loaders.length) {
    known = false;
  }
  if (target.gameVersion) {
    if (v.gameVersions.length) {
      if (!v.gameVersions.some((g) => gameVersionMatches(g, target.gameVersion!))) {
        return { ok: false, detail: `${v.version} lists ${summarizeVersions(v.gameVersions)}, not ${target.gameVersion}` };
      }
    } else if (target.strictGameVersion) {
      return { ok: false, detail: `${v.version} doesn't say which game versions it supports` };
    } else known = false;
  } else if (target.strictGameVersion) {
    return { ok: false, detail: "this server's game version is unknown" };
  }
  return { ok: true, known, detail: known ? `supports ${target.loader ?? target.family}${target.gameVersion ? ` ${target.gameVersion}` : ""}` : "the source publishes no compatibility data for it" };
}

function summarizeVersions(vs: string[]): string {
  const sorted = [...vs].sort(compareVersions);
  if (sorted.length <= 3) return sorted.join(", ");
  return `${sorted[0]}…${sorted[sorted.length - 1]}`;
}

type Constraint = { dep: DepSpec; from: string };
type Assigned = { key: string; version: string; versionId: string | null; cand: CandidateVersion | null; kept: boolean };
type Conflict = { key: string; msg: string; roots: string[] };

function newestFirst(vs: CandidateVersion[]): CandidateVersion[] {
  return [...vs].sort((a, b) => newer(b, a));
}

function findInstalledCandidate(u: Universe, p: { key: string; version: string; versionId: string | null }): CandidateVersion | null {
  const vs = u[p.key]?.versions ?? [];
  return (p.versionId ? vs.find((v) => v.versionId === p.versionId) : null) ?? vs.find((v) => v.version === p.version) ?? null;
}

/** Does a version (string/id + its catalogue entry) satisfy one dependency constraint? */
function meets(u: Universe, key: string, version: string, versionId: string | null, c: DepSpec): boolean {
  if (c.range && !satisfies(version, c.range)) return false;
  if (c.versionId) {
    if (versionId === c.versionId) return true;
    // A pinned version id is a MINIMUM: that build or anything newer of the same project.
    const pinned = u[key]?.versions.find((v) => v.versionId === c.versionId);
    if (!pinned) return true; // can't compare against something we know nothing about
    const self = u[key]?.versions.find((v) => v.versionId === versionId) ?? { version, publishedAt: null };
    return newer(self, pinned) >= 0;
  }
  return true;
}

function describe(c: DepSpec): string {
  if (c.range) return c.range;
  if (c.versionId) return `build ${c.versionId} or newer`;
  return "any version";
}

export function resolveUpdates(target: Target, installed: InstalledPkg[], universe: Universe, opts: ResolveOptions = {}): Plan {
  const maxSteps = opts.maxSteps ?? 200;
  const byKey = new Map(installed.map((p) => [p.key, p]));
  const roots = installed.filter((p) => p.root);
  const name = (k: string) => byKey.get(k)?.name ?? universe[k]?.name ?? k.replace(/^[a-z_]+:/, "");
  const allowPreFor = (k: string) => {
    const inst = byKey.get(k);
    if (!inst) return false;
    const c = findInstalledCandidate(universe, inst);
    return c ? c.channel !== "release" : isPrerelease(inst.version);
  };
  const notOlder = (k: string, v: CandidateVersion) => {
    const inst = byKey.get(k);
    if (!inst || opts.allowDowngrade) return true;
    const instC = findInstalledCandidate(universe, inst);
    return newer(v, instC ?? { version: inst.version, publishedAt: null }) >= 0;
  };

  // ── per-root option lists: compatible, not older, newest first; "keep" last ──
  type Opt = CandidateVersion | "keep";
  const options = new Map<string, Opt[]>();
  const rootNotes = new Map<string, string[]>();
  for (const r of roots) {
    const mayChange = !r.pinned && !r.disabled && !universe[r.key]?.isModpack && (!opts.onlyKeys || opts.onlyKeys.includes(r.key));
    const list: Opt[] = [];
    if (mayChange) {
      for (const v of newestFirst(universe[r.key]?.versions ?? [])) {
        if (!notOlder(r.key, v)) continue;
        if (v.versionId === r.versionId || (v.version === r.version && !r.versionId)) continue; // that's "keep"
        if (compatibility(v, target, { allowPre: allowPreFor(r.key) }).ok) list.push(v);
      }
    }
    list.push("keep");
    options.set(r.key, list);
    rootNotes.set(r.key, []);
  }

  const solve = (choice: Map<string, Opt>): { assigned: Map<string, Assigned>; conflicts: Conflict[]; parents: Map<string, Set<string>> } => {
    const assigned = new Map<string, Assigned>();
    const parents = new Map<string, Set<string>>();
    for (const r of roots) {
      const ch = choice.get(r.key) ?? "keep";
      if (ch === "keep") assigned.set(r.key, { key: r.key, version: r.version, versionId: r.versionId, cand: findInstalledCandidate(universe, r), kept: true });
      else assigned.set(r.key, { key: r.key, version: ch.version, versionId: ch.versionId, cand: ch, kept: false });
    }
    const rootsOf = (k: string, seen = new Set<string>()): string[] => {
      if (seen.has(k)) return [];
      seen.add(k);
      if (options.has(k) && !parents.get(k)?.size) return [k];
      const out = new Set<string>(options.has(k) ? [k] : []);
      for (const p of parents.get(k) ?? []) for (const x of rootsOf(p, seen)) out.add(x);
      return [...out];
    };
    for (let iter = 0; iter < 50; iter++) {
      const cons = new Map<string, Constraint[]>();
      const incompat: { key: string; from: string }[] = [];
      parents.clear();
      for (const a of assigned.values()) {
        for (const d of a.cand?.deps ?? []) {
          if (d.kind === "required") {
            const arr = cons.get(d.key) ?? [];
            arr.push({ dep: d, from: a.key });
            cons.set(d.key, arr);
            const ps = parents.get(d.key) ?? new Set<string>();
            ps.add(a.key);
            parents.set(d.key, ps);
          } else if (d.kind === "incompatible") incompat.push({ key: d.key, from: a.key });
        }
      }
      const conflicts: Conflict[] = [];
      let changed = false;
      for (const [key, cs] of cons) {
        const cur = assigned.get(key);
        const inst = byKey.get(key);
        const okFor = (version: string, versionId: string | null) => cs.every((c) => meets(universe, key, version, versionId, c.dep));
        if (cur && okFor(cur.version, cur.versionId)) continue;
        if (cur && options.has(key)) {
          // A ROOT another mod depends on: its own option search moves it, not this pass.
          const need = cs.filter((c) => !meets(universe, key, cur.version, cur.versionId, c.dep)).map((c) => `${name(c.from)} needs ${name(key)} ${describe(c.dep)}`);
          conflicts.push({ key, msg: `${need.join("; ")} (it would be ${cur.version})`, roots: [...new Set([...rootsOf(key), ...cs.flatMap((c) => rootsOf(c.from))])] });
          continue;
        }
        const pool = newestFirst(universe[key]?.versions ?? []).filter((v) => okFor(v.version, v.versionId));
        const compatPool = pool.filter((v) => compatibility(v, target, { allowPre: allowPreFor(key) }).ok);
        const upward = compatPool.filter((v) => notOlder(key, v));
        let pick: Assigned | null = null;
        if (upward.length) pick = { key, version: upward[0].version, versionId: upward[0].versionId, cand: upward[0], kept: false };
        else if (inst && okFor(inst.version, inst.versionId)) {
          // Nothing better is known — what's installed already meets every range.
          pick = { key, version: inst.version, versionId: inst.versionId, cand: findInstalledCandidate(universe, inst), kept: true };
        }
        if (!pick) {
          const who = [...new Set(cs.map((c) => c.from))];
          const want = cs.map((c) => `${name(c.from)} needs ${describe(c.dep)}`).join("; ");
          let msg: string;
          if (!universe[key]?.versions.length) msg = `${name(key)} is required (${want}) but no build of it could be found`;
          else if (compatPool.length && !upward.length && inst) msg = `${want} — that would mean downgrading ${name(key)} from ${inst.version}`;
          else if (pool.length && !compatPool.length) msg = `${name(key)} has no build that loads on ${target.loader ?? target.family}${target.gameVersion ? ` ${target.gameVersion}` : ""} and meets ${want}`;
          else msg = `no version of ${name(key)} satisfies every requirement at once (${want})`;
          conflicts.push({ key, msg, roots: [...new Set(who.flatMap((w) => rootsOf(w)))] });
          continue;
        }
        if (!cur || cur.version !== pick.version || cur.versionId !== pick.versionId) {
          assigned.set(key, pick);
          changed = true;
        }
      }
      for (const ic of incompat) {
        const there = assigned.get(ic.key) ?? (byKey.get(ic.key) && !byKey.get(ic.key)!.disabled ? byKey.get(ic.key) : null);
        if (there) conflicts.push({ key: ic.key, msg: `${name(ic.from)} declares it is incompatible with ${name(ic.key)}`, roots: [...new Set([...rootsOf(ic.from), ...rootsOf(ic.key)])] });
      }
      if (conflicts.length || !changed) return { assigned, conflicts, parents };
    }
    return { assigned, conflicts: [{ key: "*", msg: "the dependency set did not settle", roots: roots.map((r) => r.key) }], parents };
  };

  // ── search: newest for every root, step back culprits one build at a time ──
  const idx = new Map(roots.map((r) => [r.key, 0]));
  const choiceOf = () => new Map(roots.map((r) => [r.key, options.get(r.key)![idx.get(r.key)!]]));
  let steps = 0;
  let result = solve(choiceOf());
  const firstFail = new Map<string, string>();
  while (result.conflicts.length && steps < maxSteps) {
    steps++;
    const culprits = [...new Set(result.conflicts.flatMap((c) => c.roots))].filter((k) => options.has(k));
    for (const c of result.conflicts) for (const k of c.roots) {
      const ch = options.get(k)?.[idx.get(k) ?? 0];
      if (ch && ch !== "keep" && !firstFail.has(k)) firstFail.set(k, `${ch.version}: ${c.msg}`);
    }
    // Step back the culprit with a non-"keep" choice whose current pick is newest-but-failing.
    const movable = culprits.filter((k) => idx.get(k)! < options.get(k)!.length - 1);
    if (!movable.length) {
      // Everything involved is already at "keep": fall back to keeping ALL roots.
      for (const r of roots) idx.set(r.key, options.get(r.key)!.length - 1);
      result = solve(choiceOf());
      break;
    }
    const k = movable[movable.length - 1];
    idx.set(k, idx.get(k)! + 1);
    result = solve(choiceOf());
  }
  if (result.conflicts.length && steps >= maxSteps) {
    for (const r of roots) idx.set(r.key, options.get(r.key)!.length - 1);
    result = solve(choiceOf());
  }

  // ── decisions ───────────────────────────────────────────────────────────────
  const decisions: Decision[] = [];
  const conflictsFinal = result.conflicts.map((c) => c.msg);
  const tgt = `${target.loader ?? target.family}${target.gameVersion ? ` ${target.gameVersion}` : ""}`;
  for (const r of roots) {
    const a = result.assigned.get(r.key)!;
    const base = { key: r.key, name: r.name, root: true, modId: r.modId ?? null, from: r.version };
    const instC = findInstalledCandidate(universe, r);
    const instCompat = instC ? compatibility(instC, target, { allowPre: true }) : null;
    if (r.pinned) {
      decisions.push({ ...base, action: "pinned", to: null, toVersionId: null, reason: `Pinned at ${r.version} by you — never updated automatically.` });
      continue;
    }
    if (r.disabled) {
      decisions.push({ ...base, action: "current", to: null, toVersionId: null, reason: `Disabled — not checked for updates until you enable it again.` });
      continue;
    }
    if (universe[r.key]?.isModpack) {
      decisions.push({ ...base, action: "held", to: null, toVersionId: null, reason: `Modpacks aren't updated automatically (an update rewrites config files) — update it from the Mods tab when you're ready.` });
      continue;
    }
    if (!a.kept && a.cand) {
      const extra = universe[r.key]?.unverifiedSource ? " The source publishes no checksum; the file is size-capped and archive-checked instead." : "";
      const skipped = firstFail.get(r.key);
      decisions.push({
        ...base,
        action: "update",
        to: a.version,
        toVersionId: a.versionId,
        candidate: a.cand,
        reason: `${r.version} → ${a.version}: newest build that ${compatibility(a.cand, target, { allowPre: allowPreFor(r.key) }).detail}${skipped ? ` (a newer build was skipped — ${skipped})` : ""}.${extra}`,
      });
      continue;
    }
    // Kept. Why?
    const opts2 = options.get(r.key)!;
    const hadNewer = opts2.length > 1;
    if (hadNewer) {
      decisions.push({ ...base, action: "held", to: null, toVersionId: null, reason: `Staying on ${r.version}: ${firstFail.get(r.key) ?? conflictsFinal[0] ?? "newer builds conflict with other installed mods"}.` });
      continue;
    }
    const known = universe[r.key]?.versions ?? [];
    if (!known.length) {
      decisions.push({ ...base, action: "unknown", to: null, toVersionId: null, reason: `Couldn't get ${r.name}'s version list from its source — nothing was changed.` });
      continue;
    }
    if (instCompat && !instCompat.ok) {
      decisions.push({ ...base, action: "no-compatible", to: null, toVersionId: null, reason: `No compatible version: ${r.version} doesn't support ${tgt} and the source has no newer build that does (${instCompat.detail}).` });
      continue;
    }
    if (!instC) {
      // Installed build isn't in the list we got; is anything in the list compatible at all?
      const anyCompat = known.some((v) => compatibility(v, target, { allowPre: allowPreFor(r.key) }).ok);
      if (!anyCompat && (target.gameVersion || target.acceptedLoaders.length)) {
        decisions.push({ ...base, action: "no-compatible", to: null, toVersionId: null, reason: `No compatible version: none of ${r.name}'s published builds load on ${tgt}.` });
        continue;
      }
    }
    const blocked = known.filter((v) => notOlder(r.key, v) && v.version !== r.version && newer(v, instC ?? { version: r.version, publishedAt: null }) > 0);
    if (blocked.length) {
      const why = compatibility(newestFirst(blocked)[0], target, { allowPre: allowPreFor(r.key) });
      decisions.push({ ...base, action: "current", to: null, toVersionId: null, reason: `${r.version} is the newest build for ${tgt} — ${!why.ok ? `newer ${why.detail}` : "newer builds aren't usable here"}.` });
      continue;
    }
    decisions.push({ ...base, action: "current", to: null, toVersionId: null, reason: `${r.version} is already the newest version${instCompat && instCompat.ok && instCompat.known ? ` for ${tgt}` : ""}.` });
  }
  // Dependencies (installed or new) the final set requires.
  for (const [key, a] of result.assigned) {
    if (options.has(key)) continue;
    const inst = byKey.get(key);
    const by = [...(result.parents.get(key) ?? [])];
    const byNames = by.map(name).join(", ");
    if (!inst) {
      decisions.push({ key, name: name(key), root: false, action: "add-dependency", from: null, to: a.version, toVersionId: a.versionId, candidate: a.cand, requiredBy: by, reason: `New dependency: ${byNames} now require${by.length === 1 ? "s" : ""} ${name(key)} ${a.version}.` });
    } else if (inst.version !== a.version || (a.versionId && inst.versionId !== a.versionId)) {
      decisions.push({ key, name: inst.name, root: false, action: "update", from: inst.version, to: a.version, toVersionId: a.versionId, candidate: a.cand, requiredBy: by, reason: `${inst.version} → ${a.version}: newest build that loads on ${tgt} and satisfies ${byNames}.` });
    } else {
      decisions.push({ key, name: inst.name, root: false, action: "current", from: inst.version, to: null, toVersionId: null, requiredBy: by, reason: `${inst.version} still satisfies ${byNames}.` });
    }
  }
  return { target, decisions, conflicts: conflictsFinal, steps };
}

/** The decisions that change something on disk. */
export function changesOf(plan: Plan): Decision[] {
  return plan.decisions.filter((d) => (d.action === "update" || d.action === "add-dependency") && d.candidate);
}

