/**
 * Does a mod have to be installed — at the SAME version — on every player's
 * own game? Pure.
 *
 * Why this matters: Valheim refuses the connection when a gameplay mod's
 * version differs between server and client (docs/DOCUMENTATION.md, Valheim
 * KB, "client parity" — customer Jay's friends could not join for exactly
 * this reason). Auto-updating such a mod on the server silently locks every
 * player out until they update too, so clientRequired mods default to NOTIFY
 * and only auto-update when the owner opted in explicitly.
 *
 * Sources of truth, best first:
 *  1. curated overrides (below) — the cases heuristics get wrong;
 *  2. the provider's own flag: Modrinth `client_side` (required → yes,
 *     optional/unsupported → no); Thunderstore Valheim community categories
 *     ("Server-side" without "Client-side" → no);
 *  3. family heuristics: server plugin platforms (Paper/Spigot/Hangar, uMod,
 *     CounterStrikeSharp) never need client installs; Valheim BepInEx gameplay
 *     mods almost always do; Factorio mods must match but the game downloads
 *     them for players automatically.
 */

export type ClientInfo = {
  family: string;
  source: string;
  /** Guest-state key ("thunderstore:ValheimModding-Jotunn") or catalogue sourceId. */
  key: string;
  name: string;
  /** Server variant (paper, fabric, bepinex…). */
  variant: string | null;
  clientSide?: string | null;
  serverSide?: string | null;
  categories?: string[];
};

export type ClientVerdict = { required: boolean | null; reason: string; basis: "curated" | "provider" | "heuristic" | "unknown" };

/**
 * Valheim packages whose client requirement is known. Keys are Thunderstore
 * "Namespace-Name", lower-cased. `true` = players need it at the same version.
 */
export const VALHEIM_CLIENT_OVERRIDES: Record<string, { required: boolean; why: string }> = {
  // Libraries every client-side Valheim mod is built on: players need them too.
  "valheimmodding-jotunn": { required: true, why: "Jötunn is a library the client-side halves of other mods load — players need the same version." },
  "denikson-bepinexpack_valheim": { required: true, why: "BepInEx is the mod loader itself; every player using mods needs it." },
  // ServerSync-enforced mods: the server kicks clients whose version differs.
  "azumatt-azuantiarickroll": { required: true, why: "Uses ServerSync version enforcement." },
  "randyknapp-epicloot": { required: true, why: "Epic Loot adds items and enforces matching versions between server and players." },
  "advize-planteverything": { required: true, why: "Adds build pieces; players need the same version to place and see them." },
  "smoothbrain-serverdevcommands": { required: true, why: "Dev commands run on each player's client; the server half alone does nothing." },
  // Genuinely server-only tools.
  "nxeon-nxeondevadmin": { required: true, why: "NxeonDevAdmin 2.0.0 is a client-side plugin (it unlocks god/fly on the player's game)." },
};

