    };
  }

  if (fam === "minecraft") {
    if (SERVER_PLUGIN_SOURCES.has(m.source) || PLUGIN_VARIANTS.has(variant)) {
      return { required: false, reason: "Server plugin — players join with an unmodified game.", basis: "heuristic" };
    }
    const cs = (m.clientSide ?? "").toLowerCase();
    if (cs === "required") return { required: true, reason: "Modrinth: client_side = required — players need the same mod.", basis: "provider" };
    if (cs === "optional") return { required: false, reason: "Modrinth: client_side = optional — players can join without it.", basis: "provider" };
    if (cs === "unsupported") return { required: false, reason: "Modrinth: server-side only.", basis: "provider" };
    if (cats.includes("datapacks") || cats.includes("datapack")) return { required: false, reason: "Datapacks run on the server only.", basis: "heuristic" };
    return { required: null, reason: "The source doesn't say whether players need it.", basis: "unknown" };
  }

  if (fam === "factorio") {
    return { required: true, reason: "Factorio mods must match on every player — the game offers to download them when joining.", basis: "heuristic" };
  }
  if (fam === "rust" || fam === "cs2") {
    return { required: false, reason: "Server-side plugin — players join with an unmodified game.", basis: "heuristic" };
  }
  return { required: null, reason: "Not known for this game.", basis: "unknown" };
}

