/**
 * "Give this to your players" — client profiles for a server's mod list. Pure.
 *
 * Solves "my friends can't join": the players get EXACTLY the versions the
 * server runs, in a format their mod manager imports in one step.
 *
 *  - r2modman / Thunderstore Mod Manager (Valheim): a `.r2z` — a zip holding
 *    `export.r2x`, YAML of `{ profileName, mods: [{ name: "Namespace-Name",
 *    version: { major, minor, patch }, enabled }] }`, exactly r2modman's own
 *    ExportFormat/ExportMod/VersionNumber shape (ebkr/r2modmanPlus
 *    src/model/exports/*). The shareable "profile code" is that same file,
 *    base64-encoded behind a `#r2modman\n` header, POSTed to Thunderstore's
 *    legacyprofile/create endpoint (profileCodePayload below; the upload
 *    itself is lib/mod-autoupdate/profile-store.ts).
 *  - Modrinth / Prism / ATLauncher (Minecraft mod loaders): a `.mrpack` —
 *    a zip with `modrinth.index.json` (formatVersion 1, game "minecraft",
 *    files[] with path + sha1 + sha512 + downloads + env, dependencies with
 *    the minecraft version and the loader version). Per the format, every file
 *    must carry both hashes and download from an allowed host; anything that
 *    doesn't is left out and named in `skipped`.
 *  - everything else: a plain checklist (name, exact version, link).
 */
import { writeZip } from "./zip";

export type ProfileMod = {
  key: string;
  name: string;
  version: string;
  source: string;
  url?: string | null;
  /** true = players must have it; false = server-only; null = unknown (included, marked optional). */
  clientRequired: boolean | null;
  file?: { filename: string; url: string | null; sha1?: string | null; sha512?: string | null; size?: number | null } | null;
};

// ── r2modman ────────────────────────────────────────────────────────────────

const TS_NAME = /^[A-Za-z0-9_]+-[A-Za-z0-9_]+$/;

/** JSON strings are valid YAML scalars — safest quoting there is. */
const y = (s: string) => JSON.stringify(s);

export function r2xYaml(profileName: string, mods: { name: string; version: string; enabled: boolean }[]): string {
  const lines = [`profileName: ${y(profileName)}`, "mods:"];
  if (!mods.length) lines[1] = "mods: []";
  for (const m of mods) {
    const [major, minor, patch] = m.version.split(".").map((n) => Number(n));
    lines.push(`  - name: ${y(m.name)}`, "    version:", `      major: ${major}`, `      minor: ${minor}`, `      patch: ${patch}`, `    enabled: ${m.enabled ? "true" : "false"}`);
  }
  return lines.join("\n") + "\n";
}

export function buildR2modmanProfile(
  profileName: string,
  mods: ProfileMod[],
  loaderPack: { name: string; version: string } | null,
): { data: Buffer; r2x: string; included: string[]; skipped: string[] } {
  const skipped: string[] = [];
  const out: { name: string; version: string; enabled: boolean }[] = [];
  const included: string[] = [];
  if (loaderPack && TS_NAME.test(loaderPack.name) && /^\d+\.\d+\.\d+$/.test(loaderPack.version)) {
    out.push({ name: loaderPack.name, version: loaderPack.version, enabled: true });
    included.push(`${loaderPack.name} ${loaderPack.version}`);
  }
  for (const m of mods) {
    if (m.source !== "thunderstore") { skipped.push(`${m.name} (not a Thunderstore package)`); continue; }
    if (m.clientRequired === false) continue; // server-only: players don't need it
    const name = m.key.replace(/^thunderstore:/, "");
    if (!TS_NAME.test(name) || !/^\d+\.\d+\.\d+$/.test(m.version)) { skipped.push(`${m.name} (unusual version "${m.version}")`); continue; }
    if (out.some((o) => o.name.toLowerCase() === name.toLowerCase())) continue;
    out.push({ name, version: m.version, enabled: true });
    included.push(`${name} ${m.version}`);
  }
  const r2x = r2xYaml(profileName.slice(0, 60) || "Nxeon server", out);
  return { data: writeZip([{ name: "export.r2x", data: Buffer.from(r2x, "utf8") }]), r2x, included, skipped };
}

/** Body r2modman uploads to thunderstore.io/api/experimental/legacyprofile/create/. */
export function profileCodePayload(r2z: Buffer): string {
  return `#r2modman\n${r2z.toString("base64")}`;
}

// ── Modrinth .mrpack ───────────────────────────────────────────────────────

export const MRPACK_HOSTS = ["cdn.modrinth.com", "github.com", "raw.githubusercontent.com", "gitlab.com"];
const LOADER_KEY: Record<string, string> = { fabric: "fabric-loader", quilt: "quilt-loader", forge: "forge", neoforge: "neoforge" };

export type MrpackIndex = {
  formatVersion: 1;
  game: "minecraft";
  versionId: string;
  name: string;
  summary?: string;
  files: { path: string; hashes: { sha1: string; sha512: string }; env: { client: "required" | "optional"; server: "required" | "optional" | "unsupported" }; downloads: string[]; fileSize: number }[];
  dependencies: Record<string, string>;
};

function hostOk(u: string): boolean {
  try {
    const x = new URL(u);
    return x.protocol === "https:" && MRPACK_HOSTS.includes(x.hostname);
  } catch {
    return false;
  }
}

export function buildMrpack(opts: {
  name: string;
  versionId: string;
  summary?: string;
  mcVersion: string;
  loader: string;
  loaderVersion: string;
  mods: ProfileMod[];
}): { data: Buffer; index: MrpackIndex; included: string[]; skipped: string[] } | { error: string } {
  const lk = LOADER_KEY[opts.loader.toLowerCase()];
  if (!lk) return { error: `${opts.loader} servers don't need a client modpack — players join with an unmodified game.` };
  if (!/^[0-9A-Za-z.\-+_]{1,40}$/.test(opts.loaderVersion)) return { error: "The server's loader version isn't known, so a modpack can't name it." };
  const files: MrpackIndex["files"] = [];
  const included: string[] = [];
  const skipped: string[] = [];
  for (const m of opts.mods) {
    if (m.clientRequired === false) continue;
    const f = m.file;
    if (!f || !f.url || !f.sha1 || !f.sha512 || !f.size) { skipped.push(`${m.name} ${m.version} (no checksummed download to point players at)`); continue; }
    if (!hostOk(f.url)) { skipped.push(`${m.name} ${m.version} (hosted somewhere a .mrpack may not download from)`); continue; }
    const safe = f.filename.replace(/[^A-Za-z0-9._+\-]/g, "_");
    if (!safe.endsWith(".jar")) { skipped.push(`${m.name} (not a mod jar)`); continue; }
    files.push({
      path: `mods/${safe}`,
      hashes: { sha1: f.sha1.toLowerCase(), sha512: f.sha512.toLowerCase() },
      env: { client: m.clientRequired === true ? "required" : "optional", server: "required" },
      downloads: [f.url],
      fileSize: f.size,
    });
    included.push(`${m.name} ${m.version}`);
  }
  const index: MrpackIndex = {
    formatVersion: 1,
    game: "minecraft",
    versionId: opts.versionId,
    name: opts.name.slice(0, 80),
    ...(opts.summary ? { summary: opts.summary.slice(0, 200) } : {}),
    files,
    dependencies: { minecraft: opts.mcVersion, [lk]: opts.loaderVersion },
  };
  const data = writeZip([{ name: "modrinth.index.json", data: Buffer.from(JSON.stringify(index, null, 2), "utf8") }]);
  return { data, index, included, skipped };
}

/** The loader version itzg/minecraft-server will run, from a McJarPin build or game config. */
export function loaderVersionFrom(loader: string, pinBuild: string | null | undefined, config: Record<string, unknown> | null | undefined): string | null {
  const l = loader.toLowerCase();
  const cfg = config ?? {};
  const fromCfg = (k: string) => (typeof cfg[k] === "string" && /^[0-9A-Za-z.\-+_]{1,40}$/.test(cfg[k] as string) ? (cfg[k] as string) : null);
  if (l === "fabric") return fromCfg("FABRIC_LOADER_VERSION") ?? (pinBuild ? pinBuild.split("+")[0] : null);
  if (l === "quilt") return fromCfg("QUILT_LOADER_VERSION");
  if (l === "forge") return fromCfg("FORGE_VERSION") ?? pinBuild ?? null;
  if (l === "neoforge") return fromCfg("NEOFORGE_VERSION") ?? pinBuild ?? null;
  return null;
}

// ── plain checklist ────────────────────────────────────────────────────────

export function buildChecklist(opts: { serverName: string; gameLabel: string; gameVersion?: string | null; loaderNote?: string | null; mods: ProfileMod[] }): string {
  const need = opts.mods.filter((m) => m.clientRequired !== false);
  const serverOnly = opts.mods.filter((m) => m.clientRequired === false);
  const lines: string[] = [];
  lines.push(`Mods for ${opts.serverName} (${opts.gameLabel}${opts.gameVersion ? ` ${opts.gameVersion}` : ""})`);
  lines.push("");
  if (opts.loaderNote) lines.push(opts.loaderNote, "");
  if (need.length) {
    lines.push("Install these on your own game — the SAME versions, or the server may refuse to let you join:");
    for (const m of need) lines.push(`  [ ] ${m.name} ${m.version}${m.clientRequired === null ? " (may be optional)" : ""}${m.url ? ` — ${m.url}` : ""}`);
  } else {
    lines.push("You don't need to install anything — join with your normal game.");
  }
  if (serverOnly.length) {
    lines.push("", "Runs on the server only (nothing for you to install):");
    for (const m of serverOnly) lines.push(`  - ${m.name} ${m.version}`);
  }
  return lines.join("\n") + "\n";
}

/** Stable hash input for "has the client-visible mod list changed?". */
export function modsFingerprint(mods: ProfileMod[]): string {
  return mods
    .map((m) => `${m.key}@${m.version}:${m.clientRequired}`)
    .sort()
    .join("|");
}

