/**
 * Mod auto-update apply engine: snapshot → stage+swap → restart → health-check
 * → automatic rollback. All side effects are injected (EngineIO), so
 * test/mod-autoupdate.test.ts drives it with a LocalGuestFs and fake
 * restart/health functions; worker/mod-autoupdate.ts passes the real ones.
 *
 * Steps:
 *  1. SNAPSHOT every mod directory the family's installer manages (never the
 *     world, never the game root) plus the engine's state file into one zip on
 *     the guest (/root/.nxeon-mods/autoupdate/<stamp>.zip, newest 3 kept),
 *     and hold it in memory. Too big to snapshot safely → nothing is changed.
 *  2. APPLY each update through the one-click install engine
 *     (lib/mods/engine.ts installOrUpdate) with the resolver's chosen builds:
 *     mirror-first verified download (NX Labs mirror via resolveLocal, then
 *     upstream, hash-checked where the source publishes hashes), staged
 *     `.nxeon-part` writes + rename, state file update. A failed apply →
 *     restore the snapshot; the game was never restarted.
 *  3. RESTART through the platform's game control path, then HEALTH-check
 *     (service active + game port answering — the same checks GAME_POWER uses).
 *  4. Unhealthy → RESTORE the snapshot exactly (files the update added are
 *     removed, every original file is written back byte-for-byte), restart,
 *     health-check again, and report ROLLED_BACK with the reason.
 *
 * "Atomic" here means: per file, a rename; per update set, the snapshot — the
 * server ends either on the full new set (healthy) or on the full old set.
 */
import { createHash } from "node:crypto";
import type { GuestFs } from "../mods/guest-fs";
import { isWithin } from "../mods/paths";
import { readZip } from "../mods/archive";
import { STATE_PATH } from "../mods/engine";
import type { CatalogFacts, Layout, OpResult, ResolvedPackage, Resolution } from "../mods/types";
import type { CandidateVersion, Decision, InstalledPkg, Universe } from "./types";
import { writeZip } from "./zip";

export const SNAPSHOT_DIR = "/root/.nxeon-mods/autoupdate";
export const SNAPSHOT_MAX_BYTES = 768 * 1024 * 1024;
export const SNAPSHOT_MAX_FILES = 20_000;
const KEEP_SNAPSHOTS = 3;

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

export type Snapshot = { path: string | null; dirs: string[]; files: Map<string, Buffer>; bytes: number };

/** The directories an update may touch: the layout's named mod dirs, never its base/root. */
export function managedDirs(layout: Layout): string[] {
  const out = new Set<string>();
  for (const [name, d] of Object.entries(layout.dirs)) {
    if (name === "root" || d === layout.base) continue;
    if (!isWithin(layout.base, d)) continue;
    out.add(d);
  }
  return [...out].sort();
}

async function walk(fs: GuestFs, dir: string, out: string[], depth = 0, budget = { files: 0 }): Promise<void> {
  if (depth > 12) throw new Error(`${dir} is nested too deeply to snapshot`);
  for (const n of await fs.list(dir)) {
    if (n === "." || n === ".." || n.includes("/")) continue;
    const p = `${dir}/${n}`;
    const st = await fs.stat(p);
    if (!st) continue;
    if (st.type === "dir") await walk(fs, p, out, depth + 1, budget);
    else {
      if (p.endsWith(".nxeon-part")) continue;
      out.push(p);
      if (++budget.files > SNAPSHOT_MAX_FILES) throw new Error(`more than ${SNAPSHOT_MAX_FILES} files in the mod folders`);
    }
  }
}

export async function takeSnapshot(fs: GuestFs, dirs: string[], now: Date, persist = true): Promise<Snapshot> {
  const files = new Map<string, Buffer>();
  let bytes = 0;
  const paths: string[] = [];
  for (const d of dirs) if ((await fs.stat(d))?.type === "dir") await walk(fs, d, paths);
  if ((await fs.stat(STATE_PATH))?.type === "file") paths.push(STATE_PATH);
  for (const p of paths) {
    const st = await fs.stat(p);
    if (!st) continue;
    bytes += st.size;
    if (bytes > SNAPSHOT_MAX_BYTES) throw new Error(`the mod folders are over ${SNAPSHOT_MAX_BYTES / 1048576} MB — too big to snapshot safely`);
    const b = await fs.readFile(p, SNAPSHOT_MAX_BYTES);
    if (!b) throw new Error(`couldn't read ${p} for the snapshot`);
    files.set(p, b);
  }
  let path: string | null = null;
  if (persist) {
    path = `${SNAPSHOT_DIR}/${now.toISOString().replace(/[:.]/g, "-")}.zip`;
    const zip = writeZip([...files].map(([p, data]) => ({ name: p.replace(/^\//, ""), data, store: /\.(jar|zip|dll)$/i.test(p) })), now);
    await fs.writeFile(`${path}.nxeon-part`, zip);
    await fs.rename(`${path}.nxeon-part`, path);
    const old = (await fs.list(SNAPSHOT_DIR)).filter((n) => /^\d{4}-.*\.zip$/.test(n)).sort();
    for (const n of old.slice(0, Math.max(0, old.length - KEEP_SNAPSHOTS))) await fs.remove(`${SNAPSHOT_DIR}/${n}`);
  }
  return { path, dirs, files, bytes };
}

/** Read a persisted snapshot zip back (admin/manual restore). */
export function snapshotFromZip(zip: Buffer, dirs: string[]): Snapshot {
  const files = new Map<string, Buffer>();
  let bytes = 0;
  for (const e of readZip(zip, { maxEntries: SNAPSHOT_MAX_FILES + 1, maxEntryBytes: 512 * 1024 * 1024, maxTotalBytes: SNAPSHOT_MAX_BYTES, maxRatio: 2000 })) {
    if (e.dir) continue;
    const p = "/" + e.path.join("/");
    files.set(p, e.data);
    bytes += e.data.length;
  }
  return { path: null, dirs, files, bytes };
}

/** Put the managed dirs back exactly as snapshotted. Returns true when a re-walk matches. */
export async function restoreSnapshot(fs: GuestFs, snap: Snapshot): Promise<{ ok: boolean; detail: string }> {
  const now: string[] = [];
  for (const d of snap.dirs) if ((await fs.stat(d))?.type === "dir") await walk(fs, d, now);
  let removed = 0;
  let written = 0;
  for (const p of now) {
    if (!snap.files.has(p)) {
      await fs.remove(p);
      removed++;
    }
  }
  for (const [p, data] of snap.files) {
    const cur = await fs.readFile(p, SNAPSHOT_MAX_BYTES).catch(() => null);
    if (cur && cur.length === data.length && sha256(cur) === sha256(data)) continue;
    await fs.writeFile(`${p}.nxeon-part`, data);
    await fs.rename(`${p}.nxeon-part`, p);
    written++;
  }
  // Verify.
  const after: string[] = [];
  for (const d of snap.dirs) if ((await fs.stat(d))?.type === "dir") await walk(fs, d, after);
  const expected = [...snap.files.keys()].filter((p) => p !== STATE_PATH).sort();
  const got = after.sort();
  const same = expected.length === got.length && expected.every((p, i) => p === got[i]);
  return { ok: same, detail: `restored ${written} file(s), removed ${removed} added file(s)${same ? "" : " — but the folder still differs from the snapshot"}` };
}

// ── decisions → install-engine resolutions ────────────────────────────────────

export type ApplyItem = {
  modId: string;
  facts: CatalogFacts;
  resolution: Resolution;
  label: string;
  changes: { name: string; from: string | null; to: string; key: string }[];
};

function toPackage(c: CandidateVersion, name: string, root: boolean, known: Set<string>, universe: Universe): ResolvedPackage | null {
  if (!c.file || !c.placement) return null;
  return {
    key: c.key,
    name,
    version: c.version,
    versionId: c.versionId,
    file: c.file,
    placement: c.placement,
    requires: c.deps.filter((d) => d.kind === "required" && known.has(d.key)).map((d) => d.key),
    incompatible: c.deps.filter((d) => d.kind === "incompatible").map((d) => ({ key: d.key, name: universe[d.key]?.name ?? d.name ?? d.key })),
    root,
  };
}

/**
 * Group the plan's changes per ROOT mod into install-engine resolutions.
 * Dependency-only changes ride along with a root that (transitively) needs
 * them; when that root's own installed build can't be re-described (no file
 * info), the dependency change is reported but not applied.
 */
export function buildApplyItems(
  changes: Decision[],
  allDecisions: Decision[],
  installed: InstalledPkg[],
  universe: Universe,
  facts: Map<string, CatalogFacts>,
): { items: ApplyItem[]; skipped: { name: string; reason: string }[] } {
  const skipped: { name: string; reason: string }[] = [];
  const byKey = new Map(allDecisions.map((d) => [d.key, d]));
  const instByKey = new Map(installed.map((p) => [p.key, p]));
  const known = new Set<string>([...installed.map((p) => p.key), ...allDecisions.map((d) => d.key)]);
  const rootsOf = (key: string, seen = new Set<string>()): string[] => {
    if (seen.has(key)) return [];
    seen.add(key);
    const d = byKey.get(key);
    if (d?.root) return [key];
    const parents = d?.requiredBy ?? [];
    return [...new Set(parents.flatMap((p) => rootsOf(p, seen)))];
  };
  const perRoot = new Map<string, Decision[]>();
  for (const c of changes) {
    if (c.root) { perRoot.set(c.key, [...(perRoot.get(c.key) ?? []), c]); continue; }
    const r = rootsOf(c.key)[0];
    if (!r) { skipped.push({ name: c.name, reason: "no installed mod needs it" }); continue; }
    perRoot.set(r, [...(perRoot.get(r) ?? []), c]);
  }
  const items: ApplyItem[] = [];
  for (const [rootKey, ds] of perRoot) {
    const rootD = byKey.get(rootKey);
    const inst = instByKey.get(rootKey);
    const modId = rootD?.modId ?? inst?.modId ?? null;
    const f = modId ? facts.get(modId) : null;
    if (!modId || !f) { for (const d of ds) skipped.push({ name: d.name, reason: "its catalogue entry is missing" }); continue; }
    const rootChange = ds.find((d) => d.root);
    const rootCand = rootChange?.candidate ?? (inst ? (universe[rootKey]?.versions.find((v) => v.versionId === inst.versionId) ?? universe[rootKey]?.versions.find((v) => v.version === inst.version) ?? null) : null);
    if (!rootCand) { for (const d of ds) skipped.push({ name: d.name, reason: `rides along with ${rootD?.name ?? rootKey}, whose installed build couldn't be looked up` }); continue; }
    const pkgs: ResolvedPackage[] = [];
    let bad: string | null = null;
    // Dependencies first (deepest first by requiredBy distance is not needed: the engine writes all before saving state).
    for (const d of ds.filter((x) => !x.root)) {
      const p = d.candidate ? toPackage(d.candidate, d.name, false, known, universe) : null;
      if (!p) { bad = `${d.name} ${d.to} has no downloadable file we can verify`; break; }
      pkgs.push(p);
    }
    const rp = toPackage(rootCand, f.name, true, known, universe);
    if (!rp) bad = bad ?? `${f.name} ${rootCand.version} has no downloadable file we can verify`;
    if (bad || !rp) { for (const d of ds) skipped.push({ name: d.name, reason: bad! }); continue; }
    pkgs.push(rp);
    items.push({
      modId,
      facts: f,
      resolution: { packages: pkgs, notes: [] },
      label: f.name,
      changes: ds.map((d) => ({ name: d.name, from: d.from, to: d.to!, key: d.key })),
    });
  }
  return { items, skipped };
}

// ── the run ─────────────────────────────────────────────────────────────────

export type EngineIO = {
  fs: GuestFs;
  layout: Layout;
  apply(item: ApplyItem): Promise<OpResult>;
  restart(): Promise<{ ok: boolean; detail: string }>;
  health(): Promise<{ ok: boolean; detail: string }>;
  now(): Date;
  progress?(step: string, pct: number): void | Promise<void>;
  /** Write the zip to the guest (default true). */
  persistSnapshot?: boolean;
};

export type ApplyOutcome = {
  status: "APPLIED" | "ROLLED_BACK" | "FAILED" | "NOOP";
  applied: { name: string; from: string | null; to: string; key: string }[];
  reason: string;
  snapshotPath: string | null;
  /** After a rollback: did the old set come back healthy? */
  rollbackHealthy?: boolean;
  failedMod?: string | null;
  notes: string[];
};

export async function applyUpdateSet(io: EngineIO, items: ApplyItem[]): Promise<ApplyOutcome> {
  if (!items.length) return { status: "NOOP", applied: [], reason: "Nothing to update.", snapshotPath: null, notes: [] };
  const notes: string[] = [];
  const dirs = managedDirs(io.layout);
  await io.progress?.("Snapshotting your mod folders", 5);
  let snap: Snapshot;
  try {
    snap = await takeSnapshot(io.fs, dirs, io.now(), io.persistSnapshot ?? true);
  } catch (e) {
    return { status: "FAILED", applied: [], reason: `Couldn't take a safety snapshot of the mod folders (${(e as Error).message}) — nothing was changed.`, snapshotPath: null, notes };
  }

  const applied: ApplyOutcome["applied"] = [];
  let i = 0;
  for (const it of items) {
    i++;
    await io.progress?.(`Updating ${it.label}`, 10 + Math.round((50 * i) / items.length));
    let r: OpResult;
    try {
      r = await io.apply(it);
    } catch (e) {
      r = { ok: false, error: (e as Error).message };
    }
    if (!r.ok) {
      const back = await restoreSnapshot(io.fs, snap).catch((e) => ({ ok: false, detail: String((e as Error).message) }));
      return {
        status: "FAILED",
        applied: [],
        failedMod: it.label,
        reason: `Updating ${it.label} failed (${r.error}). The mod folders were restored from the snapshot (${back.detail}); the server was not restarted.`,
        snapshotPath: snap.path,
        notes,
      };
    }
    notes.push(...r.notes);
    applied.push(...it.changes);
  }

  await io.progress?.("Restarting the server", 70);
  const rs = await io.restart().catch((e) => ({ ok: false, detail: String((e as Error).message) }));
  const hc = rs.ok ? await io.health().catch((e) => ({ ok: false, detail: String((e as Error).message) })) : { ok: false, detail: rs.detail };
  if (rs.ok && hc.ok) {
    await io.progress?.("Done", 100);
    return { status: "APPLIED", applied, reason: `Updated ${applied.length} mod${applied.length === 1 ? "" : "s"}; the server restarted and is answering (${hc.detail}).`, snapshotPath: snap.path, notes };
  }

  // ── rollback ──────────────────────────────────────────────────────────────
  await io.progress?.("The server didn't come back — rolling back", 80);
  const back = await restoreSnapshot(io.fs, snap).catch((e) => ({ ok: false, detail: String((e as Error).message) }));
  const rs2 = await io.restart().catch((e) => ({ ok: false, detail: String((e as Error).message) }));
  const hc2 = rs2.ok ? await io.health().catch((e) => ({ ok: false, detail: String((e as Error).message) })) : { ok: false, detail: rs2.detail };
  await io.progress?.("Rolled back", 100);
  const why = rs.ok ? hc.detail : `restart failed: ${rs.detail}`;
  return {
    status: "ROLLED_BACK",
    applied: [],
    reason: hc2.ok
      ? `After updating ${applied.map((a) => `${a.name} ${a.to}`).join(", ")} the server didn't come back (${why}). We restored the previous mods (${back.detail}) and it's running again.`
      : `After updating ${applied.map((a) => `${a.name} ${a.to}`).join(", ")} the server didn't come back (${why}). We restored the previous mods (${back.detail}) but it still isn't answering (${hc2.detail}) — our team has been alerted.`,
    rollbackHealthy: hc2.ok,
    snapshotPath: snap.path,
    notes,
  };
}

