 *  - Thunderstore (Valheim): the package's latest version plus the installed
 *    one; dependency strings become minimum ranges (">=1.2.3"), which is how
 *    Thunderstore's mod managers treat them;
 *  - anything else the install engine supports (SpigotMC, uMod, CS2, Factorio…):
 *    the family installer's own resolve() — the newest build it would install
 *    today — as a one-version list;
 *  - the NX Labs catalogue (ModVersion rows) as a fallback when an upstream
 *    doesn't answer, and to tag builds the local mirror holds.
 *
 * The fetcher is injected (lib/mods/safe-fetch.ts in production — allowlisted
 * https hosts, size caps), the catalogue query too, so tests can run offline.
 */
import { fetchJson, type Fetcher } from "../mods/safe-fetch";
import { acceptedLoaders, isModVariant, isPluginVariant } from "../mods/installers/minecraft";
import { isLoaderPack, parseDepString } from "../mods/installers/valheim";
import type { CatalogFacts, FamilyInstaller, InstallerCtx } from "../mods/types";
import type { CandidateVersion, DepSpec, InstalledPkg, ProjectInfo, Universe } from "./types";

export type CatalogVersionRow = {
  id: string;
  gameModId: string;
  versionId: string;
  versionNumber: string;
  channel: string;
  gameVersions: string[];
  loaders: string[];
  fileName: string | null;
  fileUrl: string | null;
  fileBytes: number | null;
  sha1: string | null;
  sha256: string | null;
  sha512: string | null;
  dependencies: unknown;
  publishedAt: Date | null;
  mirrorState: string;
};

export type LoadCtx = {
  family: string;
  variant: string | null;
  gameVersion: string | null;
  installed: InstalledPkg[];
  /** GameMod facts for every installed ROOT, by GameMod id. */
  mods: Map<string, CatalogFacts>;
  fetcher: Fetcher;
  /** Install-engine context for the generic path (installer.resolve). */
  installer?: FamilyInstaller | null;
  installerCtx?: InstallerCtx | null;
  /** NX Labs catalogue rows for a set of GameMod ids. */
  catalog?: (gameModIds: string[]) => Promise<CatalogVersionRow[]>;
  maxProjects?: number;
  log?: (m: string) => void;
};

const MR = "https://api.modrinth.com/v2";
const TS = "https://thunderstore.io/api/experimental/package";
const enc = (v: unknown) => encodeURIComponent(JSON.stringify(v));
const chan = (c: string | undefined | null): CandidateVersion["channel"] => (c === "beta" ? "beta" : c === "alpha" ? "alpha" : c === "snapshot" ? "snapshot" : "release");

function mcPlacement(variant: string | null, loaders: string[], projectType: string | null): string {
  if (projectType === "modpack") return "mrpack";
  if (projectType === "datapack" || (loaders.length === 1 && loaders[0] === "datapack")) return "datapack";
  if (isPluginVariant(variant)) return "plugin-jar";
  if (isModVariant(variant)) return loaders.includes("datapack") && !loaders.some((l) => acceptedLoaders(variant).includes(l)) ? "datapack" : "mod-jar";
  return "datapack";
}

type MrVersion = {
  id: string; project_id: string; version_number: string; version_type: string; game_versions: string[]; loaders: string[]; date_published?: string;
  files: { url: string; filename: string; primary: boolean; size: number; hashes: { sha1?: string; sha512?: string } }[];
  dependencies: { version_id: string | null; project_id: string | null; dependency_type: string }[];
};
type MrProject = { id: string; slug: string; title: string; project_type: string; client_side?: string; server_side?: string; categories?: string[] };

function mrDeps(v: { dependencies?: MrVersion["dependencies"] }, versionToProject: Map<string, string>): DepSpec[] {
  const out: DepSpec[] = [];
  for (const d of v.dependencies ?? []) {
    const pid = d.project_id ?? (d.version_id ? versionToProject.get(d.version_id) ?? null : null);
    if (!pid) continue;
    const kind = d.dependency_type === "required" ? "required" : d.dependency_type === "incompatible" ? "incompatible" : d.dependency_type === "embedded" ? "embedded" : "optional";
    out.push({ key: `modrinth:${pid}`, kind, versionId: d.version_id ?? null });
  }
  return out;
}

function mrCandidate(v: MrVersion, variant: string | null, projectType: string | null, versionToProject: Map<string, string>): CandidateVersion {
  const f = v.files.find((x) => x.primary) ?? v.files[0];
  return {
    key: `modrinth:${v.project_id}`,
    versionId: v.id,
    version: v.version_number,
    channel: chan(v.version_type),
    gameVersions: v.game_versions ?? [],
    loaders: (v.loaders ?? []).map((l) => l.toLowerCase()),
    publishedAt: v.date_published ? Date.parse(v.date_published) : null,
    deps: mrDeps(v, versionToProject),
    file: f ? { url: f.url, filename: f.filename, size: f.size ?? null, hashes: { sha1: f.hashes?.sha1, sha512: f.hashes?.sha512 }, mirrorKey: { source: "modrinth", projectId: v.project_id, versionId: v.id } } : null,
    placement: mcPlacement(variant, (v.loaders ?? []).map((l) => l.toLowerCase()), projectType),
  };
}

export function catalogRowToCandidate(key: string, r: CatalogVersionRow, source: string, variant: string | null, family: string): CandidateVersion {
  const deps: DepSpec[] = [];
  if (Array.isArray(r.dependencies)) {
    for (const d of r.dependencies as Record<string, unknown>[]) {
      if (source === "modrinth" && typeof d.project_id === "string") {
        const t = String(d.dependency_type ?? "optional");
        deps.push({ key: `modrinth:${d.project_id}`, kind: t === "required" ? "required" : t === "incompatible" ? "incompatible" : t === "embedded" ? "embedded" : "optional", versionId: typeof d.version_id === "string" ? d.version_id : null });
      }
    }
  }
  return {
    key,
    versionId: r.versionId,
    version: r.versionNumber,
    channel: chan(r.channel),
    gameVersions: r.gameVersions,
    loaders: r.loaders.map((l) => l.toLowerCase()),
    publishedAt: r.publishedAt ? r.publishedAt.getTime() : null,
    deps,
    file: r.fileUrl && r.fileName ? { url: r.fileUrl, filename: r.fileName, size: r.fileBytes, hashes: { sha1: r.sha1 ?? undefined, sha256: r.sha256 ?? undefined, sha512: r.sha512 ?? undefined }, mirrorKey: { source, projectId: key.replace(/^[a-z_]+:/, ""), versionId: r.versionId } } : null,
    placement: family === "minecraft" ? mcPlacement(variant, r.loaders.map((l) => l.toLowerCase()), null) : null,
    catalogRowId: r.id,
  };
}

async function loadModrinth(key: string, ctx: LoadCtx, inst: InstalledPkg | undefined, v2p: Map<string, string>): Promise<ProjectInfo | null> {
  const pid = key.slice("modrinth:".length);
  const project = await fetchJson<MrProject>(ctx.fetcher, `${MR}/project/${encodeURIComponent(pid)}`);
  const isPack = project.project_type === "modpack";
  const loaders = isPack ? [] : project.project_type === "datapack" ? ["datapack"] : acceptedLoaders(ctx.variant).length ? [...acceptedLoaders(ctx.variant), "datapack"] : ["datapack"];
  const q = `${MR}/project/${encodeURIComponent(project.id)}/version?${loaders.length ? `loaders=${enc(loaders)}` : ""}${ctx.gameVersion ? `${loaders.length ? "&" : ""}game_versions=${enc([ctx.gameVersion])}` : ""}`;
  let versions = (await fetchJson<MrVersion[]>(ctx.fetcher, q)).slice(0, 40);
  if (inst?.versionId && !versions.some((v) => v.id === inst.versionId)) {
    const iv = await fetchJson<MrVersion>(ctx.fetcher, `${MR}/version/${encodeURIComponent(inst.versionId)}`).catch(() => null);
    if (iv) versions = [...versions, iv];
  }
  // Dependencies given only by version id → their project ids (bounded).
  const unknown = [...new Set(versions.flatMap((v) => v.dependencies ?? []).filter((d) => !d.project_id && d.version_id && !v2p.has(d.version_id)).map((d) => d.version_id!))].slice(0, 20);
  if (unknown.length) {
    const vs = await fetchJson<MrVersion[]>(ctx.fetcher, `${MR}/versions?ids=${enc(unknown)}`).catch(() => [] as MrVersion[]);
    for (const v of vs) v2p.set(v.id, v.project_id);
  }
  return {
    key: `modrinth:${project.id}`,
    name: project.title,
    versions: versions.map((v) => mrCandidate(v, ctx.variant, project.project_type, v2p)),
    clientSide: project.client_side ?? null,
    serverSide: project.server_side ?? null,
    categories: project.categories ?? [],
    isModpack: isPack,
  };
}

type HangarVersion = {
  name: string; createdAt?: string; channel?: { name: string };
  downloads: Record<string, { fileInfo?: { name: string; sizeBytes: number; sha256Hash: string } | null; downloadUrl?: string | null }>;
  pluginDependencies?: Record<string, { name: string; required: boolean }[]>;
  platformDependencies?: Record<string, string[]>;
};

async function loadHangar(key: string, ctx: LoadCtx): Promise<ProjectInfo | null> {
  const slug = key.slice("hangar:".length);
  const page = await fetchJson<{ result: HangarVersion[] }>(ctx.fetcher, `https://hangar.papermc.io/api/v1/projects/${encodeURIComponent(slug)}/versions?limit=25&offset=0&platform=PAPER${ctx.gameVersion ? `&platformVersion=${encodeURIComponent(ctx.gameVersion)}` : ""}`);
  const versions: CandidateVersion[] = [];
  for (const v of page.result ?? []) {
    const dl = v.downloads?.PAPER;
    const ch = (v.channel?.name ?? "Release").toLowerCase();
    versions.push({
      key,
      versionId: v.name,
      version: v.name,
      channel: ch === "release" ? "release" : ch === "snapshot" ? "snapshot" : "beta",
      gameVersions: v.platformDependencies?.PAPER ?? [],
      loaders: ["paper", "purpur", "folia"],
      publishedAt: v.createdAt ? Date.parse(v.createdAt) : null,
      deps: (v.pluginDependencies?.PAPER ?? []).map((d) => ({ key: `hangar:${d.name.toLowerCase()}`, kind: d.required ? "required" : "optional", name: d.name })),
      file: dl?.fileInfo && dl.downloadUrl ? { url: dl.downloadUrl, filename: dl.fileInfo.name, size: dl.fileInfo.sizeBytes, hashes: { sha256: dl.fileInfo.sha256Hash }, mirrorKey: { source: "hangar", projectId: slug, versionId: v.name } } : null,
      placement: "plugin-jar",
    });
  }
  return { key, name: slug, versions };
}

type TsVersion = { namespace: string; name: string; version_number: string; full_name: string; download_url: string; dependencies: string[]; file_size?: number; date_created?: string };
type TsPackage = { namespace: string; name: string; full_name: string; is_deprecated?: boolean; latest: TsVersion; community_listings?: { community: string; categories?: string[] }[] };

function tsDeps(v: TsVersion): DepSpec[] {
  const out: DepSpec[] = [];
  for (const d of v.dependencies ?? []) {
    const p = parseDepString(d);
    if (!p || isLoaderPack(p.namespace, p.name)) continue;
    out.push({ key: `thunderstore:${p.namespace}-${p.name}`, kind: "required", range: `>=${p.version}`, name: `${p.namespace}-${p.name}` });
  }
  return out;
}
function tsCandidate(v: TsVersion): CandidateVersion {
  return {
    key: `thunderstore:${v.namespace}-${v.name}`,
    versionId: v.version_number,
    version: v.version_number,
    channel: "release",
    gameVersions: [],
    loaders: [],
    publishedAt: v.date_created ? Date.parse(v.date_created) : null,
    deps: tsDeps(v),
    file: { url: v.download_url, filename: `${v.full_name}.zip`, size: v.file_size ?? null, hashes: {}, mirrorKey: { source: "thunderstore", projectId: `${v.namespace}-${v.name}`, versionId: v.version_number } },
    placement: "bepinex",
  };
}

async function loadThunderstore(key: string, ctx: LoadCtx, inst: InstalledPkg | undefined): Promise<ProjectInfo | null> {
  const id = key.slice("thunderstore:".length);
  const [ns, name] = id.split("-");
  if (!ns || !name) return null;
  const p = await fetchJson<TsPackage>(ctx.fetcher, `${TS}/${encodeURIComponent(ns)}/${encodeURIComponent(name)}/`);
  const versions = [tsCandidate(p.latest)];
  if (inst && inst.version !== p.latest.version_number && /^\d+\.\d+\.\d+$/.test(inst.version)) {
    const iv = await fetchJson<TsVersion>(ctx.fetcher, `${TS}/${encodeURIComponent(ns)}/${encodeURIComponent(name)}/${encodeURIComponent(inst.version)}/`).catch(() => null);
    if (iv) versions.push(tsCandidate(iv));
  }
  const cats = (p.community_listings ?? []).filter((c) => c.community === "valheim").flatMap((c) => c.categories ?? []);
  return { key, name: p.full_name, versions, categories: cats, unverifiedSource: true };
}

/** Generic: what the family installer would install today, as a one-version list. */
async function loadViaInstaller(mod: CatalogFacts, ctx: LoadCtx): Promise<ProjectInfo[]> {
  if (!ctx.installer || !ctx.installerCtx) return [];
  const res = await ctx.installer.resolve(mod, ctx.installerCtx);
  if ("error" in res) throw new Error(res.error);
  return res.packages.map((p) => ({
    key: p.key,
    name: p.name,
    unverifiedSource: !p.file.hashes.sha1 && !p.file.hashes.sha256 && !p.file.hashes.sha512,
    versions: [
      {
        key: p.key,
        versionId: p.versionId ?? p.version,
        version: p.version,
        channel: "release" as const,
        gameVersions: [],
        loaders: [],
        publishedAt: null,
        deps: [...p.requires.map((k) => ({ key: k, kind: "required" as const })), ...p.incompatible.map((x) => ({ key: x.key, kind: "incompatible" as const, name: x.name }))],
        file: p.file,
        placement: p.placement,
      },
    ],
  }));
}

/** Build the Universe. Never throws: a project whose source fails is simply absent ("unknown"). */
export async function loadUniverse(ctx: LoadCtx): Promise<{ universe: Universe; errors: string[] }> {
  const universe: Universe = {};
  const errors: string[] = [];
  const max = ctx.maxProjects ?? 60;
  const inst = new Map(ctx.installed.map((p) => [p.key, p]));
  const v2p = new Map<string, string>();
  const queue: string[] = ctx.installed.filter((p) => !p.disabled).map((p) => p.key);
  const seen = new Set<string>();
  const rootMod = new Map<string, CatalogFacts>();
  for (const p of ctx.installed) if (p.root && p.modId && ctx.mods.get(p.modId)) rootMod.set(p.key, ctx.mods.get(p.modId)!);

  // Catalogue rows (fallback + mirror tags), one query.
  let catalog: CatalogVersionRow[] = [];
  if (ctx.catalog) {
    const ids = [...rootMod.values()].map((m) => m.id);
    catalog = ids.length ? await ctx.catalog(ids).catch(() => []) : [];
  }

  while (queue.length && seen.size < max) {
    const key = queue.shift()!;
    if (seen.has(key)) continue;
    seen.add(key);
    let info: ProjectInfo | null = null;
    try {
      if (key.startsWith("modrinth:")) info = await loadModrinth(key, ctx, inst.get(key), v2p);
      else if (key.startsWith("hangar:")) info = await loadHangar(key, ctx);
      else if (key.startsWith("thunderstore:")) info = await loadThunderstore(key, ctx, inst.get(key));
      else if (rootMod.has(key)) {
        for (const pi of await loadViaInstaller(rootMod.get(key)!, ctx)) {
          if (!universe[pi.key]) universe[pi.key] = pi;
          seen.add(pi.key);
        }
        continue;
      }
    } catch (e) {
      errors.push(`${key}: ${(e as Error).message}`.slice(0, 200));
    }
    // Upstream failed (or returned nothing) → the NX Labs catalogue, if it has this mod.
    const mod = rootMod.get(key);
    if ((!info || !info.versions.length) && mod) {
      const rows = catalog.filter((r) => r.gameModId === mod.id);
      if (rows.length) info = { key, name: mod.name, versions: rows.map((r) => catalogRowToCandidate(key, r, mod.source, ctx.variant, ctx.family)) };
    }
    if (!info) continue;
    // Tag builds the catalogue/mirror holds.
    if (mod) {
      for (const v of info.versions) {
        const row = catalog.find((r) => r.gameModId === mod.id && r.versionId === v.versionId);
        if (row) v.catalogRowId = row.id;
      }
    }
    if (info.key !== key) {
      // Canonical key differs (e.g. a slug resolved to a project id) — keep both pointing at it.
      universe[info.key] = { ...info };
    }
    universe[key] = { ...info, key, versions: info.versions.map((v) => ({ ...v, key })) };
    for (const v of info.versions) for (const d of v.deps) if (d.kind === "required" && !seen.has(d.key)) queue.push(d.key);
  }
  if (queue.length) errors.push(`stopped after ${max} projects`);
  return { universe, errors };
}

