/**
 * Persist the "give this to your players" client profiles (ModClientProfile)
 * and create r2modman share codes. Generation itself is pure
 * (./profile-export.ts); this file is the DB + one upstream call.
 */
import { createHash } from "node:crypto";
import { db } from "../db";
import { fetchJson, type Fetcher } from "../mods/safe-fetch";
import { buildChecklist, buildMrpack, buildR2modmanProfile, modsFingerprint, profileCodePayload, type ProfileMod } from "./profile-export";

export type ProfileInput = {
  serverId: string;
  serverName: string;
  family: string;
  gameLabel: string;
  variant: string | null;
  gameVersion: string | null;
  loaderVersion: string | null;
  mods: ProfileMod[];
  /** Valheim: the BepInExPack players need (name + version), when known. */
  loaderPack?: { name: string; version: string } | null;
};

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const safeName = (s: string) => s.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "server";

export async function saveProfiles(p: ProfileInput): Promise<{ kinds: string[]; changed: boolean; notes: string[] }> {
  const fp = createHash("sha256").update(`${p.family}|${p.variant}|${p.gameVersion}|${p.loaderVersion}|${p.loaderPack?.version ?? ""}|${modsFingerprint(p.mods)}`).digest("hex");
  const settings = await db.modAutoUpdateSettings.findUnique({ where: { serverId: p.serverId }, select: { profileHash: true } });
  const existing = await db.modClientProfile.count({ where: { serverId: p.serverId } });
  if (settings?.profileHash === fp && existing > 0) return { kinds: [], changed: false, notes: [] };

  const base = safeName(p.serverName);
  const rows: { kind: string; fileName: string; contentType: string; data: Buffer; notes: string | null }[] = [];
  const notes: string[] = [];
  if (p.family === "valheim") {
    const r = buildR2modmanProfile(p.serverName, p.mods, p.loaderPack ?? null);
    if (!p.loaderPack) notes.push("BepInExPack's current version couldn't be looked up — players add BepInExPack_Valheim themselves.");
    rows.push({ kind: "r2z", fileName: `${base}.r2z`, contentType: "application/zip", data: r.data, notes: [...r.skipped.map((s) => `Not in the profile: ${s}`), ...notes].join("\n") || null });
  }
  if (p.family === "minecraft" && p.variant && ["fabric", "quilt", "forge", "neoforge"].includes(p.variant) && p.gameVersion) {
    if (p.loaderVersion) {
      const r = buildMrpack({ name: `${p.serverName} (client)`, versionId: fp.slice(0, 12), summary: `Client mods for ${p.serverName}`, mcVersion: p.gameVersion, loader: p.variant, loaderVersion: p.loaderVersion, mods: p.mods });
      if ("error" in r) notes.push(r.error);
      else rows.push({ kind: "mrpack", fileName: `${base}.mrpack`, contentType: "application/x-modrinth-modpack+zip", data: r.data, notes: r.skipped.map((s) => `Not in the pack: ${s}`).join("\n") || null });
    } else notes.push(`The server's ${p.variant} loader version isn't recorded, so a .mrpack can't be built — use the checklist.`);
  }
  const loaderNote =
    p.family === "valheim" ? "First install BepInExPack_Valheim (r2modman or Thunderstore Mod Manager does this for you)."
    : p.family === "minecraft" && p.variant && ["fabric", "quilt", "forge", "neoforge"].includes(p.variant) ? `Use the ${p.variant}${p.loaderVersion ? ` ${p.loaderVersion}` : ""} loader for Minecraft ${p.gameVersion ?? ""}.`.trim()
    : null;
  const text = buildChecklist({ serverName: p.serverName, gameLabel: p.gameLabel, gameVersion: p.gameVersion, loaderNote, mods: p.mods });
  rows.push({ kind: "checklist", fileName: `${base}-mods.txt`, contentType: "text/plain; charset=utf-8", data: Buffer.from(text, "utf8"), notes: notes.join("\n") || null });

  for (const r of rows) {
    await db.modClientProfile.upsert({
      where: { serverId_kind: { serverId: p.serverId, kind: r.kind } },
      create: { serverId: p.serverId, kind: r.kind, fileName: r.fileName, contentType: r.contentType, data: r.data, sha256: sha(r.data), modsHash: fp, notes: r.notes },
      // A new file invalidates the old share code.
      update: { fileName: r.fileName, contentType: r.contentType, data: r.data, sha256: sha(r.data), modsHash: fp, notes: r.notes, shareCode: null, generatedAt: new Date() },
    });
  }
  await db.modClientProfile.deleteMany({ where: { serverId: p.serverId, kind: { notIn: rows.map((r) => r.kind) } } });
  await db.modAutoUpdateSettings.upsert({ where: { serverId: p.serverId }, create: { serverId: p.serverId, profileHash: fp }, update: { profileHash: fp } });
  return { kinds: rows.map((r) => r.kind), changed: true, notes };
}

/**
 * Upload the r2z to Thunderstore's legacy profile endpoint (what r2modman's
 * "Export as code" does) and keep the returned code. Codes expire upstream
 * after a while; the UI says so and offers the file as the lasting option.
 */
export async function createShareCode(serverId: string, fetcher: Fetcher): Promise<{ code: string } | { error: string }> {
  const row = await db.modClientProfile.findUnique({ where: { serverId_kind: { serverId, kind: "r2z" } } });
  if (!row) return { error: "No r2modman profile yet — run a mod check first." };
  if (row.shareCode) return { code: row.shareCode };
  try {
    const r = await fetchJson<{ key?: string }>(fetcher, "https://thunderstore.io/api/experimental/legacyprofile/create/", {
      method: "POST",
      headers: { "Content-Type": "application/octet-stream" },
      body: profileCodePayload(Buffer.from(row.data)),
      maxBytes: 64 * 1024,
    });
    const code = typeof r.key === "string" && /^[A-Za-z0-9-]{8,64}$/.test(r.key) ? r.key : null;
    if (!code) return { error: "Thunderstore didn't return a profile code — download the .r2z file instead." };
    await db.modClientProfile.update({ where: { id: row.id }, data: { shareCode: code } });
    return { code };
  } catch (e) {
    return { error: `Thunderstore didn't answer (${(e as Error).message}) — download the .r2z file instead.` };
  }
}

