/**
 * What a server "is" for compatibility purposes. Pure.
 *
 *  Minecraft: loader = itzg TYPE (McJarPin.type when the jar is pinned, else
 *             Server.gameVariant); game version = McJarPin.mcVersion, else the
 *             pinned VERSION, else what the guest's own log says it started as.
 *             Mod loaders are strict (a build that lists no game versions is
 *             refused); plugin servers accept loader-matching builds.
 *  Valheim:   loader = BepInEx; Thunderstore publishes no game-version data,
 *             so the game version is "the current build" (null) and every
 *             decision says so.
 *  Others:    the family's variant, no version filtering (the installer's own
 *             resolve() already picked what loads there).
 */
import { acceptedLoaders, isModVariant } from "../mods/installers/minecraft";
import type { Target } from "./types";

export function buildTarget(input: {
  family: string;
  variant: string | null;
  pin?: { type: string; mcVersion: string; state: string } | null;
  pinnedVersion?: string | null;
  detectedVersion?: string | null;
}): Target {
  const fam = input.family;
  if (fam === "minecraft") {
    const pinOk = input.pin && input.pin.state !== "FALLBACK" ? input.pin : null;
    const loader = (pinOk?.type ?? input.variant ?? "vanilla").toLowerCase();
    const gv = pinOk?.mcVersion ?? input.pinnedVersion ?? input.detectedVersion ?? null;
    const accepted = acceptedLoaders(loader);
    return {
      family: fam,
      gameVersion: gv,
      loader,
      acceptedLoaders: accepted.length ? [...accepted, "datapack"] : ["datapack"],
      strictGameVersion: isModVariant(loader),
    };
  }
  if (fam === "valheim") return { family: fam, gameVersion: null, loader: "bepinex", acceptedLoaders: [], strictGameVersion: false };
  return { family: fam, gameVersion: input.pinnedVersion ?? input.detectedVersion ?? null, loader: input.variant, acceptedLoaders: [], strictGameVersion: false };
}

