/**
 * The customer-facing update digest (in-app notification + email). Pure.
 * Honest and short: what changed, what players must update on their own game
 * (exact versions), and where the ready-made player profile is.
 */

export type DigestChange = { name: string; from: string | null; to: string; clientRequired: boolean | null };
export type DigestAvailable = { name: string; from: string | null; to: string; clientRequired: boolean | null; reason: string };

export type DigestInput = {
  serverName: string;
  status: "APPLIED" | "ROLLED_BACK" | "FAILED" | "AVAILABLE";
  changes: DigestChange[];
  available: DigestAvailable[];
  noCompatible: { name: string; reason: string }[];
  failureReason?: string | null;
  profileUrl: string;
  sandbox?: boolean;
};

const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

export function buildDigest(d: DigestInput): { title: string; body: string; html: string; subject: string } | null {
  const players = d.changes.filter((c) => c.clientRequired !== false);
  const sb = d.sandbox ? " (sandbox — nothing was restarted)" : "";
  let title: string;
  const lines: string[] = [];
  if (d.status === "APPLIED") {
    if (!d.changes.length) return null;
    title = `Mods updated on ${d.serverName}${sb}`;
    lines.push(`Updated: ${d.changes.map((c) => `${c.name} ${c.from ? `${c.from} → ` : ""}${c.to}`).join(", ")}.`);
    if (players.length) lines.push(`Players must update too: ${players.map((c) => `${c.name} ${c.to}${c.clientRequired === null ? " (if they have it)" : ""}`).join(", ")}. The player profile has the exact versions.`);
    else lines.push("Players don't need to change anything.");
  } else if (d.status === "ROLLED_BACK") {
    title = `Mod update rolled back on ${d.serverName}`;
    lines.push(d.failureReason ?? "The server didn't come back after the update, so the previous mods were restored.");
    lines.push("Nothing changed for players.");
  } else if (d.status === "FAILED") {
    title = `Mod update didn't run on ${d.serverName}`;
    lines.push(d.failureReason ?? "The update could not be applied; nothing was changed.");
  } else {
    if (!d.available.length && !d.noCompatible.length) return null;
    title = d.available.length ? `Mod updates available on ${d.serverName}` : `Some mods on ${d.serverName} have no compatible version`;
    if (d.available.length) {
      lines.push(`Available: ${d.available.map((a) => `${a.name} ${a.from ?? "?"} → ${a.to}`).join(", ")}.`);
      const pl = d.available.filter((a) => a.clientRequired !== false);
      if (pl.length) lines.push(`If you update, players will need: ${pl.map((a) => `${a.name} ${a.to}`).join(", ")}.`);
    }
  }
  if (d.noCompatible.length) lines.push(`No compatible version yet: ${d.noCompatible.map((n) => n.name).join(", ")}.`);
  const body = lines.join(" ");
  const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:1.55;color:#0f172a">
<h2 style="font-size:17px;margin:0 0 12px">${esc(title)}</h2>
${lines.map((l) => `<p style="margin:0 0 10px">${esc(l)}</p>`).join("\n")}
<p style="margin:16px 0 0"><a href="${esc(d.profileUrl)}" style="display:inline-block;background:linear-gradient(90deg,#3b6be8,#7b3fef);color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none">Open mod updates</a></p>
</div>`;
  return { title, body: body.slice(0, 900), html, subject: title };
}

