      const pl = d.available.filter((a) => a.clientRequired !== false);
      if (pl.length) lines.push(`If you update, players will need: ${pl.map((a) => `${a.name} ${a.to}`).join(", ")}.`);
    }
  }
  if (d.noCompatible.length) lines.push(`No compatible version yet: ${d.noCompatible.map((n) => n.name).join(", ")}.`);
  const body = lines.join(" ");
  const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:14px;line-height:1.55;color:#0f172a">
<h2 style="font-size:17px;margin:0 0 12px">${esc(title)}</h2>
${lines.map((l) => `<p style="margin:0 0 10px">${esc(l)}</p>`).join("\n")}
<p style="margin:16px 0 0"><a href="${esc(d.profileUrl)}" style="display:inline-block;background:linear-gradient(90deg,#3b6be8,#7b3fef);color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none">Open mod updates</a></p>
</div>`;
  return { title, body: body.slice(0, 900), html, subject: title };
}

