/**
 * Mod auto-update switches. Three layers, all must allow an automatic change:
 *
 *  ENABLE_MOD_AUTOUPDATE=1        turns the background sweep on at all (default OFF — owner rollout).
 *  MOD_AUTOUPDATE=off             env kill switch: no sweep, no applies (checks on demand still work).
 *  Setting mod_autoupdate_enabled admin kill switch (/admin/mod-updates), default "true";
 *                                 "false" stops every apply fleet-wide immediately.
 *
 * Applying to a REAL guest additionally needs the one-click mod engine's own
 * flag (ENABLE_REAL_GAMEMODS=1) — without it there is no way to write mods to
 * a customer server at all. SANDBOX runs the full pipeline against a fake
 * guest directory instead.
 */
import { SANDBOX } from "../sandbox";

export const SETTING_KEY = "mod_autoupdate_enabled";

const num = (v: string | undefined, d: number, min: number, max: number) => {
  const n = Number(v);
  return Number.isFinite(n) && n >= min && n <= max ? Math.floor(n) : d;
};

export function envConfig() {
  return {
    sweepEnabled: process.env.ENABLE_MOD_AUTOUPDATE === "1",
    envKilled: process.env.MOD_AUTOUPDATE === "off",
    realGuests: SANDBOX || process.env.ENABLE_REAL_GAMEMODS === "1",
    sandbox: SANDBOX,
    nodeCap: num(process.env.MOD_AUTOUPDATE_NODE_CAP, 1, 1, 20),
    globalCap: num(process.env.MOD_AUTOUPDATE_GLOBAL_CAP, 3, 1, 50),
    checkHours: num(process.env.MOD_AUTOUPDATE_CHECK_HOURS, 12, 1, 168),
    perSweep: num(process.env.MOD_AUTOUPDATE_PER_SWEEP, 10, 1, 200),
  };
}

export async function adminKillSwitchOn(): Promise<boolean> {
  try {
    const { getSetting } = await import("../settings");
    return (await getSetting(SETTING_KEY, "true")) === "false";
  } catch {
    return false;
  }
}

/** May anything be applied automatically right now? */
export async function appliesAllowed(): Promise<{ ok: true } | { ok: false; reason: string }> {
  const env = envConfig();
  if (env.envKilled) return { ok: false, reason: "Mod auto-update is switched off platform-wide right now." };
  if (await adminKillSwitchOn()) return { ok: false, reason: "Mod auto-update is paused platform-wide right now." };
  if (!env.realGuests) return { ok: false, reason: "One-click mod changes aren't enabled for this game yet." };
  return { ok: true };
}

