/**
 * Mod auto-update — the worker side.
 *
 *  modAutoUpdateSweep()    registered on the SweepRunner as "mod-autoupdate"
 *                          (worker/index.ts). Picks servers that are due a check
 *                          (MOD_AUTOUPDATE_CHECK_HOURS) or have AUTO updates
 *                          waiting inside their window, and enqueues ONE
 *                          GAME_MOD_AUTOUPDATE job per server — never while the
 *                          server has any job in flight (single-flight), within
 *                          per-node and fleet-wide caps. Cheap DB-only work;
 *                          fire-and-forget safe (its own in-flight guard).
 *  gameModAutoUpdate(job)  the GAME_MOD_AUTOUPDATE handler: read the guest's mod
 *                          state, resolve (lib/mod-autoupdate/resolver.ts),
 *                          record availability, and — for AUTO mods, inside the
 *                          window, with nobody online, when every kill switch
 *                          allows — snapshot → apply → restart → health-check →
 *                          automatic rollback (lib/mod-autoupdate/engine.ts).
 *                          Then: audit row, digest, player profiles.
 *
 * Never touches a server that isn't RUNNING, never restarts for a check, never
 * reports an update that wasn't health-checked.
 */
import { promises as fsp } from "node:fs";
import type { Job, Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { familyFor } from "../lib/game-config";
import { GAME_DISPLAY, type GameFamily } from "../lib/games";
import { controlSpec, logTrackingSpec } from "../lib/game-control";
import { withServerJobLock } from "../lib/job-guard";
import { ENGINE_INSTALLERS } from "../lib/mods/installers";
import { installOrUpdate, loadState, type EngineDeps } from "../lib/mods/engine";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../lib/mods/guest-fs";
import { safeFetch, fetchJson } from "../lib/mods/safe-fetch";
import { dbMirrorLookup, matchesAll, type MirrorLookup } from "../lib/mods/mirror";
import { catalogFacts, serverFacts } from "../lib/mods/facts";
import type { CatalogFacts, FamilyInstaller, Layout } from "../lib/mods/types";
import { resolveLocal } from "../lib/modsync/mirror";
import { refreshRuntime } from "../lib/game-runtime-probe";
import { serviceRunning } from "../lib/game-runtime";
import { sendMail } from "../lib/mailer";
import { appUrl } from "../lib/email-render";
import { appliesAllowed, envConfig } from "../lib/mod-autoupdate/config";
import { loadUniverse, type CatalogVersionRow } from "../lib/mod-autoupdate/candidates";
import { resolveUpdates, changesOf } from "../lib/mod-autoupdate/resolver";
import { buildTarget } from "../lib/mod-autoupdate/target";
import { classifyClient } from "../lib/mod-autoupdate/client-side";
import { effectiveMode, runGate, regionTimezone, inWindow, backoffAfterFailure, MAX_CONSECUTIVE_FAILURES } from "../lib/mod-autoupdate/policy";
import { applyUpdateSet, buildApplyItems, type ApplyOutcome } from "../lib/mod-autoupdate/engine";
import { buildDigest } from "../lib/mod-autoupdate/digest";
import { saveProfiles } from "../lib/mod-autoupdate/profile-store";
import type { ProfileMod } from "../lib/mod-autoupdate/profile-export";
import { loaderVersionFrom } from "../lib/mod-autoupdate/profile-export";
import { isMode, type Decision, type InstalledPkg, type Mode, type Universe } from "../lib/mod-autoupdate/types";
import { SshGuestFs } from "./mods-guest-ssh";
import { gamePower } from "./game-control";
import { notifyAdmins } from "./monitor";

const INFLIGHT = ["QUEUED", "RUNNING"] as const;

// ── sweep ─────────────────────────────────────────────────────────────────────

let sweeping = false;

export async function modAutoUpdateSweep(now = new Date()): Promise<{ enqueued: number; considered: number }> {
  const env = envConfig();
  if (!env.sweepEnabled || env.envKilled) return { enqueued: 0, considered: 0 };
  if (sweeping) return { enqueued: 0, considered: 0 };
  sweeping = true;
  try {
    const servers = await db.server.findMany({
      where: { status: "RUNNING", mods: { some: { status: "INSTALLED" } } },
      select: {
        id: true,
        nodeId: true,
        gamePlan: { select: { gameFamily: true } },
        osTemplate: { select: { family: true } },
        node: { select: { region: true } },
        gameRuntime: { select: { intent: true } },
        modAutoUpdate: true,
        mods: { where: { status: "INSTALLED", availableVersion: { not: null } }, select: { id: true } },
      },
      take: 2000,
    });
    const inflightJobs = await db.job.findMany({ where: { type: "GAME_MOD_AUTOUPDATE", status: { in: [...INFLIGHT] } }, select: { server: { select: { nodeId: true } } } });
    let global = inflightJobs.length;
    const perNode = new Map<string, number>();
    for (const j of inflightJobs) { const n = j.server?.nodeId ?? "?"; perNode.set(n, (perNode.get(n) ?? 0) + 1); }
    let enqueued = 0;
    const due: { id: string; nodeId: string; priority: number }[] = [];
    for (const s of servers) {
      const fam = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "";
      if (!ENGINE_INSTALLERS[fam]) continue;
      if (s.gameRuntime?.intent === "stopped") continue;
      const st = s.modAutoUpdate;
      const mode = (st?.mode ?? "NOTIFY") as Mode;
      if (mode === "OFF") continue;
      const checkDue = !st?.lastCheckAt || now.getTime() - st.lastCheckAt.getTime() > env.checkHours * 3600_000;
      const tz = st?.timezone || regionTimezone(s.node?.region);
      const autoWaiting =
        mode === "AUTO" && s.mods.length > 0 &&
        inWindow(now, tz, st?.windowStart ?? 4, st?.windowEnd ?? 8) &&
        (!st?.nextEligibleAt || st.nextEligibleAt <= now) &&
        (!st?.lastRunAt || now.getTime() - st.lastRunAt.getTime() > 45 * 60_000);
      if (checkDue || autoWaiting) due.push({ id: s.id, nodeId: s.nodeId ?? "?", priority: autoWaiting ? 0 : 1 });
    }
    due.sort((a, b) => a.priority - b.priority);
    for (const d of due) {
      if (enqueued >= env.perSweep || global >= env.globalCap) break;
      if ((perNode.get(d.nodeId) ?? 0) >= env.nodeCap) continue;
      const ok = await withServerJobLock(d.id, async (tx) => {
        const busy = await tx.job.count({ where: { serverId: d.id, status: { in: [...INFLIGHT] } } });
        if (busy) return false;
        await tx.job.create({ data: { type: "GAME_MOD_AUTOUPDATE", serverId: d.id, payload: { trigger: "sweep" } } });
        return true;
      }).catch(() => false);
      if (ok) {
        enqueued++;
        global++;
        perNode.set(d.nodeId, (perNode.get(d.nodeId) ?? 0) + 1);
      }
    }
    if (enqueued) console.log(`[mod-autoupdate] sweep enqueued ${enqueued} job(s) (${due.length} due of ${servers.length} with mods)`);
    return { enqueued, considered: servers.length };
  } finally {
    sweeping = false;
  }
}

/** Queue a check/apply after a successful game version bump (worker/game-update.ts). */
export async function queueAfterGameUpdate(serverId: string): Promise<void> {
  try {
    await db.job.create({ data: { type: "GAME_MOD_AUTOUPDATE", serverId, payload: { trigger: "game-update" } } });
  } catch (e) {
    console.error("[mod-autoupdate] could not queue a post-game-update check", e);
  }
}

// ── helpers ───────────────────────────────────────────────────────────────────

async function playersOnline(serverId: string, family: string): Promise<number | null> {
  if (logTrackingSpec(family)) {
    const c = await db.gameLogCursor.findUnique({ where: { serverId }, select: { onlineCount: true, updatedAt: true } });
    if (!c || Date.now() - c.updatedAt.getTime() > 30 * 60_000) return null;
    return c.onlineCount;
  }
  if (controlSpec(family as GameFamily)?.rcon === "source") {
    return db.playerSession.count({ where: { serverId, leftAt: null, joinedAt: { gt: new Date(Date.now() - 24 * 3600_000) } } });
  }
  return null;
}

/** NX Labs mirror first via resolveLocal (catalogue row id), then K1's lookup, then upstream (engine). */
function mirrorFor(universe: Universe): MirrorLookup {
  const k1 = dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args));
  const rowOf = new Map<string, string>();
  for (const p of Object.values(universe)) for (const v of p.versions) if (v.catalogRowId && v.file) rowOf.set(v.file.url, v.catalogRowId);
  return async (file) => {
    const rowId = rowOf.get(file.url);
    if (rowId) {
      try {
        const abs = await resolveLocal(rowId);
        if (abs) {
          const row = await db.modVersion.findUnique({ where: { id: rowId }, select: { mirrorSha256: true } });
          const bytes = await fsp.readFile(abs);
          if (matchesAll(bytes, file.hashes, row?.mirrorSha256 ?? null)) return bytes;
        }
      } catch (e) {
        console.error("[mod-autoupdate] resolveLocal failed — falling back", (e as Error).message);
      }
    }
    return k1(file);
  };
}

type Loaded = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
async function loadServer(id: string) {
  return db.server.findUnique({
    where: { id },
    include: {
      osTemplate: true,
      gamePlan: true,
      node: true,
      dedicatedIp: true,
      modAutoUpdate: true,
      mods: { include: { mod: true } },
    },
  });
}

function profileUrl(serverId: string) {
  return `${appUrl()}/dashboard/servers/${serverId}?tab=mods#mod-updates`;
}

async function record(serverId: string, trigger: string, status: string, summary: string, extra: Partial<Prisma.ModUpdateRunUncheckedCreateInput> = {}) {
  await db.modUpdateRun.create({ data: { serverId, trigger, status, summary: summary.slice(0, 4000), finishedAt: new Date(), ...extra } }).catch((e) => console.error("[mod-autoupdate] audit row failed", e));
  // Keep the newest 100 per server.
  const old = await db.modUpdateRun.findMany({ where: { serverId }, orderBy: { startedAt: "desc" }, skip: 100, select: { id: true } }).catch(() => []);
  if (old.length) await db.modUpdateRun.deleteMany({ where: { id: { in: old.map((o) => o.id) } } }).catch(() => {});
}

async function settle(serverId: string, data: Prisma.ModAutoUpdateSettingsUncheckedUpdateInput) {
  await db.modAutoUpdateSettings.upsert({ where: { serverId }, create: { serverId, ...(data as object) } as Prisma.ModAutoUpdateSettingsUncheckedCreateInput, update: data });
}

// ── handler ───────────────────────────────────────────────────────────────────

type Payload = { trigger?: string; apply?: boolean; checkOnly?: boolean; by?: string | null };

export async function gameModAutoUpdate(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("mod auto-update: job has no serverId");
  const p = (job.payload ?? {}) as Payload;
  const trigger = p.trigger === "manual" || p.trigger === "game-update" ? p.trigger : "sweep";
  const manualApply = trigger === "manual" && p.apply === true;
  const server = await loadServer(job.serverId);
  if (!server) return;
  const family = familyFor(server);
  const installer = family ? ENGINE_INSTALLERS[family] : null;
  const env = envConfig();
  const step = (text: string, pct: number) => db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});

  if (!family || !installer) {
    await record(server.id, trigger, "NOOP", "Mod updates aren't available for this game (its mods are updated by the game itself, or there is no one-click mod support yet).");
    return;
  }
  if (server.status !== "RUNNING") {
    await record(server.id, trigger, "DEFERRED", "The server isn't running — checked again later.");
    return;
  }
  if (!env.realGuests) {
    await record(server.id, trigger, "DEFERRED", "One-click mod changes aren't enabled for this game yet, so the server wasn't checked.");
    await settle(server.id, { lastCheckAt: new Date(), lastStatus: "DEFERRED", lastDetail: "mod engine not enabled" });
    return;
  }

  let guest: GuestFs | null = null;
  let ssh: SshGuestFs | null = null;
  try {
    await step("Reading your server's mods", 5);
    if (env.sandbox) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, family, server.gameVariant ?? null);
      guest = local;
    } else {
      ssh = await SshGuestFs.open(server as never);
      guest = ssh;
    }
    await runFor(job, server, family, installer, guest, { trigger, manualApply, checkOnly: p.checkOnly === true, step });
  } finally {
    ssh?.close();
  }
}

async function runFor(
  job: Job,
  server: Loaded,
  family: string,
  installer: FamilyInstaller,
  fs: GuestFs,
  o: { trigger: string; manualApply: boolean; checkOnly: boolean; step: (t: string, p: number) => Promise<unknown> },
): Promise<void> {
  const now = new Date();
  const facts = serverFacts(server, family);
  const det = await installer.detect(fs, facts, null);
  if ("error" in det) {
    await record(server.id, o.trigger, "FAILED", `Couldn't read the server's mod folders: ${det.error}`);
    await settle(server.id, { lastCheckAt: now, lastStatus: "FAILED", lastDetail: det.error });
    return;
  }
  const layout: Layout = det;
  const state = await loadState(fs, family);
  const settings = server.modAutoUpdate;
  const serverMode: Mode = isMode(settings?.mode) ? (settings!.mode as Mode) : "NOTIFY";
  const smByMod = new Map(server.mods.map((m) => [m.modId, m]));
  const rootModOf = new Map<string, string>();
  for (const [modId, r] of Object.entries(state.roots)) if (smByMod.has(modId)) rootModOf.set(r.key, modId);

  const installed: InstalledPkg[] = Object.values(state.packages).map((pk) => {
    const modId = rootModOf.get(pk.key) ?? null;
    const sm = modId ? smByMod.get(modId) : null;
    return { key: pk.key, name: sm?.mod.name ?? pk.name, version: pk.version, versionId: pk.versionId, root: !!sm, modId, pinned: sm?.pinned ?? false, disabled: pk.disabled || sm?.status === "DISABLED", requires: pk.requires };
  });
  const factsByMod = new Map<string, CatalogFacts>(server.mods.map((m) => [m.modId, catalogFacts(m.mod)]));

  const pin = family === "minecraft" ? await db.mcJarPin.findUnique({ where: { serverId: server.id } }).catch(() => null) : null;
  const target = buildTarget({ family, variant: server.gameVariant ?? null, pin, pinnedVersion: facts.pinnedVersion, detectedVersion: layout.gameVersion });

  await o.step("Checking for compatible updates", 15);
  const { universe, errors } = await loadUniverse({
    family,
    variant: target.loader,
    gameVersion: target.gameVersion,
    installed,
    mods: factsByMod,
    fetcher: safeFetch,
    installer,
    installerCtx: { server: facts, layout, fetcher: safeFetch },
    catalog: (ids) => db.modVersion.findMany({ where: { gameModId: { in: ids } }, orderBy: { publishedAt: "desc" }, take: 400 }) as Promise<CatalogVersionRow[]>,
  });
  const plan = resolveUpdates(target, installed, universe);
  const changes = changesOf(plan);
  const decisionByKey = new Map(plan.decisions.map((d) => [d.key, d]));

  // ── per-mod facts: client requirement, effective mode, availability ────────
  const clientOf = new Map<string, boolean | null>();
  const modeOf = new Map<string, { mode: Mode; reason: string }>();
  const prevAvailable = new Map(server.mods.map((m) => [m.modId, m.availableVersion]));
  for (const pk of installed) {
    const pi = universe[pk.key];
    const sm = pk.modId ? smByMod.get(pk.modId) : null;
    const cv = classifyClient({ family, source: sm?.mod.source ?? pk.key.split(":")[0], key: pk.key, name: pk.name, variant: target.loader, clientSide: pi?.clientSide, serverSide: pi?.serverSide, categories: [...(pi?.categories ?? []), ...(sm?.mod.categories ?? []), sm?.mod.category ?? ""] });
    clientOf.set(pk.key, cv.required);
    if (!sm || !pk.modId) continue;
    const em = effectiveMode({ serverMode, modOverride: isMode(sm.autoUpdate) ? (sm.autoUpdate as Mode) : null, pinned: sm.pinned, clientRequired: cv.required, clientModsAuto: settings?.clientModsAuto ?? false });
    modeOf.set(pk.key, em);
    const d = decisionByKey.get(pk.key);
    const pkg = state.packages[pk.key];
    const primary = pkg?.files.find((f) => /\.(jar|dll|zip|cs)$/i.test(f.path)) ?? pkg?.files[0];
    await db.serverMod.update({
      where: { id: sm.id },
      data: {
        version: pk.version,
        versionId: pk.versionId,
        fileName: primary ? primary.path.split("/").pop()!.slice(0, 200) : sm.fileName,
        fileSha256: primary?.sha256 ?? sm.fileSha256,
        clientRequired: cv.required,
        clientReason: cv.reason.slice(0, 300),
        availableVersion: d?.action === "update" ? d.to : null,
        availableVersionId: d?.action === "update" ? d.toVersionId : null,
        availableReason: d ? `${d.reason}${em.mode !== serverMode || em.reason.startsWith("Players") || em.reason.startsWith("We can't") ? ` ${em.reason}` : ""}`.slice(0, 2000) : "Not found in the server's mod state.",
        lastCheckAt: now,
      },
    }).catch((e) => console.error("[mod-autoupdate] serverMod update failed", e));
  }
  // Catalogue mods installed before the engine existed (no state entry): say why they aren't checked.
  for (const sm of server.mods) {
    if (sm.status !== "INSTALLED" || [...rootModOf.values()].includes(sm.modId)) continue;
    await db.serverMod.update({ where: { id: sm.id }, data: { lastCheckAt: now, availableVersion: null, availableReason: "Installed before automatic updates existed — update or reinstall it once from the Mods tab and it'll be checked from then on." } }).catch(() => {});
  }

  // ── what would be applied ──────────────────────────────────────────────────
  const selectedRoots = new Set(
    installed.filter((pk) => pk.root && pk.modId).filter((pk) => {
      const m = modeOf.get(pk.key)?.mode ?? "OFF";
      if (o.manualApply) {
        const sm = smByMod.get(pk.modId!);
        return !sm?.pinned && (sm?.autoUpdate ?? serverMode) !== "OFF";
      }
      return m === "AUTO";
    }).map((pk) => pk.modId!),
  );
  const built = buildApplyItems(changes, plan.decisions, installed, universe, factsByMod);
  const items = built.items.filter((it) => selectedRoots.has(it.modId));
  // Mods that keep failing are paused (moved to NOTIFY) by the failure handler below.
  const decisionsJson = plan.decisions.map((d) => ({ key: d.key, name: d.name, root: d.root, action: d.action, from: d.from, to: d.to, reason: d.reason, clientRequired: clientOf.get(d.key) ?? null, mode: modeOf.get(d.key)?.mode ?? null })) as unknown as Prisma.InputJsonValue;

  const available = plan.decisions.filter((d) => d.root && d.action === "update");
  const noCompat = plan.decisions.filter((d) => d.root && d.action === "no-compatible");
  const newlyAvailable = available.filter((d) => d.modId && prevAvailable.get(d.modId) !== d.to);
  const summaryCheck = `${available.length} update${available.length === 1 ? "" : "s"} available${noCompat.length ? `, ${noCompat.length} without a compatible version` : ""}${errors.length ? ` (${errors.length} source lookup${errors.length === 1 ? "" : "s"} failed)` : ""}.`;

  const finishCheck = async (status: string, why: string | null) => {
    await record(server.id, o.trigger, status, why ? `${summaryCheck} ${why}` : summaryCheck, { plan: decisionsJson, error: errors.length ? errors.join("\n").slice(0, 2000) : null });
    await settle(server.id, { lastCheckAt: now, lastStatus: status, lastDetail: (why ?? summaryCheck).slice(0, 1000) });
    // Digest only for something NEW (a version not announced before) — never on every check.
    if (newlyAvailable.length || (noCompat.length && o.trigger === "game-update")) {
      await digest(server, {
        status: "AVAILABLE",
        changes: [],
        available: newlyAvailable.map((d) => ({ name: d.name, from: d.from, to: d.to!, clientRequired: clientOf.get(d.key) ?? null, reason: d.reason })),
        noCompatible: noCompat.map((d) => ({ name: d.name, reason: d.reason })),
      });
    }
    await regenerateProfiles(server, family, target, state, universe, clientOf, pin?.build ?? null).catch((e) => console.error("[mod-autoupdate] profile generation failed", e));
  };

  if (o.checkOnly || !items.length) {
    const why = !items.length && changes.length && !o.checkOnly ? "Nothing set to auto-update." : null;
    if (built.skipped.length) console.log(`[mod-autoupdate] ${server.hostname}: skipped ${built.skipped.map((s) => `${s.name} (${s.reason})`).join("; ")}`);
    await finishCheck("CHECKED", why);
    return;
  }

  // ── gates ──────────────────────────────────────────────────────────────────
  const allowed = await appliesAllowed();
  if (!allowed.ok) { await finishCheck("DEFERRED", allowed.reason); return; }
  const inflight = await db.job.findMany({ where: { type: "GAME_MOD_AUTOUPDATE", status: "RUNNING", id: { not: job.id } }, select: { server: { select: { nodeId: true } } } });
  const env = envConfig();
  const gate = runGate({
    now,
    manual: o.manualApply,
    tz: settings?.timezone || regionTimezone(server.node?.region),
    windowStart: settings?.windowStart ?? 4,
    windowEnd: settings?.windowEnd ?? 8,
    requireEmpty: settings?.requireEmpty ?? true,
    playersOnline: await playersOnline(server.id, family),
    nextEligibleAt: settings?.nextEligibleAt ?? null,
    nodeInflight: inflight.filter((j) => j.server?.nodeId === server.nodeId).length,
    nodeCap: env.nodeCap,
    globalInflight: inflight.length,
    globalCap: env.globalCap,
  });
  if (!gate.go) { await finishCheck("DEFERRED", gate.reason); return; }

  // ── apply ──────────────────────────────────────────────────────────────────
  const mirror = mirrorFor(universe);
  const outcome: ApplyOutcome = await applyUpdateSet(
    {
      fs,
      layout,
      now: () => new Date(),
      progress: (t, pct) => o.step(t, 20 + Math.round(pct * 0.75)),
      apply: (it) => {
        const pinned: FamilyInstaller = { ...installer, resolve: async () => it.resolution };
        const deps: EngineDeps = { fs, fetcher: safeFetch, mirror };
        return installOrUpdate(pinned, it.facts, facts, deps, "update");
      },
      restart: async () => {
        if (env.sandbox) return { ok: true, detail: "sandbox: no real restart" };
        try {
          // The platform's own control path: systemctl via GAME_POWER semantics, unit state + game port checked.
          await gamePower({ ...job, type: "GAME_POWER", attempts: 2, payload: { action: "restart", source: "update", by: null } } as Job);
          return { ok: true, detail: "restarted" };
        } catch (e) {
          return { ok: false, detail: (e as Error).message.slice(0, 300) };
        }
      },
      health: async () => {
        if (env.sandbox) return { ok: true, detail: "sandbox: not probed" };
        const r = await refreshRuntime(server.id, { external: true }).catch(() => null);
        const up = serviceRunning(r?.probe);
        if (up !== true) return { ok: false, detail: `game service is ${r?.probe?.serviceState ?? "unknown"} after the restart` };
        if (r?.probe?.portBound === false) return { ok: false, detail: "the game port isn't bound after the restart" };
        return { ok: true, detail: "service active, game port answering" };
      },
    },
    items,
  );

  const clientChanges = outcome.applied.map((a) => ({ ...a, clientRequired: clientOf.get(a.key) ?? null }));
  const appliedJson = clientChanges as unknown as Prisma.InputJsonValue;
  if (outcome.status === "APPLIED") {
    for (const it of items) {
      const sm = smByMod.get(it.modId);
      if (!sm) continue;
      const rootChange = it.changes.find((c) => c.key === decisionByKey.get(c.key)?.key && decisionByKey.get(c.key)?.root);
      await db.serverMod.update({ where: { id: sm.id }, data: { version: rootChange?.to ?? sm.version, availableVersion: null, availableVersionId: null, lastUpdateAt: new Date(), updateFailures: 0, lastFailure: null } }).catch(() => {});
    }
    await record(server.id, o.trigger, "APPLIED", `${outcome.reason}${env.sandbox ? " (sandbox)" : ""}`, { plan: decisionsJson, applied: appliedJson, snapshotPath: outcome.snapshotPath });
    await settle(server.id, { lastCheckAt: now, lastRunAt: new Date(), lastStatus: "APPLIED", lastDetail: outcome.reason.slice(0, 1000), nextEligibleAt: null });
    await db.auditLog.create({ data: { userId: null, action: "gameserver.mod.autoupdate", detail: `${server.id} ${clientChanges.map((c) => `${c.name} ${c.from ?? "-"}->${c.to}`).join("; ")}`.slice(0, 900) } }).catch(() => {});
    await digest(server, { status: "APPLIED", changes: clientChanges, available: [], noCompatible: noCompat.map((d) => ({ name: d.name, reason: d.reason })) });
    // Re-read the state the engine just wrote so profiles carry the new versions.
    const fresh = await loadState(fs, family);
    await regenerateProfiles(server, family, target, fresh, universe, clientOf, pin?.build ?? null).catch((e) => console.error("[mod-autoupdate] profile generation failed", e));
    return;
  }

  // FAILED / ROLLED_BACK
  const failing = items.map((it) => smByMod.get(it.modId)).filter(Boolean) as NonNullable<ReturnType<typeof smByMod.get>>[];
  let maxFails = 0;
  for (const sm of failing) {
    const fails = sm.updateFailures + 1;
    maxFails = Math.max(maxFails, fails);
    await db.serverMod.update({
      where: { id: sm.id },
      data: {
        updateFailures: fails,
        lastFailure: outcome.reason.slice(0, 2000),
        // Three strikes: stop trying automatically; the owner decides.
        ...(fails >= MAX_CONSECUTIVE_FAILURES ? { autoUpdate: "NOTIFY" } : {}),
      },
    }).catch(() => {});
  }
  const next = backoffAfterFailure(new Date(), maxFails);
  await record(server.id, o.trigger, outcome.status, outcome.reason, { plan: decisionsJson, applied: appliedJson, snapshotPath: outcome.snapshotPath, error: outcome.reason.slice(0, 2000) });
  await settle(server.id, { lastCheckAt: now, lastRunAt: new Date(), lastStatus: outcome.status, lastDetail: outcome.reason.slice(0, 1000), nextEligibleAt: next ?? new Date(Date.now() + 7 * 86400_000) });
  await db.auditLog.create({ data: { userId: null, action: outcome.status === "ROLLED_BACK" ? "gameserver.mod.autoupdate_rolled_back" : "gameserver.mod.autoupdate_failed", detail: `${server.id}: ${outcome.reason}`.slice(0, 900) } }).catch(() => {});
  await digest(server, { status: outcome.status === "ROLLED_BACK" ? "ROLLED_BACK" : "FAILED", changes: [], available: [], noCompatible: [], failureReason: outcome.reason });
  if (outcome.status === "ROLLED_BACK" && outcome.rollbackHealthy === false) {
    await notifyAdmins(`Mod auto-update left ${server.hostname} down`, outcome.reason, `/admin/mod-updates`).catch(() => {});
  }
}

async function digest(server: Loaded, d: Omit<Parameters<typeof buildDigest>[0], "serverName" | "profileUrl" | "sandbox">) {
  const env = envConfig();
  const name = server.label || server.hostname;
  const msg = buildDigest({ ...d, serverName: name, profileUrl: profileUrl(server.id), sandbox: env.sandbox });
  if (!msg) return;
  await db.notification.create({ data: { userId: server.userId, title: msg.title.slice(0, 180), body: msg.body, href: `/dashboard/servers/${server.id}?tab=mods#mod-updates` } }).catch(() => {});
  if (env.sandbox) return; // never email from the sandbox
  const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
  if (user?.email) await sendMail({ to: user.email, subject: msg.subject, html: msg.html, userId: server.userId, kind: "job_done" }).catch(() => {});
}

async function regenerateProfiles(
  server: Loaded,
  family: string,
  target: ReturnType<typeof buildTarget>,
  state: Awaited<ReturnType<typeof loadState>>,
  universe: Universe,
  clientOf: Map<string, boolean | null>,
  pinBuild: string | null,
) {
  const mods: ProfileMod[] = [];
  for (const pk of Object.values(state.packages)) {
    if (pk.disabled) continue;
    const cand = universe[pk.key]?.versions.find((v) => v.versionId === pk.versionId) ?? universe[pk.key]?.versions.find((v) => v.version === pk.version) ?? null;
    const sm = server.mods.find((m) => state.roots[m.modId]?.key === pk.key);
    mods.push({
      key: pk.key,
      name: sm?.mod.name ?? universe[pk.key]?.name ?? pk.name,
      version: pk.version,
      source: pk.key.split(":")[0],
      url: sm?.mod.url ?? (pk.key.startsWith("thunderstore:") ? `https://thunderstore.io/c/valheim/p/${pk.key.slice(13).replace("-", "/")}/` : pk.key.startsWith("modrinth:") ? `https://modrinth.com/project/${pk.key.slice(9)}` : null),
      clientRequired: clientOf.get(pk.key) ?? null,
      file: cand?.file ? { filename: cand.file.filename, url: cand.file.url, sha1: cand.file.hashes.sha1 ?? null, sha512: cand.file.hashes.sha512 ?? null, size: cand.file.size } : null,
    });
  }
  let loaderPack: { name: string; version: string } | null = null;
  if (family === "valheim") {
    const p = await fetchJson<{ latest?: { version_number?: string } }>(safeFetch, "https://thunderstore.io/api/experimental/package/denikson/BepInExPack_Valheim/").catch(() => null);
    const v = p?.latest?.version_number;
    if (v && /^\d+\.\d+\.\d+$/.test(v)) loaderPack = { name: "denikson-BepInExPack_Valheim", version: v };
  }
  await saveProfiles({
    serverId: server.id,
    serverName: server.label || server.hostname,
    family,
    gameLabel: GAME_DISPLAY[family as GameFamily]?.name ?? family,
    variant: target.loader,
    gameVersion: target.gameVersion,
    loaderVersion: target.loader ? loaderVersionFrom(target.loader, pinBuild, (server.gameConfig ?? null) as Record<string, unknown> | null) : null,
    mods,
    loaderPack,
  });
}

export type { Decision };

