test("policy: run gate — players, window, back-off, caps, manual", () => {
  const base = { now: new Date("2026-10-01T05:00:00Z"), manual: false, tz: "UTC", windowStart: 4, windowEnd: 8, requireEmpty: true, playersOnline: 0, nextEligibleAt: null, nodeInflight: 0, nodeCap: 1, globalInflight: 0, globalCap: 3 };
  assert.deepEqual(runGate(base), { go: true });
  const busy = runGate({ ...base, playersOnline: 2 });
  assert.ok(!busy.go && /2 players are online/.test(busy.reason));
  assert.ok(runGate({ ...base, playersOnline: 2, requireEmpty: false }).go);
  assert.ok(runGate({ ...base, playersOnline: null }).go, "untracked game: the window decides");
  const late = runGate({ ...base, now: new Date("2026-10-01T12:00:00Z") });
  assert.ok(!late.go && /Outside the update window/.test(late.reason));
  assert.ok(!runGate({ ...base, nextEligibleAt: new Date("2026-10-02T00:00:00Z") }).go);
  assert.ok(!runGate({ ...base, nodeInflight: 1 }).go);
  assert.ok(!runGate({ ...base, globalInflight: 3 }).go);
  assert.ok(runGate({ ...base, manual: true, playersOnline: 5, now: new Date("2026-10-01T12:00:00Z") }).go);
  assert.ok(!runGate({ ...base, manual: true, nodeInflight: 1 }).go, "caps apply to manual runs too");
  assert.equal(backoffAfterFailure(base.now, 3), null);
  assert.equal(backoffAfterFailure(base.now, 1)!.getTime() - base.now.getTime(), 6 * 3600_000);
});

