// ─── engine: real install engine + LocalGuestFs + fake restart/health ───────

const sha = (b: Buffer) => ({ sha1: createHash("sha1").update(b).digest("hex"), sha512: createHash("sha512").update(b).digest("hex") });
const jar = (cls: string) => makeZip([{ name: "plugin.yml", data: `name: ${cls}\nmain: x.${cls}\n` }, { name: `x/${cls}.class`, data: Buffer.from([0xca, 0xfe, 0xba, 0xbe, cls.length]) }]);
const facts = (variant = "paper"): ServerFacts => ({ id: "srv_t", family: "minecraft", variant, pinnedVersion: "1.21.1", config: { VERSION: "1.21.1" } });
const modFacts: CatalogFacts = { id: "gm_my", gameFamily: "minecraft", slug: "myplugin", name: "My Plugin", source: "modrinth", sourceId: "myplugin", url: null, category: "Plugins", appliesToVariant: null, loaders: ["paper"], gameVersions: ["1.21.1"], serverSide: "required" };

function fakeModrinth(jars: Record<string, Buffer>, versions: { id: string; v: string; file: string; deps?: unknown[]; gv?: string[] }[], opts: { corrupt?: string } = {}) {
  const projects: Record<string, unknown> = {
    P1: { id: "P1", slug: "myplugin", title: "My Plugin", project_type: "plugin", server_side: "required", client_side: "unsupported" },
    myplugin: { id: "P1", slug: "myplugin", title: "My Plugin", project_type: "plugin", server_side: "required", client_side: "unsupported" },
  };
  const mk = (x: (typeof versions)[number], i: number) => ({
    id: x.id, project_id: "P1", version_number: x.v, version_type: "release", loaders: ["paper"], game_versions: x.gv ?? ["1.21.1"], date_published: new Date(Date.UTC(2026, 0, 1 + i)).toISOString(),
    files: [{ url: `https://cdn.modrinth.com/data/P1/versions/${x.id}/${x.file}`, filename: x.file, primary: true, size: jars[x.file].length, hashes: sha(jars[x.file]) }],
    dependencies: x.deps ?? [],
  });
  const all = versions.map(mk);
  const fetcher: Fetcher = async (url, o) => {
    validateUrl(url, o.allow);
    const u = new URL(url);
    let body: Buffer | null = null;
    let m: RegExpExecArray | null;
    if ((m = /^\/v2\/project\/([^/]+)$/.exec(u.pathname))) body = projects[m[1]] ? Buffer.from(JSON.stringify(projects[m[1]])) : null;
    else if ((m = /^\/v2\/project\/([^/]+)\/version$/.exec(u.pathname))) body = Buffer.from(JSON.stringify([...all].reverse()));
    else if ((m = /^\/v2\/version\/([^/]+)$/.exec(u.pathname))) { const x = all.find((a) => a.id === m![1]); body = x ? Buffer.from(JSON.stringify(x)) : null; }
    else if (u.hostname === "cdn.modrinth.com") {
      const f = u.pathname.split("/").pop()!;
      body = jars[f] ?? null;
      if (body && opts.corrupt === f) body = Buffer.concat([body, Buffer.from("x")]);
    }
    if (!body) throw new FetchError("upstream answered HTTP 404", "status");
    const h = hashAll(body);
    checkHashes(h, o.expect);
    return { bytes: body, finalUrl: url, status: 200, ...h };
  };
  return fetcher;
}

function fakeGuest() {
  const root = mkdtempSync(path.join(tmpdir(), "nxeon-autoupd-test-"));
  mkdirSync(path.join(root, "opt/mc/plugins"), { recursive: true });
  mkdirSync(path.join(root, "opt/mc/world/datapacks"), { recursive: true });
  writeFileSync(path.join(root, "opt/mc/server.properties"), "level-name=world\n");
  writeFileSync(path.join(root, "opt/mc/world/level.dat"), "WORLD");
  writeFileSync(path.join(root, "opt/mc/plugins/HandAdded.jar"), "not ours");
  return { root, fs: new LocalGuestFs(root), at: (p: string) => path.join(root, p) };
}

/** Install v1, then build the auto-update pieces for v2 exactly as the worker does. */
async function scenario(opts: { corrupt?: string } = {}) {
  const g = fakeGuest();
  const jars = { "myplugin-1.0.0.jar": jar("MyPlugin"), "myplugin-1.1.0.jar": jar("MyPluginV2") };
  const v1only = fakeModrinth(jars, [{ id: "V100", v: "1.0.0", file: "myplugin-1.0.0.jar" }]);
  const r1 = await installOrUpdate(minecraftInstaller, modFacts, facts(), { fs: g.fs, fetcher: v1only });
  assert.ok(r1.ok, JSON.stringify(r1));
  const fetcher = fakeModrinth(jars, [{ id: "V100", v: "1.0.0", file: "myplugin-1.0.0.jar" }, { id: "V110", v: "1.1.0", file: "myplugin-1.1.0.jar" }], opts);

  const layout = (await minecraftInstaller.detect(g.fs, facts(), null)) as Layout;
  const state = await loadState(g.fs, "minecraft");
  const installed: InstalledPkg[] = Object.values(state.packages).map((p) => ({ key: p.key, name: p.name, version: p.version, versionId: p.versionId, root: true, modId: "gm_my", pinned: false }));
  const target = buildTarget({ family: "minecraft", variant: "paper", pinnedVersion: "1.21.1" });
  const { universe, errors } = await loadUniverse({ family: "minecraft", variant: "paper", gameVersion: "1.21.1", installed, mods: new Map([["gm_my", modFacts]]), fetcher });
  assert.deepEqual(errors, []);
  const plan = resolveUpdates(target, installed, universe);
  const built = buildApplyItems(changesOf(plan), plan.decisions, installed, universe, new Map([["gm_my", modFacts]]));
  return { g, layout, plan, built, fetcher, jars };
}

function io(g: ReturnType<typeof fakeGuest>, layout: Layout, fetcher: Fetcher, healthy: boolean[]) {
  const calls = { restart: 0, health: 0 };
  return {
    calls,
    io: {
      fs: g.fs,
      layout,
      now: () => new Date("2026-10-01T05:00:00Z"),
      apply: (it: Parameters<typeof applyUpdateSet>[1][number]) => {
        const pinned: FamilyInstaller = { ...minecraftInstaller, resolve: async () => it.resolution };
        return installOrUpdate(pinned, it.facts, facts(), { fs: g.fs, fetcher }, "update");
      },
      restart: async () => { calls.restart++; return { ok: true, detail: "restarted" }; },
      health: async () => { const ok = healthy[calls.health++] ?? false; return { ok, detail: ok ? "port answering" : "port never answered" }; },
    },
  };
}

test("engine: loader + resolver + apply → APPLIED; new jar in, old jar out, snapshot zip on the guest, world untouched", async () => {
  const { g, layout, plan, built, fetcher, jars } = await scenario();
  try {
    assert.equal(plan.decisions.find((d) => d.root)!.to, "1.1.0");
    assert.equal(built.items.length, 1);
    const { io: e, calls } = io(g, layout, fetcher, [true]);
    const out = await applyUpdateSet(e, built.items);
    assert.equal(out.status, "APPLIED", out.reason);
