    assert.equal(readFileSync(g.at("opt/mc/plugins/HandAdded.jar"), "utf8"), "not ours");
    const st = await loadState(g.fs, "minecraft");
    assert.equal(Object.values(st.packages)[0].version, "1.1.0");
    const snaps = readdirSync(g.at(SNAPSHOT_DIR.slice(1))).filter((n) => n.endsWith(".zip"));
    assert.equal(snaps.length, 1);
    const names = readZip(readFileSync(g.at(path.join(SNAPSHOT_DIR.slice(1), snaps[0])))).filter((x) => !x.dir).map((x) => x.path.join("/")).sort();
    assert.ok(names.includes("opt/mc/plugins/myplugin-1.0.0.jar") && names.includes("root/.nxeon-mods/state.json"));
    assert.ok(!names.some((n) => n.includes("level.dat") || n.includes("server.properties")), "the world and game root are never in a mod snapshot");
    assert.deepEqual(managedDirs(layout), ["/opt/mc/mods", "/opt/mc/plugins", "/opt/mc/world/datapacks"]);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: unhealthy after restart → ROLLED BACK byte-for-byte, restarted again, reason recorded", async () => {
  const { g, layout, built, fetcher, jars } = await scenario();
  try {
    const before = readFileSync(g.at(STATE_PATH.slice(1)));
    const { io: e, calls } = io(g, layout, fetcher, [false, true]);
    const out = await applyUpdateSet(e, built.items);
    assert.equal(out.status, "ROLLED_BACK");
    assert.equal(out.rollbackHealthy, true);
    assert.equal(calls.restart, 2);
    assert.match(out.reason, /didn't come back \(port never answered\)/);
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.1.0.jar")));
    assert.deepEqual(readFileSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")), jars["myplugin-1.0.0.jar"]);
    assert.deepEqual(readFileSync(g.at(STATE_PATH.slice(1))), before, "state file restored exactly");
    assert.equal(readFileSync(g.at("opt/mc/plugins/HandAdded.jar"), "utf8"), "not ours");
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: rollback that still doesn't come up says so (admin alert path)", async () => {
  const { g, layout, built, fetcher } = await scenario();
  try {
    const { io: e } = io(g, layout, fetcher, [false, false]);
    const out = await applyUpdateSet(e, built.items);
    assert.equal(out.status, "ROLLED_BACK");
    assert.equal(out.rollbackHealthy, false);
    assert.match(out.reason, /still isn't answering/);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: checksum mismatch on download → FAILED, nothing restarted, nothing changed", async () => {
  const { g, layout, built, fetcher } = await scenario({ corrupt: "myplugin-1.1.0.jar" });
  try {
    const { io: e, calls } = io(g, layout, fetcher, [true]);
    const out = await applyUpdateSet(e, built.items);
    assert.equal(out.status, "FAILED");
    assert.equal(calls.restart, 0);
    assert.match(out.reason, /My Plugin/);
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.1.0.jar")));
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: snapshot restore removes files added after it and survives a zip round-trip", async () => {
  const g = fakeGuest();
  try {
    const dirs = ["/opt/mc/plugins"];
    const snap = await takeSnapshot(g.fs, dirs, new Date("2026-10-01T00:00:00Z"));
    writeFileSync(g.at("opt/mc/plugins/Added.jar"), "new");
    writeFileSync(g.at("opt/mc/plugins/HandAdded.jar"), "changed");
    const r = await restoreSnapshot(g.fs, snap);
    assert.ok(r.ok, r.detail);
    assert.ok(!existsSync(g.at("opt/mc/plugins/Added.jar")));
    assert.equal(readFileSync(g.at("opt/mc/plugins/HandAdded.jar"), "utf8"), "not ours");
    const fromZip = snapshotFromZip(readFileSync(g.at(snap.path!.slice(1))), dirs);
    assert.deepEqual([...fromZip.files.keys()], [...snap.files.keys()]);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: nothing to update is a NOOP — no snapshot, no restart", async () => {
  const g = fakeGuest();
  try {
    let restarted = false;
    const out = await applyUpdateSet({ fs: g.fs, layout: { base: "/opt/mc", dirs: { plugins: "/opt/mc/plugins" }, gameVersion: null }, now: () => new Date(), apply: async () => ({ ok: true, restartRequired: true, changed: [], notes: [] }), restart: async () => { restarted = true; return { ok: true, detail: "" }; }, health: async () => ({ ok: true, detail: "" }) }, []);
    assert.equal(out.status, "NOOP");
    assert.equal(restarted, false);
    assert.ok(!existsSync(g.at(SNAPSHOT_DIR.slice(1))));
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

