/**
 * Mod auto-update: version ranges, the compatibility resolver, policy gates,
 * client-requirement classification, the apply engine (snapshot → apply →
 * restart → health → rollback) against a real LocalGuestFs + the real
 * one-click install engine, and the client-profile export formats.
 *
 *   npx tsx --test test/mod-autoupdate.test.ts
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, existsSync, readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";

import { compareVersions, satisfies, isValidRange, gameVersionMatches } from "../lib/mod-autoupdate/version.ts";
import { resolveUpdates, changesOf, compatibility } from "../lib/mod-autoupdate/resolver.ts";
import type { CandidateVersion, InstalledPkg, Target, Universe, DepSpec } from "../lib/mod-autoupdate/types.ts";
import { effectiveMode, inWindow, runGate, backoffAfterFailure, localHour } from "../lib/mod-autoupdate/policy.ts";
import { classifyClient } from "../lib/mod-autoupdate/client-side.ts";
import { buildTarget } from "../lib/mod-autoupdate/target.ts";
import { judgeGameBump } from "../lib/mod-autoupdate/game-hold.ts";
import { buildDigest } from "../lib/mod-autoupdate/digest.ts";
import { writeZip } from "../lib/mod-autoupdate/zip.ts";
import { buildR2modmanProfile, buildMrpack, buildChecklist, profileCodePayload, r2xYaml, loaderVersionFrom, type ProfileMod } from "../lib/mod-autoupdate/profile-export.ts";
import { applyUpdateSet, buildApplyItems, managedDirs, takeSnapshot, restoreSnapshot, snapshotFromZip, SNAPSHOT_DIR } from "../lib/mod-autoupdate/engine.ts";
import { loadUniverse } from "../lib/mod-autoupdate/candidates.ts";
import { readZip } from "../lib/mods/archive.ts";
import { LocalGuestFs } from "../lib/mods/guest-fs.ts";
import { installOrUpdate, loadState, STATE_PATH } from "../lib/mods/engine.ts";
import { minecraftInstaller } from "../lib/mods/installers/minecraft.ts";
import { hashAll, checkHashes, validateUrl, FetchError, type Fetcher } from "../lib/mods/safe-fetch.ts";
import type { CatalogFacts, FamilyInstaller, Layout, ServerFacts } from "../lib/mods/types.ts";
import { makeZip } from "./_mods-zip-fixture.ts";

// ─── version ranges ─────────────────────────────────────────────────────────

test("compareVersions: numeric, prerelease below release, build metadata ignored, loader prefixes", () => {
  assert.equal(compareVersions("1.10.0", "1.9.9"), 1);
  assert.equal(compareVersions("1.2", "1.2.0"), 0);
  assert.equal(compareVersions("1.0.0-beta.2", "1.0.0"), -1);
  assert.equal(compareVersions("1.0.0-beta.10", "1.0.0-beta.2"), 1);
  assert.equal(compareVersions("0.5.8+1.20.1", "0.5.8+1.21"), 0);
  assert.equal(compareVersions("fabric-0.92.2+1.20.1", "fabric-0.92.1+1.20.1"), 1);
  assert.equal(compareVersions("v2.1", "2.0.9"), 1);
});

test("satisfies: comparators, AND, OR, caret, tilde, wildcards, Factorio spacing, fail-closed", () => {
  assert.ok(satisfies("1.2.3", ">=1.2"));
  assert.ok(!satisfies("1.1.9", ">=1.2"));
  assert.ok(satisfies("1.5.0", ">=1.0 <2.0"));
  assert.ok(!satisfies("2.0.0", ">=1.0 <2.0"));
  assert.ok(satisfies("3.1.0", "<2 || >=3"));
  assert.ok(satisfies("1.9.9", "^1.2.0"));
  assert.ok(!satisfies("2.0.0", "^1.2.0"));
  assert.ok(satisfies("0.2.9", "^0.2.3") && !satisfies("0.3.0", "^0.2.3"));
  assert.ok(satisfies("1.2.9", "~1.2.0") && !satisfies("1.3.0", "~1.2.0"));
  assert.ok(satisfies("1.21.4", "1.21.x") && !satisfies("1.22.0", "1.21.x"));
  assert.ok(satisfies("2.0.10", ">= 2.0.7"), "Factorio puts a space after the operator");
  assert.ok(satisfies("1.0.0", "") && satisfies("1.0.0", "*"));
  assert.ok(!satisfies("1.0.0", "garbage!!"), "unparseable range is not satisfied");
  assert.ok(!isValidRange("garbage!!") && isValidRange(">=1 <2"));
  assert.ok(gameVersionMatches("1.21.x", "1.21.4") && gameVersionMatches("1.21.1", "1.21.1") && !gameVersionMatches("1.21", "1.21.1"));
});

// ─── resolver ────────────────────────────────────────────────────────────────

const PAPER: Target = buildTarget({ family: "minecraft", variant: "paper", pinnedVersion: "1.21.1" });
const FABRIC: Target = buildTarget({ family: "minecraft", variant: "fabric", pinnedVersion: "1.20.1" });
const VALHEIM: Target = buildTarget({ family: "valheim", variant: "bepinex" });

let t0 = Date.parse("2026-01-01T00:00:00Z");
function v(key: string, version: string, o: Partial<CandidateVersion> = {}): CandidateVersion {
  t0 += 3600_000;
  return { key, versionId: `${key}@${version}`, version, channel: "release", gameVersions: ["1.21.1"], loaders: ["paper"], publishedAt: t0, deps: [], file: null, placement: "plugin-jar", ...o };
}
const dep = (key: string, range?: string, kind: DepSpec["kind"] = "required"): DepSpec => ({ key, kind, range: range ?? null });
const root = (key: string, version: string, o: Partial<InstalledPkg> = {}): InstalledPkg => ({ key, name: key.split(":")[1], version, versionId: `${key}@${version}`, root: true, modId: `gm_${key.split(":")[1]}`, ...o });
const depPkg = (key: string, version: string): InstalledPkg => ({ key, name: key.split(":")[1], version, versionId: `${key}@${version}`, root: false });
const uni = (...vs: CandidateVersion[]): Universe => {
  const u: Universe = {};
  for (const x of vs) (u[x.key] ??= { key: x.key, name: x.key.split(":")[1], versions: [] }).versions.push(x);
  return u;
};
const dec = (p: ReturnType<typeof resolveUpdates>, key: string) => p.decisions.find((d) => d.key === key)!;

test("resolver: picks the newest build that lists this game version, skips one that doesn't", () => {
  const u = uni(v("m:lp", "1.0"), v("m:lp", "1.1"), v("m:lp", "1.2", { gameVersions: ["1.21.4"] }));
  const p = resolveUpdates(PAPER, [root("m:lp", "1.0")], u);
  const d = dec(p, "m:lp");
  assert.equal(d.action, "update");
  assert.equal(d.to, "1.1");
  assert.match(d.reason, /1\.0 → 1\.1/);
});

test("resolver: never downgrades", () => {
  const u = uni(v("m:a", "1.9"), v("m:a", "2.0", { gameVersions: ["1.21.4"] }));
  const p = resolveUpdates(PAPER, [root("m:a", "2.0")], u);
  assert.notEqual(dec(p, "m:a").action, "update");
  assert.equal(changesOf(p).length, 0);
});

test("resolver: loader mismatch — a Forge-only build is not offered on Fabric", () => {
  const u = uni(
    v("m:sod", "0.5.0", { loaders: ["fabric"], gameVersions: ["1.20.1"] }),
    v("m:sod", "0.6.0", { loaders: ["forge"], gameVersions: ["1.20.1"] }),
  );
  const p = resolveUpdates(FABRIC, [root("m:sod", "0.5.0")], u);
  const d = dec(p, "m:sod");
  assert.equal(d.action, "current");
  assert.match(d.reason, /forge/);
  const verdict = compatibility(u["m:sod"].versions[1], FABRIC);
  assert.equal(verdict.ok, false);
});

test("resolver: 'no compatible version' is explicit after a game version bump", () => {
  const bumped = buildTarget({ family: "minecraft", variant: "fabric", pinnedVersion: "1.21.2" });
  const u = uni(v("m:create", "0.5.1", { loaders: ["fabric"], gameVersions: ["1.20.1"] }), v("m:create", "0.5.2", { loaders: ["fabric"], gameVersions: ["1.20.1"] }));
  const p = resolveUpdates(bumped, [root("m:create", "0.5.2")], u);
  assert.equal(dec(p, "m:create").action, "no-compatible");
  assert.match(dec(p, "m:create").reason, /No compatible version/);
});

test("resolver: mod loaders refuse builds that list no game versions; plugin servers accept them as unknown", () => {
  const u = uni(v("m:x", "1.0", { loaders: ["fabric"], gameVersions: ["1.20.1"] }), v("m:x", "1.1", { loaders: ["fabric"], gameVersions: [] }));
  assert.equal(dec(resolveUpdates(FABRIC, [root("m:x", "1.0")], u), "m:x").action, "current");
  const u2 = uni(v("m:y", "1.0"), v("m:y", "1.1", { gameVersions: [] }));
  assert.equal(dec(resolveUpdates(PAPER, [root("m:y", "1.0")], u2), "m:y").to, "1.1");
});

test("resolver: diamond — two mods share a dependency, it gets the newest version satisfying BOTH ranges", () => {
  const u = uni(
    v("m:a", "1.0"), v("m:a", "2.0", { deps: [dep("m:d", ">=2.0")] }),
    v("m:b", "1.0", { deps: [dep("m:d", "<2.5")] }),
    v("m:d", "1.0"), v("m:d", "2.0"), v("m:d", "2.4"), v("m:d", "3.0"),
  );
  const p = resolveUpdates(PAPER, [root("m:a", "1.0"), root("m:b", "1.0"), depPkg("m:d", "1.0")], u);
  assert.equal(dec(p, "m:a").to, "2.0");
  const d = dec(p, "m:d");
  assert.equal(d.action, "update");
  assert.equal(d.to, "2.4");
  assert.deepEqual([...(d.requiredBy ?? [])].sort(), ["m:a", "m:b"]);
  assert.equal(p.conflicts.length, 0);
});

test("resolver: range conflict → steps the culprit back one build instead of giving up", () => {
  const u = uni(
    v("m:a", "1.0", { deps: [dep("m:d", ">=1")] }),
    v("m:a", "1.5", { deps: [dep("m:d", ">=1")] }),
    v("m:a", "2.0", { deps: [dep("m:d", ">=3")] }),
    v("m:b", "1.0", { deps: [dep("m:d", "<2")] }),
    v("m:d", "1.0"), v("m:d", "1.9"), v("m:d", "3.0"),
  );
  const p = resolveUpdates(PAPER, [root("m:a", "1.0"), root("m:b", "1.0"), depPkg("m:d", "1.0")], u);
  const a = dec(p, "m:a");
  assert.equal(a.action, "update");
  assert.equal(a.to, "1.5");
  assert.match(a.reason, /newer build was skipped/);
  assert.equal(dec(p, "m:d").to, "1.9");
  assert.equal(p.conflicts.length, 0);
});

test("resolver: unsatisfiable → held with the conflict as the reason, nothing changes", () => {
  const u = uni(
    v("m:a", "1.0"),
    v("m:a", "2.0", { deps: [dep("m:d", ">=3")] }),
    v("m:b", "1.0", { deps: [dep("m:d", "<2")] }),
    v("m:d", "1.0"), v("m:d", "3.0"),
  );
  const p = resolveUpdates(PAPER, [root("m:a", "1.0"), root("m:b", "1.0"), depPkg("m:d", "1.0")], u);
  assert.equal(dec(p, "m:a").action, "held");
  assert.match(dec(p, "m:a").reason, /Staying on 1\.0/);
  assert.equal(changesOf(p).filter((c) => c.root).length, 0);
});

test("resolver: declared incompatibility with an installed mod blocks that build", () => {
  const u = uni(
    v("m:a", "1.0"), v("m:a", "1.1"),
    v("m:a", "2.0", { deps: [dep("m:c", null as unknown as string, "incompatible")] }),
    v("m:c", "1.0"),
  );
  const p = resolveUpdates(PAPER, [root("m:a", "1.0"), root("m:c", "1.0")], u);
  assert.equal(dec(p, "m:a").to, "1.1");
  assert.match(dec(p, "m:a").reason, /incompatible/);
});

test("resolver: transitive new dependencies are added (A → B → C)", () => {
  const u = uni(
    v("m:a", "1.0"), v("m:a", "2.0", { deps: [dep("m:b")] }),
    v("m:b", "1.0", { deps: [dep("m:c", ">=0.5")] }),
    v("m:c", "0.4"), v("m:c", "0.6"),
  );
  const p = resolveUpdates(PAPER, [root("m:a", "1.0")], u);
  assert.equal(dec(p, "m:a").to, "2.0");
  assert.equal(dec(p, "m:b").action, "add-dependency");
  assert.equal(dec(p, "m:c").action, "add-dependency");
  assert.equal(dec(p, "m:c").to, "0.6");
});

test("resolver: a dependency that would need a downgrade holds the root", () => {
  const u = uni(v("m:a", "1.0"), v("m:a", "2.0", { deps: [dep("m:d", "<=2")] }), v("m:d", "1.0"), v("m:d", "3.0"));
  const p = resolveUpdates(PAPER, [root("m:a", "1.0"), depPkg("m:d", "3.0")], u);
  assert.equal(dec(p, "m:a").action, "held");
  assert.match(dec(p, "m:a").reason, /downgrading/);
});

test("resolver: a dependency nobody can find holds the root", () => {
  const u = uni(v("m:a", "1.0"), v("m:a", "2.0", { deps: [dep("m:ghost", ">=1")] }));
  const p = resolveUpdates(PAPER, [root("m:a", "1.0")], u);
  assert.equal(dec(p, "m:a").action, "held");
  assert.match(dec(p, "m:a").reason, /no build of it could be found/);
});

test("resolver: pinned, prerelease, modpack and missing-metadata cases", () => {
  const u = uni(v("m:p", "1.0"), v("m:p", "2.0"), v("m:q", "1.0"), v("m:q", "1.1-beta.1", { channel: "beta" }), v("m:pack", "1"), v("m:pack", "2"));
  u["m:pack"].isModpack = true;
  const p = resolveUpdates(PAPER, [root("m:p", "1.0", { pinned: true }), root("m:q", "1.0"), root("m:pack", "1"), root("m:none", "1.0")], u);
  assert.equal(dec(p, "m:p").action, "pinned");
  assert.equal(dec(p, "m:q").action, "current", "betas aren't offered to a release install");
  assert.equal(dec(p, "m:pack").action, "held");
  assert.equal(dec(p, "m:none").action, "unknown");
  // Already on a beta → newer betas are fine.
  const u2 = uni(v("m:q", "1.1-beta.1", { channel: "beta" }), v("m:q", "1.1-beta.2", { channel: "beta" }));
  assert.equal(dec(resolveUpdates(PAPER, [root("m:q", "1.1-beta.1")], u2), "m:q").to, "1.1-beta.2");
});

test("resolver: Valheim/Thunderstore — no game-version data, dependency minimums, shared library", () => {
  const ts = (k: string, ver: string, deps: DepSpec[] = []) => v(k, ver, { gameVersions: [], loaders: [], deps, placement: "bepinex" });
  const u = uni(
    ts("thunderstore:A-Epic", "0.9.0"), ts("thunderstore:A-Epic", "0.10.0", [dep("thunderstore:V-Jotunn", ">=2.20.0")]),
    ts("thunderstore:B-Plant", "1.0.0", [dep("thunderstore:V-Jotunn", ">=2.12.0")]),
    ts("thunderstore:V-Jotunn", "2.12.0"), ts("thunderstore:V-Jotunn", "2.21.1"),
  );
  const p = resolveUpdates(VALHEIM, [root("thunderstore:A-Epic", "0.9.0"), root("thunderstore:B-Plant", "1.0.0"), depPkg("thunderstore:V-Jotunn", "2.12.0")], u);
  assert.equal(dec(p, "thunderstore:A-Epic").to, "0.10.0");
  assert.equal(dec(p, "thunderstore:V-Jotunn").to, "2.21.1");
  assert.match(dec(p, "thunderstore:A-Epic").reason, /no compatibility data/);
});

test("resolver: bounded and deterministic on a wide universe", () => {
  const vs: CandidateVersion[] = [];
  const roots: InstalledPkg[] = [];
  for (let i = 0; i < 25; i++) {
    for (let j = 0; j < 8; j++) vs.push(v(`m:r${i}`, `1.${j}`, { deps: [dep("m:core", `>=1.${j % 4}`)] }));
    roots.push(root(`m:r${i}`, "1.0"));
  }
  for (let j = 0; j < 6; j++) vs.push(v("m:core", `1.${j}`));
  const a = resolveUpdates(PAPER, [...roots, depPkg("m:core", "1.0")], uni(...vs));
  const b = resolveUpdates(PAPER, [...roots, depPkg("m:core", "1.0")], uni(...vs));
  assert.deepEqual(a.decisions.map((d) => [d.key, d.to]), b.decisions.map((d) => [d.key, d.to]));
  assert.ok(a.decisions.filter((d) => d.root).every((d) => d.to === "1.7"));
  assert.equal(dec(a, "m:core").to, "1.5");
});

// ─── policy ──────────────────────────────────────────────────────────────────

test("policy: clientRequired mods default to NOTIFY under AUTO unless the owner opted in", () => {
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: null, pinned: false, clientRequired: true, clientModsAuto: false }).mode, "NOTIFY");
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: null, pinned: false, clientRequired: true, clientModsAuto: true }).mode, "AUTO");
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: null, pinned: false, clientRequired: null, clientModsAuto: false }).mode, "NOTIFY");
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: null, pinned: false, clientRequired: false, clientModsAuto: false }).mode, "AUTO");
  assert.equal(effectiveMode({ serverMode: "NOTIFY", modOverride: "AUTO", pinned: false, clientRequired: false, clientModsAuto: false }).mode, "AUTO");
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: "OFF", pinned: false, clientRequired: false, clientModsAuto: false }).mode, "OFF");
  assert.equal(effectiveMode({ serverMode: "AUTO", modOverride: "AUTO", pinned: true, clientRequired: false, clientModsAuto: true }).mode, "OFF");
});

test("policy: window in local time, wrap past midnight, start==end = any time", () => {
  const at = new Date("2026-10-01T20:30:00Z"); // 04:30 in Singapore
  assert.equal(localHour(at, "Asia/Singapore"), 4);
  assert.ok(inWindow(at, "Asia/Singapore", 4, 8));
  assert.ok(!inWindow(at, "UTC", 4, 8));
  assert.ok(inWindow(at, "UTC", 22, 4) === false && inWindow(new Date("2026-10-01T23:00:00Z"), "UTC", 22, 4));
  assert.ok(inWindow(at, "UTC", 0, 0));
});

test("policy: run gate — players, window, back-off, caps, manual", () => {
  const base = { now: new Date("2026-10-01T05:00:00Z"), manual: false, tz: "UTC", windowStart: 4, windowEnd: 8, requireEmpty: true, playersOnline: 0, nextEligibleAt: null, nodeInflight: 0, nodeCap: 1, globalInflight: 0, globalCap: 3 };
