"use server";

/**
 * Server actions for mod auto-update — the customer "Updates" panel
 * (components/customer/mods/AutoUpdatePanel.tsx) and the admin fleet view
 * (/admin/mod-updates).
 *
 * Nothing here touches a server: settings are rows, "Check now" / "Update now"
 * queue ONE GAME_MOD_AUTOUPDATE job under the per-server job lock, and the
 * worker (worker/mod-autoupdate.ts) does the work. Ownership is checked on
 * every call; every change writes an AuditLog row.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { familyFor } from "./game-config";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { ENGINE_INSTALLERS } from "./mods/installers";
import { withServerJobLock } from "./job-guard";
import { safeFetch } from "./mods/safe-fetch";
import { logTrackingSpec, controlSpec } from "./game-control";
import { isMode, type Mode } from "./mod-autoupdate/types";
import { effectiveMode, isValidTimezone, regionTimezone } from "./mod-autoupdate/policy";
import { adminKillSwitchOn, envConfig, SETTING_KEY } from "./mod-autoupdate/config";
import { createShareCode } from "./mod-autoupdate/profile-store";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, node: { select: { region: true } }, modAutoUpdate: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server, family: familyFor(server) };
}

const hits = new Map<string, number[]>();
function throttled(key: string, max: number, windowMs = 60_000): boolean {
  const now = Date.now();
  const arr = (hits.get(key) ?? []).filter((t) => now - t < windowMs);
  if (arr.length >= max) return true;
  arr.push(now);
  hits.set(key, arr);
  return false;
}

async function audit(userId: string, action: string, detail: string) {
  await db.auditLog.create({ data: { userId, action, detail: detail.slice(0, 900) } }).catch(() => {});
}

export type ModUpdateRow = {
  id: string;
  modId: string;
  name: string;
  version: string | null;
  status: string;
  available: string | null;
  reason: string | null;
  clientRequired: boolean | null;
  clientReason: string | null;
  override: Mode | null;
  pinned: boolean;
  effective: Mode;
  effectiveReason: string;
  lastCheckAt: string | null;
  lastUpdateAt: string | null;
  failures: number;
  lastFailure: string | null;
};

export type ModUpdatesView = {
  supported: boolean;
  unsupportedReason: string | null;
  familyName: string;
  settings: {
    mode: Mode;
    clientModsAuto: boolean;
    clientModsAckAt: string | null;
    windowStart: number;
    windowEnd: number;
    timezone: string | null;
    defaultTimezone: string;
    requireEmpty: boolean;
    holdGameUpdates: boolean;
    lastCheckAt: string | null;
    lastStatus: string | null;
    lastDetail: string | null;
    nextEligibleAt: string | null;
  };
  mods: ModUpdateRow[];
  runs: { id: string; trigger: string; status: string; summary: string; startedAt: string; applied: { name: string; from: string | null; to: string; clientRequired: boolean | null }[] }[];
  profiles: { kind: string; fileName: string; generatedAt: string; notes: string | null; shareCode: string | null; bytes: number }[];
  job: { status: string; step: string | null; progress: number; mine: boolean } | null;
  platform: { sweepOn: boolean; paused: boolean; engineOn: boolean };
  playerTracking: boolean;
  isMinecraftLoader: boolean;
  gameUpdatesItself: boolean;
};

export async function getModUpdatesView(serverId: string): Promise<{ error?: string; view?: ModUpdatesView }> {
  const { server, family } = await ownedServer(serverId);
  const fam = family ?? "";
  const supported = !!ENGINE_INSTALLERS[fam];
  const s = server.modAutoUpdate;
  const mode: Mode = isMode(s?.mode) ? (s!.mode as Mode) : "NOTIFY";
  const [rows, runs, profiles, job] = await Promise.all([
    db.serverMod.findMany({ where: { serverId, status: { in: ["INSTALLED", "DISABLED", "UPDATING"] } }, include: { mod: { select: { name: true } } }, orderBy: { installedAt: "asc" } }),
    db.modUpdateRun.findMany({ where: { serverId }, orderBy: { startedAt: "desc" }, take: 15 }),
    db.modClientProfile.findMany({ where: { serverId }, select: { kind: true, fileName: true, generatedAt: true, notes: true, shareCode: true, sha256: true, data: true } }),
    db.job.findFirst({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } }, orderBy: { createdAt: "desc" }, select: { type: true, status: true, step: true, progress: true } }),
  ]);
  const env = envConfig();
  const view: ModUpdatesView = {
    supported,
    unsupportedReason: supported ? null : "Automatic mod updates aren't available for this game — its mods are updated by the game itself, or there is no one-click mod support yet.",
    familyName: GAME_DISPLAY[fam as GameFamily]?.name ?? fam,
    settings: {
      mode,
      clientModsAuto: s?.clientModsAuto ?? false,
      clientModsAckAt: s?.clientModsAckAt?.toISOString() ?? null,
      windowStart: s?.windowStart ?? 4,
      windowEnd: s?.windowEnd ?? 8,
      timezone: s?.timezone ?? null,
      defaultTimezone: regionTimezone(server.node?.region),
      requireEmpty: s?.requireEmpty ?? true,
      holdGameUpdates: s?.holdGameUpdates ?? true,
      lastCheckAt: s?.lastCheckAt?.toISOString() ?? null,
      lastStatus: s?.lastStatus ?? null,
      lastDetail: s?.lastDetail ?? null,
      nextEligibleAt: s?.nextEligibleAt?.toISOString() ?? null,
    },
    mods: rows.map((r) => {
      const override = isMode(r.autoUpdate) ? (r.autoUpdate as Mode) : null;
      const em = effectiveMode({ serverMode: mode, modOverride: override, pinned: r.pinned, clientRequired: r.clientRequired, clientModsAuto: s?.clientModsAuto ?? false });
      return {
        id: r.id,
        modId: r.modId,
        name: r.mod.name,
        version: r.version,
        status: r.status,
        available: r.availableVersion,
        reason: r.availableReason,
        clientRequired: r.clientRequired,
        clientReason: r.clientReason,
        override,
        pinned: r.pinned,
        effective: em.mode,
        effectiveReason: em.reason,
        lastCheckAt: r.lastCheckAt?.toISOString() ?? null,
        lastUpdateAt: r.lastUpdateAt?.toISOString() ?? null,
        failures: r.updateFailures,
        lastFailure: r.lastFailure,
      };
    }),
    runs: runs.map((r) => ({ id: r.id, trigger: r.trigger, status: r.status, summary: r.summary, startedAt: r.startedAt.toISOString(), applied: Array.isArray(r.applied) ? (r.applied as ModUpdatesView["runs"][number]["applied"]) : [] })),
    profiles: profiles.map((p) => ({ kind: p.kind, fileName: p.fileName, generatedAt: p.generatedAt.toISOString(), notes: p.notes, shareCode: p.shareCode, bytes: p.data.length })),
    job: job ? { status: job.status, step: job.type === "GAME_MOD_AUTOUPDATE" ? job.step : "Another operation is running on this server", progress: job.progress, mine: job.type === "GAME_MOD_AUTOUPDATE" } : null,
    platform: { sweepOn: env.sweepEnabled && !env.envKilled, paused: env.envKilled || (await adminKillSwitchOn()), engineOn: env.realGuests },
    playerTracking: !!logTrackingSpec(fam) || controlSpec(fam as GameFamily)?.rcon === "source",
    isMinecraftLoader: fam === "minecraft" && ["fabric", "quilt", "forge", "neoforge"].includes((server.gameVariant ?? "").toLowerCase()),
    gameUpdatesItself: fam === "valheim",
  };
  return { view };
}

export type SettingsInput = { mode: string; windowStart: number; windowEnd: number; timezone: string | null; requireEmpty: boolean; holdGameUpdates: boolean };

export async function saveModUpdateSettings(serverId: string, input: SettingsInput): Promise<{ error?: string; ok?: true }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family || !ENGINE_INSTALLERS[family]) return { error: "Automatic mod updates aren't available for this game." };
  if (!isMode(input?.mode)) return { error: "Pick Off, Notify or Auto." };
  const ws = Number(input.windowStart);
  const we = Number(input.windowEnd);
  if (!Number.isInteger(ws) || !Number.isInteger(we) || ws < 0 || ws > 23 || we < 0 || we > 23) return { error: "The window hours must be 0–23." };
  const tz = input.timezone ? String(input.timezone).slice(0, 64) : null;
  if (tz && !isValidTimezone(tz)) return { error: "That timezone isn't recognised." };
  const data = { mode: input.mode, windowStart: ws, windowEnd: we, timezone: tz, requireEmpty: !!input.requireEmpty, holdGameUpdates: !!input.holdGameUpdates };
  await db.modAutoUpdateSettings.upsert({ where: { serverId }, create: { serverId, ...data }, update: data });
  await audit(user.id, "gameserver.mod.autoupdate.settings", `${server.id} ${JSON.stringify(data)}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/** mode: OFF | NOTIFY | AUTO | "INHERIT" | "PIN" | "UNPIN" */
export async function setModUpdateMode(serverId: string, serverModId: string, mode: string): Promise<{ error?: string; ok?: true }> {
  const { user } = await ownedServer(serverId);
  const sm = await db.serverMod.findFirst({ where: { id: String(serverModId), serverId }, include: { mod: { select: { slug: true } } } });
  if (!sm) return { error: "That mod isn't on this server." };
  let data: { autoUpdate?: string | null; pinned?: boolean; updateFailures?: number };
  if (mode === "INHERIT") data = { autoUpdate: null };
  else if (mode === "PIN") data = { pinned: true };
  else if (mode === "UNPIN") data = { pinned: false, updateFailures: 0 };
  else if (isMode(mode)) data = { autoUpdate: mode, ...(mode === "AUTO" ? { updateFailures: 0 } : {}) };
  else return { error: "Unknown setting." };
  await db.serverMod.update({ where: { id: sm.id }, data });
  await audit(user.id, "gameserver.mod.autoupdate.mod", `${serverId} ${sm.mod.slug} ${mode}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

export const CLIENT_OPT_IN_PHRASE = "players-must-update";

/** Opting in to auto-updating mods players need — requires the explicit confirmation phrase. */
export async function setClientModsAuto(serverId: string, enabled: boolean, confirm: string): Promise<{ error?: string; ok?: true }> {
  const { user } = await ownedServer(serverId);
  if (enabled && confirm !== CLIENT_OPT_IN_PHRASE) return { error: "Confirm that you understand players will be locked out until they update." };
  const data = enabled ? { clientModsAuto: true, clientModsAckAt: new Date(), clientModsAckBy: user.id } : { clientModsAuto: false };
  await db.modAutoUpdateSettings.upsert({ where: { serverId }, create: { serverId, ...data }, update: data });
  await audit(user.id, "gameserver.mod.autoupdate.client_opt_in", `${serverId} ${enabled ? "on" : "off"}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

async function enqueue(serverId: string, userId: string, payload: Record<string, unknown>): Promise<{ error?: string; ok?: true }> {
  const r = await withServerJobLock(serverId, async (tx) => {
    const busy = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (busy) return { ok: false as const };
    await tx.job.create({ data: { type: "GAME_MOD_AUTOUPDATE", serverId, payload: { ...payload, by: userId } as object } });
    return { ok: true as const };
  });
  if (!r.ok) return { error: "Another operation is already running on this server — try again when it finishes." };
  return { ok: true };
}

export async function runModUpdateCheck(serverId: string): Promise<{ error?: string; ok?: true }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family || !ENGINE_INSTALLERS[family]) return { error: "Automatic mod updates aren't available for this game." };
  if (server.status !== "RUNNING") return { error: "Start the server first — checking reads its mod folders." };
  if (throttled(`${user.id}:modcheck`, 3)) return { error: "Checked very recently — try again in a minute." };
  const r = await enqueue(serverId, user.id, { trigger: "manual", checkOnly: true });
  if (r.ok) await audit(user.id, "gameserver.mod.autoupdate.check", serverId);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return r;
}

/** Apply every available update now (not OFF/pinned), restart, health-check, roll back on failure. */
export async function applyModUpdatesNow(serverId: string): Promise<{ error?: string; ok?: true }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family || !ENGINE_INSTALLERS[family]) return { error: "Automatic mod updates aren't available for this game." };
  if (server.status !== "RUNNING") return { error: "Start the server first." };
  if (throttled(`${user.id}:modapply`, 2)) return { error: "Please wait a minute before trying again." };
  const r = await enqueue(serverId, user.id, { trigger: "manual", apply: true });
  if (r.ok) await audit(user.id, "gameserver.mod.autoupdate.apply_now", serverId);
  revalidatePath(`/dashboard/servers/${serverId}`);
  return r;
}

export async function createPlayerShareCode(serverId: string): Promise<{ error?: string; code?: string }> {
  const { user } = await ownedServer(serverId);
  if (throttled(`${user.id}:sharecode`, 3)) return { error: "Please wait a minute before trying again." };
  const r = await createShareCode(serverId, safeFetch);
  if ("code" in r) {
    await audit(user.id, "gameserver.mod.profile.share_code", serverId);
    return { code: r.code };
  }
  return { error: r.error };
}

// ── admin ───────────────────────────────────────────────────────────────────

export async function setModAutoUpdatePaused(paused: boolean): Promise<{ ok: true }> {
  const admin = await requireArea("fleet");
  await db.setting.upsert({ where: { key: SETTING_KEY }, update: { value: paused ? "false" : "true" }, create: { key: SETTING_KEY, value: paused ? "false" : "true" } });
  await audit(admin.id, paused ? "admin.mod_autoupdate.paused" : "admin.mod_autoupdate.resumed", `fleet-wide ${paused ? "paused" : "resumed"}`);
  revalidatePath("/admin/mod-updates");
  return { ok: true };
}

/** Admin: clear a server's back-off (after investigating a failure). */
export async function adminClearModUpdateBackoff(serverId: string): Promise<{ ok: true }> {
  const admin = await requireArea("fleet");
  await db.modAutoUpdateSettings.updateMany({ where: { serverId: String(serverId) }, data: { nextEligibleAt: null } });
  await audit(admin.id, "admin.mod_autoupdate.clear_backoff", String(serverId));
  revalidatePath("/admin/mod-updates");
  return { ok: true };
}

