import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

const KINDS = new Set(["r2z", "mrpack", "checklist"]);

/**
 * Download a generated "give this to your players" profile (ModClientProfile,
 * written by worker/mod-autoupdate.ts). Owner (or admin) only. The file holds
 * nothing secret — mod names, versions and public download links — but it is
 * still one customer's server, so it is not served to anyone else.
 */
export async function GET(_req: Request, ctx: { params: Promise<{ id: string; kind: string }> }) {
  const { id, kind } = await ctx.params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  if (!KINDS.has(kind) || id.length > 64) return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
  const server = await db.server.findUnique({ where: { id }, select: { userId: true } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
  const row = await db.modClientProfile.findUnique({ where: { serverId_kind: { serverId: id, kind } } });
  if (!row) return NextResponse.json({ error: "not generated yet" }, { status: 404, headers: NO_STORE_HEADERS });
  const name = row.fileName.replace(/[^A-Za-z0-9._-]/g, "_");
  return new NextResponse(Buffer.from(row.data), {
    status: 200,
    headers: {
      ...NO_STORE_HEADERS,
      "Content-Type": row.contentType,
      "Content-Disposition": `attachment; filename="${name}"`,
      "X-Content-Type-Options": "nosniff",
    },
  });
}

