"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  applyModUpdatesNow,
  getModUpdatesView,
  runModUpdateCheck,
  saveModUpdateSettings,
  setClientModsAuto,
  setModUpdateMode,
  type ModUpdatesView,
  type ModUpdateRow,
} from "@/lib/actions-mod-autoupdate";
import { AutoUpdateProfiles } from "./AutoUpdateProfiles";
import { AutoUpdateHistory } from "./AutoUpdateHistory";

/**
 * "Updates" — automatic mod updates for one game server (Mods & Plugins tab).
 *
 * Every fact on this panel comes from the worker's last real check
 * (worker/mod-autoupdate.ts → ServerMod availability columns, ModUpdateRun
 * history, ModClientProfile files). Nothing here is estimated: a mod we
 * couldn't check says so, and the "players need it" badge shows its source.
 */

const MODE_LABEL: Record<string, string> = { OFF: "Off", NOTIFY: "Notify me", AUTO: "Auto-update" };
const btn = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50";
const card = "rounded-[14px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-4";

function Chip({ cls, children, title }: { cls: string; children: React.ReactNode; title?: string }) {
  return <span title={title} className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>{children}</span>;
}

export function ago(iso: string | null): string {
  if (!iso) return "never";
  const s = Math.round((Date.now() - Date.parse(iso)) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
}

function ClientBadge({ m }: { m: ModUpdateRow }) {
  if (m.clientRequired === true) return <Chip cls="border-amber-500/45 bg-amber-500/12 text-amber-300" title={m.clientReason ?? undefined}>Players need it</Chip>;
  if (m.clientRequired === false) return <Chip cls="border-emerald-500/40 bg-emerald-500/10 text-emerald-300" title={m.clientReason ?? undefined}>Server only</Chip>;
  return <Chip cls="border-rim-hi bg-well text-tx-faint" title={m.clientReason ?? undefined}>Players: unknown</Chip>;
}

export function AutoUpdatePanel({ serverId }: { serverId: string }) {
  const [view, setView] = useState<ModUpdatesView | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [confirmApply, setConfirmApply] = useState(false);
  const [optIn, setOptIn] = useState(false);

  const load = useCallback(async () => {
    try {
      const r = await getModUpdatesView(serverId);
      if (r.error) setError(r.error);
      else if (r.view) setView(r.view);
    } catch {
      setError("Couldn't load mod updates.");
    }
  }, [serverId]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    if (!view?.job) return;
    const t = setInterval(() => void load(), 4000);
    return () => clearInterval(t);
  }, [view?.job, load]);

  const run = (fn: () => Promise<{ error?: string; ok?: true }>, okMsg: string) =>
    start(async () => {
      setError(null);
      setNotice(null);
      const r = await fn().catch(() => ({ error: "That didn't work — try again." }));
      if (r.error) setError(r.error);
      else setNotice(okMsg);
      await load();
    });

  if (!view) {
    return <div id="mod-updates" className={card}><p className="text-[12.5px] text-tx-faint">{error ?? "Loading mod updates…"}</p></div>;
  }
  if (!view.supported) {
    return (
      <div id="mod-updates" className={card}>
        <h3 className="text-[14px] font-bold text-white">Automatic mod updates</h3>
        <p className="mt-1 text-[12.5px] text-tx-dim">{view.unsupportedReason}</p>
      </div>
    );
  }

  const s = view.settings;
  const available = view.mods.filter((m) => m.available && m.effective !== "OFF");
  const playersAffected = available.filter((m) => m.clientRequired !== false);
  const tz = s.timezone ?? s.defaultTimezone;
  const busy = pending || !!view.job;

  const save = (patch: Partial<typeof s>) => {
    const next = { ...s, ...patch };
    run(() => saveModUpdateSettings(serverId, { mode: next.mode, windowStart: next.windowStart, windowEnd: next.windowEnd, timezone: next.timezone, requireEmpty: next.requireEmpty, holdGameUpdates: next.holdGameUpdates }), "Saved.");
  };

  return (
    <div id="mod-updates" className="flex flex-col gap-3">
      <div className={card}>
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div className="min-w-0">
            <h3 className="text-[14px] font-bold text-white">Automatic mod updates</h3>
            <p className="mt-0.5 text-[12px] text-tx-faint">
              Last checked {ago(s.lastCheckAt)}
              {s.lastStatus ? ` · ${s.lastStatus.toLowerCase().replace("_", " ")}` : ""}
              {available.length ? ` · ${available.length} update${available.length === 1 ? "" : "s"} available` : s.lastCheckAt ? " · everything is current" : ""}
            </p>
            {s.lastDetail && <p className="mt-1 text-[11.5px] leading-snug text-tx-dim">{s.lastDetail}</p>}
          </div>
          <div className="flex flex-none flex-wrap gap-2">
            <button type="button" className={btn} disabled={busy} onClick={() => run(() => runModUpdateCheck(serverId), "Checking — this takes a minute.")}>Check now</button>
            <button type="button" className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50" disabled={busy || !available.length || view.platform.paused || !view.platform.engineOn} onClick={() => setConfirmApply(true)}>
              Update now{available.length ? ` (${available.length})` : ""}
            </button>
          </div>
        </div>
        {view.job && (
          <div className="mt-3 rounded-[10px] border border-cyan-400/30 bg-cyan-400/[0.06] px-3 py-2 text-[12px] text-cyan-200">
            {view.job.step ?? (view.job.status === "QUEUED" ? "Queued…" : "Working…")}{view.job.mine && view.job.progress ? ` · ${view.job.progress}%` : ""}
          </div>
        )}
        {view.platform.paused && <p className="mt-3 rounded-[10px] border border-amber-500/30 bg-amber-500/[0.07] px-3 py-2 text-[12px] text-amber-300">Automatic mod updates are paused platform-wide right now. Checks still work; nothing will be changed until they resume.</p>}
        {!view.platform.engineOn && <p className="mt-3 rounded-[10px] border border-amber-500/30 bg-amber-500/[0.07] px-3 py-2 text-[12px] text-amber-300">One-click mod changes aren't enabled for this game yet, so updates can't be applied.</p>}
        {error && <p className="mt-3 text-[12px] text-red-300">{error}</p>}
        {notice && !error && <p className="mt-3 text-[12px] text-emerald-300">{notice}</p>}
      </div>

      <div className={card}>
        <h4 className="text-[13px] font-bold text-white">Settings</h4>
        <div className="mt-3 flex flex-wrap gap-1.5" role="radiogroup" aria-label="Default for every mod">
          {(["OFF", "NOTIFY", "AUTO"] as const).map((m) => (
            <button key={m} type="button" role="radio" aria-checked={s.mode === m} disabled={busy}
              onClick={() => save({ mode: m })}
              className={"rounded-[10px] border px-3 py-1.5 text-[12px] font-semibold transition disabled:opacity-50 " + (s.mode === m ? "border-[#7b3fef]/70 bg-[linear-gradient(90deg,rgba(59,107,232,.25),rgba(123,63,239,.25))] text-white" : "border-rim-hi bg-well text-tx-dim hover:text-white")}>
              {MODE_LABEL[m]}
            </button>
          ))}
        </div>
        <p className="mt-2 text-[11.5px] leading-relaxed text-tx-faint">
          {s.mode === "AUTO" ? "New compatible versions are installed for you: the mod folders are snapshotted first, the server restarts, and if it doesn't come back the previous mods are put back automatically." : s.mode === "NOTIFY" ? "We check regularly and tell you when compatible updates exist. Nothing changes until you press Update now." : "No checks and no changes."}
        </p>

        <div className="mt-4 grid gap-3 sm:grid-cols-2">
          <label className="flex flex-col gap-1 text-[12px] text-tx-dim">
            Update window ({tz})
            <span className="flex items-center gap-2">
              <select value={s.windowStart} disabled={busy} onChange={(e) => save({ windowStart: Number(e.target.value) })} className="input h-9 flex-1 text-[12.5px]">
                {Array.from({ length: 24 }, (_, h) => <option key={h} value={h}>{String(h).padStart(2, "0")}:00</option>)}
              </select>
              <span className="text-tx-faint">to</span>
              <select value={s.windowEnd} disabled={busy} onChange={(e) => save({ windowEnd: Number(e.target.value) })} className="input h-9 flex-1 text-[12.5px]">
                {Array.from({ length: 24 }, (_, h) => <option key={h} value={h}>{String(h).padStart(2, "0")}:00</option>)}
              </select>
            </span>
            <span className="text-[11px] text-tx-faint">{s.windowStart === s.windowEnd ? "Same start and end = any time of day." : "Automatic updates only start inside this window."}</span>
          </label>
          <div className="flex flex-col gap-2 text-[12px] text-tx-dim">
            <label className="flex cursor-pointer items-start gap-2">
              <input type="checkbox" className="mt-0.5 accent-[#7b3fef]" checked={s.requireEmpty} disabled={busy} onChange={(e) => save({ requireEmpty: e.target.checked })} />
              <span>Wait until nobody is online{!view.playerTracking && <span className="block text-[11px] text-tx-faint">We can't see who's online for this game, so the window alone decides.</span>}</span>
            </label>
            {view.isMinecraftLoader && (
              <label className="flex cursor-pointer items-start gap-2">
                <input type="checkbox" className="mt-0.5 accent-[#7b3fef]" checked={s.holdGameUpdates} disabled={busy} onChange={(e) => save({ holdGameUpdates: e.target.checked })} />
                <span>Hold Minecraft version updates until every mod has a build for the new version</span>
              </label>
            )}
            {view.gameUpdatesItself && (
              <p className="text-[11px] leading-snug text-tx-faint">Valheim updates itself when it restarts — that can't be held. If a Valheim update breaks a mod, the health check after the next mod update rolls the mods back; check the mod's page for a fixed version.</p>
            )}
          </div>
        </div>

        <div className="mt-4 rounded-[12px] border border-amber-500/30 bg-amber-500/[0.06] p-3">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="min-w-0">
              <p className="text-[12.5px] font-semibold text-amber-200">Mods your players also need</p>
              <p className="text-[11.5px] leading-snug text-amber-300/90">
                {s.clientModsAuto ? `Auto-updated too (you turned this on ${ago(s.clientModsAckAt)}). Players are locked out until they update to the same version.` : "Only notified, never auto-updated — a different version on the server locks players out until they update theirs."}
              </p>
            </div>
            <button type="button" className={btn} disabled={busy} onClick={() => (s.clientModsAuto ? run(() => setClientModsAuto(serverId, false, ""), "Mods players need will only be notified now.") : setOptIn(true))}>
              {s.clientModsAuto ? "Stop auto-updating these" : "Auto-update these too…"}
            </button>
          </div>
        </div>
      </div>

      <div className={card}>
        <h4 className="text-[13px] font-bold text-white">Your mods</h4>
        {view.mods.length === 0 ? (
          <p className="mt-2 text-[12px] text-tx-faint">No mods installed.</p>
        ) : (
          <ul className="mt-2 flex flex-col divide-y divide-[rgba(120,140,200,.12)]">
            {view.mods.map((m) => (
              <li key={m.id} className="flex flex-col gap-2 py-3 sm:flex-row sm:items-start">
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-1.5">
                    <span className="text-[13px] font-bold text-white">{m.name}</span>
                    <span className="num text-[11.5px] text-tx-faint">{m.version ? `v${m.version}` : ""}</span>
                    {m.available && <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200">→ {m.available}</Chip>}
                    <ClientBadge m={m} />
                    {m.pinned && <Chip cls="border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]">Pinned</Chip>}
                    {m.failures > 0 && <Chip cls="border-red-500/40 bg-red-500/10 text-red-300">{m.failures} failed</Chip>}
                  </div>
                  {m.reason && <p className="mt-1 text-[11.5px] leading-snug text-tx-dim">{m.reason}</p>}
                  {m.lastFailure && <p className="mt-1 text-[11.5px] leading-snug text-red-300">{m.lastFailure}</p>}
                  <p className="mt-1 text-[11px] text-tx-faint">{m.effectiveReason}{m.lastUpdateAt ? ` · last auto-updated ${ago(m.lastUpdateAt)}` : ""}</p>
                </div>
                <select aria-label={`Update setting for ${m.name}`} disabled={busy} className="input h-9 w-full flex-none text-[12px] sm:w-[170px]"
                  value={m.pinned ? "PIN" : m.override ?? "INHERIT"}
                  onChange={(e) => {
                    const v = e.target.value;
                    run(() => setModUpdateMode(serverId, m.id, m.pinned && v !== "PIN" ? "UNPIN" : v).then(async (r) => (m.pinned && v !== "PIN" && v !== "INHERIT" && !r.error ? setModUpdateMode(serverId, m.id, v) : r)), "Saved.");
                  }}>
                  <option value="INHERIT">Server default ({MODE_LABEL[s.mode]})</option>
                  <option value="OFF">Off</option>
                  <option value="NOTIFY">Notify me</option>
                  <option value="AUTO">Auto-update</option>
                  <option value="PIN">Pin this version</option>
                </select>
              </li>
            ))}
          </ul>
        )}
      </div>

      <AutoUpdateProfiles serverId={serverId} family={view.familyName} profiles={view.profiles} onChanged={load} />
      <AutoUpdateHistory runs={view.runs} />

      {confirmApply && (
        <Dialog onClose={() => setConfirmApply(false)} title="Update mods now?">
          <ul className="flex list-disc flex-col gap-1 pl-5 text-[12.5px] text-tx-dim">
            {available.map((m) => <li key={m.id}>{m.name} {m.version} → <strong className="text-white">{m.available}</strong></li>)}
          </ul>
          {playersAffected.length > 0 && (
            <p className="mt-3 rounded-[10px] border border-amber-500/30 bg-amber-500/[0.07] px-3 py-2 text-[12px] leading-snug text-amber-300">
              Players will need {playersAffected.map((m) => `${m.name} ${m.available}`).join(", ")} on their own game to keep joining. The player profile below updates automatically.
            </p>
          )}
          <p className="mt-3 text-[11.5px] text-tx-faint">The server restarts now, even if people are online. If it doesn't come back, the previous mods are restored automatically.</p>
          <div className="mt-4 flex justify-end gap-2">
            <button type="button" className={btn} onClick={() => setConfirmApply(false)}>Cancel</button>
            <button type="button" className="nx-cta px-4 py-1.5 text-[12.5px]" onClick={() => { setConfirmApply(false); run(() => applyModUpdatesNow(serverId), "Updating — follow the progress above."); }}>Update and restart</button>
          </div>
        </Dialog>
      )}
      {optIn && <OptInDialog onClose={() => setOptIn(false)} onConfirm={(phrase) => { setOptIn(false); run(() => setClientModsAuto(serverId, true, phrase), "Mods players need will be auto-updated too."); }} />}
    </div>
  );
}

function Dialog({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-[80] flex items-end justify-center bg-black/60 p-4 sm:items-center" role="dialog" aria-modal="true" aria-label={title} onClick={onClose}>
      <div className="w-full max-w-[480px] rounded-[16px] border border-rim-hi bg-[#081230] p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <h3 className="mb-3 text-[15px] font-bold text-white">{title}</h3>
        {children}
      </div>
    </div>
  );
}

function OptInDialog({ onClose, onConfirm }: { onClose: () => void; onConfirm: (phrase: string) => void }) {
  const [phrase, setPhrase] = useState("");
  const want = "players-must-update";
  return (
    <Dialog title="Auto-update mods players need?" onClose={onClose}>
      <p className="text-[12.5px] leading-relaxed text-tx-dim">
        Some mods have to be the <strong className="text-white">same version on the server and on every player's game</strong> — Valheim refuses the connection otherwise. If we update one of those on the server automatically, <strong className="text-amber-300">your players can't join until they update theirs</strong>.
      </p>
      <p className="mt-2 text-[12.5px] leading-relaxed text-tx-dim">You'll get a message with the exact versions each time, and the player profile updates itself.</p>
      <label className="mt-3 flex flex-col gap-1 text-[12px] text-tx-dim">
        Type <span className="font-mono text-white">{want}</span> to confirm
        <input value={phrase} onChange={(e) => setPhrase(e.target.value)} className="input h-9 text-[12.5px]" autoComplete="off" spellCheck={false} />
      </label>
      <div className="mt-4 flex justify-end gap-2">
        <button type="button" className={btn} onClick={onClose}>Cancel</button>
        <button type="button" className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50" disabled={phrase.trim() !== want} onClick={() => onConfirm(phrase.trim())}>Turn on</button>
      </div>
    </Dialog>
  );
}

