"use client";

import { useState, useTransition } from "react";
import { createPlayerShareCode, type ModUpdatesView } from "@/lib/actions-mod-autoupdate";

/**
 * "Give this to your players" — the client profiles the worker regenerates
 * after every mod change (ModClientProfile). Fixes "my friends can't join":
 * players import the server's exact mod versions in one step.
 */
const btn = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50";

const KIND: Record<string, { label: string; how: string }> = {
  r2z: { label: "r2modman / Thunderstore profile (.r2z)", how: "In r2modman or Thunderstore Mod Manager: Settings → Import profile → From file. It installs every mod at the server's exact version." },
  mrpack: { label: "Modrinth modpack (.mrpack)", how: "Open it with the Modrinth App, Prism Launcher or ATLauncher (Import → .mrpack). It sets up the right loader and every client mod." },
  checklist: { label: "Checklist (.txt)", how: "Names, exact versions and links — for players installing by hand." },
};

export function AutoUpdateProfiles({ serverId, family, profiles, onChanged }: { serverId: string; family: string; profiles: ModUpdatesView["profiles"]; onChanged: () => void }) {
  const [open, setOpen] = useState(false);
  const [code, setCode] = useState<string | null>(profiles.find((p) => p.kind === "r2z")?.shareCode ?? null);
  const [err, setErr] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [pending, start] = useTransition();
  const order = ["r2z", "mrpack", "checklist"];
  const list = [...profiles].sort((a, b) => order.indexOf(a.kind) - order.indexOf(b.kind));

  return (
    <div className="rounded-[14px] border border-[#7b3fef]/35 bg-[linear-gradient(135deg,rgba(59,107,232,.12),rgba(123,63,239,.12))] p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="min-w-0">
          <h4 className="text-[13px] font-bold text-white">Friends can't join?</h4>
          <p className="text-[11.5px] leading-snug text-tx-dim">Players need the same mod versions as the server. Hand them a ready-made profile — it's rebuilt automatically after every update.</p>
        </div>
        <button type="button" className="nx-cta px-4 py-1.5 text-[12.5px]" onClick={() => setOpen((o) => !o)} aria-expanded={open}>Give this to your players</button>
      </div>
      {open && (
        <div className="mt-3 flex flex-col gap-2.5">
          {list.length === 0 && <p className="text-[12px] text-tx-faint">No profile yet — press “Check now” above and it's generated from what's on your {family} server.</p>}
          {list.map((p) => (
            <div key={p.kind} className="rounded-[12px] border border-rim-hi bg-well p-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="min-w-0">
                  <p className="text-[12.5px] font-semibold text-white">{KIND[p.kind]?.label ?? p.kind}</p>
                  <p className="text-[11px] text-tx-faint">Updated {new Date(p.generatedAt).toLocaleString()}</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <a className={btn} href={`/api/servers/${serverId}/mod-profile/${p.kind}`} download={p.fileName}>Download</a>
                  {p.kind === "r2z" && (
                    <button type="button" className={btn} disabled={pending} onClick={() => start(async () => {
                      setErr(null);
                      const r = await createPlayerShareCode(serverId).catch(() => ({ error: "Couldn't create a code." } as { error?: string; code?: string }));
                      if (r.code) { setCode(r.code); onChanged(); } else setErr(r.error ?? "Couldn't create a code.");
                    })}>{code ? "Show code" : "Get a profile code"}</button>
                  )}
                </div>
              </div>
              <p className="mt-1.5 text-[11.5px] leading-snug text-tx-dim">{KIND[p.kind]?.how}</p>
              {p.kind === "r2z" && code && (
                <div className="mt-2 flex flex-wrap items-center gap-2">
                  <code className="rounded-[8px] border border-rim-hi bg-[rgba(2,7,20,.6)] px-2.5 py-1 font-mono text-[13px] text-cyan-200">{code}</code>
                  <button type="button" className={btn} onClick={() => { void navigator.clipboard?.writeText(code).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1500); }); }}>{copied ? "Copied" : "Copy"}</button>
                  <span className="text-[11px] text-tx-faint">r2modman: Import profile → From code. Codes expire after a while; the file doesn't.</span>
                </div>
              )}
              {p.notes && <p className="mt-1.5 whitespace-pre-line text-[11px] leading-snug text-amber-300/90">{p.notes}</p>}
            </div>
          ))}
          {err && <p className="text-[12px] text-red-300">{err}</p>}
        </div>
      )}
    </div>
  );
}

