"use client";

import { useState } from "react";
import type { ModUpdatesView } from "@/lib/actions-mod-autoupdate";

/** Update history / audit trail (ModUpdateRun rows, newest first). */
const TONE: Record<string, string> = {
  APPLIED: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
  ROLLED_BACK: "border-amber-500/45 bg-amber-500/12 text-amber-300",
  FAILED: "border-red-500/40 bg-red-500/10 text-red-300",
  DEFERRED: "border-rim-hi bg-well text-tx-faint",
  CHECKED: "border-cyan-400/40 bg-cyan-400/10 text-cyan-200",
  HELD: "border-amber-500/45 bg-amber-500/12 text-amber-300",
  NOOP: "border-rim-hi bg-well text-tx-faint",
};
const LABEL: Record<string, string> = { APPLIED: "Updated", ROLLED_BACK: "Rolled back", FAILED: "Failed", DEFERRED: "Waiting", CHECKED: "Checked", HELD: "Held", NOOP: "Nothing to do" };
const TRIGGER: Record<string, string> = { sweep: "automatic", manual: "you", "game-update": "after a game update" };

export function AutoUpdateHistory({ runs }: { runs: ModUpdatesView["runs"] }) {
  const [all, setAll] = useState(false);
  const shown = all ? runs : runs.slice(0, 5);
  return (
    <div className="rounded-[14px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-4">
      <h4 className="text-[13px] font-bold text-white">Update history</h4>
