import { useTransition } from "react";
import { adminClearModUpdateBackoff, setModAutoUpdatePaused } from "@/lib/actions-mod-autoupdate";

/** Fleet-wide kill switch for mod auto-update (Setting mod_autoupdate_enabled). */
export function ModAutoUpdateKillSwitch({ paused }: { paused: boolean }) {
  const [pending, start] = useTransition();
  return paused ? (
    <button className="btn-primary py-1 text-xs" disabled={pending} onClick={() => start(async () => { await setModAutoUpdatePaused(false); })}>Resume auto-updates</button>
  ) : (
    <button
      className="btn-secondary py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (!window.confirm("Pause mod auto-update for EVERY server? Checks keep running; nothing is applied until you resume.")) return;
        start(async () => { await setModAutoUpdatePaused(true); });
      }}
    >
      Pause fleet-wide
    </button>
  );
}

export function ClearBackoffButton({ serverId }: { serverId: string }) {
  const [pending, start] = useTransition();
  return (
    <button className="btn-secondary py-0.5 text-xs" disabled={pending} onClick={() => start(async () => { await adminClearModUpdateBackoff(serverId); })}>
      Clear back-off
    </button>
  );
}

