input.content:
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, StatCard, timeAgo } from "@/components/ui/primitives";
import { adminKillSwitchOn, envConfig } from "@/lib/mod-autoupdate/config";
import { ModAutoUpdateKillSwitch, ClearBackoffButton } from "@/components/admin/ModAutoUpdateControls";

export const dynamic = "force-dynamic";

const tone = (s: string): "green" | "red" | "amber" | "brand" =>
  s === "APPLIED" ? "green" : s === "FAILED" ? "red" : s === "ROLLED_BACK" || s === "HELD" ? "amber" : "brand";

/**
 * Mod auto-update — fleet view: switches, what's running, failures and
 * rollbacks, servers in back-off. Data is ModUpdateRun / ModAutoUpdateSettings
 * / ServerMod rows written by worker/mod-autoupdate.ts; nothing is estimated.
 */
export default async function AdminModUpdatesPage() {
  await requireArea("fleet");
  const env = envConfig();
  const paused = await adminKillSwitchOn();
  const since = new Date(Date.now() - 7 * 86400_000);
  const [byMode, runs7, recent, backoff, available, failing, jobs] = await Promise.all([
    db.modAutoUpdateSettings.groupBy({ by: ["mode"], _count: { _all: true } }),
    db.modUpdateRun.groupBy({ by: ["status"], where: { startedAt: { gt: since } }, _count: { _all: true } }),
    db.modUpdateRun.findMany({ where: { status: { in: ["APPLIED", "ROLLED_BACK", "FAILED"] } }, orderBy: { startedAt: "desc" }, take: 40, include: { server: { select: { hostname: true, id: true } } } }),
    db.modAutoUpdateSettings.findMany({ where: { nextEligibleAt: { gt: new Date() } }, include: { server: { select: { hostname: true } } }, take: 50 }),
    db.serverMod.count({ where: { availableVersion: { not: null } } }),
    db.serverMod.findMany({ where: { updateFailures: { gt: 0 } }, include: { mod: { select: { name: true } }, server: { select: { hostname: true, id: true } } }, orderBy: { updatedAt: "desc" }, take: 30 }),
    db.job.count({ where: { type: "GAME_MOD_AUTOUPDATE", status: { in: ["QUEUED", "RUNNING"] } } }),
  ]);
  const count = (arr: { _count: { _all: number } }[], f: (x: any) => boolean) => arr.filter(f).reduce((a, x) => a + x._count._all, 0);

  return (
    <div>
      <PageHeader title="Mod auto-update" sub="Compatible-version checks and automatic updates for one-click mods (snapshot → update → restart → health check → automatic rollback).">
        {paused ? <Badge tone="red">paused fleet-wide</Badge> : env.sweepEnabled && !env.envKilled ? <Badge tone="green">sweep on</Badge> : <Badge tone="amber">sweep off</Badge>}
      </PageHeader>

      <div className="card mb-6 flex flex-wrap items-center justify-between gap-3">
        <div className="text-sm">
          <div>ENABLE_MOD_AUTOUPDATE: <strong>{env.sweepEnabled ? "1 (sweep on)" : "unset (sweep off)"}</strong> · MOD_AUTOUPDATE: <strong>{env.envKilled ? "off (env kill switch)" : "not off"}</strong> · mod engine on guests: <strong>{env.realGuests ? (env.sandbox ? "sandbox" : "enabled") : "ENABLE_REAL_GAMEMODS unset"}</strong></div>
          <div className="mt-1 text-xs text-slate-500">caps: {env.nodeCap}/node, {env.globalCap} fleet-wide · checks every {env.checkHours} h · up to {env.perSweep} jobs per 5-min sweep · {jobs} in flight</div>
        </div>
        <ModAutoUpdateKillSwitch paused={paused} />
      </div>

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Servers on AUTO" value={String(count(byMode, (x) => x.mode === "AUTO"))} delta={`${count(byMode, (x) => x.mode === "NOTIFY")} notify · ${count(byMode, (x) => x.mode === "OFF")} off`} />
        <StatCard label="Updates waiting" value={String(available)} delta="mods with a newer compatible version" />
        <StatCard label="Applied (7 d)" value={String(count(runs7, (x) => x.status === "APPLIED"))} />
        <StatCard label="Rolled back / failed (7 d)" value={String(count(runs7, (x) => x.status === "ROLLED_BACK" || x.status === "FAILED"))} />
      </div>

      <h2 className="mb-2 text-lg font-semibold">Recent updates, rollbacks and failures</h2>
      <div className="card mb-8 overflow-x-auto">
        {recent.length === 0 ? <p className="text-sm text-slate-500">None yet.</p> : (
          <table className="w-full text-left text-sm">
            <thead className="text-xs text-slate-500"><tr><th className="py-1">When</th><th>Server</th><th>Result</th><th>Trigger</th><th>Detail</th></tr></thead>
            <tbody>
              {recent.map((r) => (
                <tr key={r.id} className="border-t border-white/5 align-top">
                  <td className="py-1 whitespace-nowrap">{timeAgo(r.startedAt)}</td>
                  <td><a className="hover:underline" href={`/admin/servers/${r.server.id}`}>{r.server.hostname}</a></td>
                  <td><Badge tone={tone(r.status)}>{r.status.toLowerCase().replace("_", " ")}</Badge></td>
                  <td className="text-slate-400">{r.trigger}</td>
                  <td className="max-w-[560px] text-xs text-slate-400">{r.summary}{r.snapshotPath ? <div className="mt-0.5 font-mono">snapshot {r.snapshotPath}</div> : null}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <h2 className="mb-2 text-lg font-semibold">Mods with failed updates</h2>
      <div className="card mb-8 overflow-x-auto">
        {failing.length === 0 ? <p className="text-sm text-slate-500">None.</p> : (
          <table className="w-full text-left text-sm">
