/* TEMPORARY verification script — NOT committed. Runs against the throwaway DB in SANDBOX mode. */
import { db } from "../lib/db";
import { gameModAutoUpdate, modAutoUpdateSweep } from "../worker/mod-autoupdate";
import { installOrUpdate, loadState } from "../lib/mods/engine";
import { minecraftInstaller } from "../lib/mods/installers/minecraft";
import { valheimInstaller } from "../lib/mods/installers/valheim";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest } from "../lib/mods/guest-fs";
import { safeFetch, fetchJson } from "../lib/mods/safe-fetch";
import { catalogFacts, serverFacts } from "../lib/mods/facts";
import type { FamilyInstaller, ResolvedPackage } from "../lib/mods/types";
import { readdirSync } from "node:fs";
import path from "node:path";

async function main() {
  if (process.env.NXEON_SANDBOX !== "1") throw new Error("sandbox only");
  if (!/nxeon_agt_modupdate/.test(process.env.DATABASE_URL ?? "")) throw new Error("throwaway DB only");
  const user = await db.user.upsert({ where: { email: "modupd-test@example.invalid" }, create: { email: "modupd-test@example.invalid", passwordHash: "x", name: "Mod Update Test" }, update: {} });
  const plan = await db.plan.upsert({ where: { slug: "modupd-test" }, create: { slug: "modupd-test", name: "t", cpuCores: 2, ramMB: 4096, diskGB: 20, priceCents: 0 }, update: {} });
  const osMc = await db.osTemplate.upsert({ where: { slug: "modupd-mc" }, create: { slug: "modupd-mc", name: "Minecraft", vmid: 99901, family: "minecraft" } as never, update: {} });
  const osVh = await db.osTemplate.upsert({ where: { slug: "modupd-vh" }, create: { slug: "modupd-vh", name: "Valheim", vmid: 99902, family: "valheim" } as never, update: {} });
  const mk = (hostname: string, os: string, variant: string, cfg: object) =>
    db.server.upsert({ where: { hostname }, create: { name: hostname, hostname, userId: user.id, planId: plan.id, osTemplateId: os, status: "RUNNING", gameVariant: variant, gameConfig: cfg } as never, update: { status: "RUNNING" } as never });
  const mc = await mk("modupd-mc-1", osMc.id, "paper", { VERSION: "1.21.1" });
  const vh = await mk("modupd-vh-1", osVh.id, "bepinex", {});

  const lp = await db.gameMod.upsert({ where: { gameFamily_slug: { gameFamily: "minecraft", slug: "luckperms" } }, create: { gameFamily: "minecraft", name: "LuckPerms", slug: "luckperms", category: "Plugins", source: "modrinth", sourceId: "luckperms", url: "https://modrinth.com/plugin/luckperms", loaders: ["paper"] }, update: {} });
  const jt = await db.gameMod.upsert({ where: { gameFamily_slug: { gameFamily: "valheim", slug: "jotunn" } }, create: { gameFamily: "valheim", name: "Jötunn", slug: "jotunn", category: "Libraries", source: "thunderstore", sourceId: "ValheimModding-Jotunn", url: "https://thunderstore.io/c/valheim/p/ValheimModding/Jotunn/" }, update: {} });

  // ── install an OLD LuckPerms build with the real install engine ──
  const fsMc = new LocalGuestFs(sandboxGuestRoot(mc.id));
  await seedSandboxGuest(fsMc, "minecraft", "paper");
  type MrV = { id: string; project_id: string; version_number: string; files: { url: string; filename: string; primary: boolean; size: number; hashes: { sha1: string; sha512: string } }[] };
  const versions = await fetchJson<MrV[]>(safeFetch, `https://api.modrinth.com/v2/project/luckperms/version?loaders=${encodeURIComponent('["paper"]')}&game_versions=${encodeURIComponent('["1.21.1"]')}`);
  const old = versions[Math.min(versions.length - 1, 3)];
  console.log(`LuckPerms builds for paper 1.21.1: ${versions.length}; installing old ${old.version_number} (newest is ${versions[0].version_number})`);
  const f = old.files.find((x) => x.primary) ?? old.files[0];
  const pkgMc: ResolvedPackage = { key: `modrinth:${old.project_id}`, name: "LuckPerms", version: old.version_number, versionId: old.id, file: { url: f.url, filename: f.filename, size: f.size, hashes: f.hashes, mirrorKey: { source: "modrinth", projectId: old.project_id, versionId: old.id } }, placement: "plugin-jar", requires: [], incompatible: [], root: true };
  const pinnedMc: FamilyInstaller = { ...minecraftInstaller, resolve: async () => ({ packages: [pkgMc], notes: [] }) };
  const r1 = await installOrUpdate(pinnedMc, catalogFacts(lp), serverFacts(mc as never, "minecraft"), { fs: fsMc, fetcher: safeFetch });
  console.log("install old LuckPerms:", r1.ok ? r1.changed : r1.error);
  await db.serverMod.upsert({ where: { serverId_modId: { serverId: mc.id, modId: lp.id } }, create: { serverId: mc.id, modId: lp.id, status: "INSTALLED", version: old.version_number }, update: { status: "INSTALLED", version: old.version_number, autoUpdate: null, updateFailures: 0 } });

  // ── install an OLD Jötunn ──
  const fsVh = new LocalGuestFs(sandboxGuestRoot(vh.id));
  await seedSandboxGuest(fsVh, "valheim", "bepinex");
  type TsV = { namespace: string; name: string; version_number: string; full_name: string; download_url: string; dependencies: string[]; file_size?: number };
  let tsOld: TsV | null = null;
  for (const vv of ["2.20.0", "2.19.0", "2.18.0", "2.12.0"]) {
    tsOld = await fetchJson<TsV>(safeFetch, `https://thunderstore.io/api/experimental/package/ValheimModding/Jotunn/${vv}/`).catch(() => null);
    if (tsOld) break;
  }
  if (!tsOld) throw new Error("no old Jotunn version found");
  const pkgVh: ResolvedPackage = { key: "thunderstore:ValheimModding-Jotunn", name: "Jötunn", version: tsOld.version_number, versionId: tsOld.full_name, file: { url: tsOld.download_url, filename: `${tsOld.full_name}.zip`, size: tsOld.file_size ?? null, hashes: {}, mirrorKey: { source: "thunderstore", projectId: "ValheimModding-Jotunn", versionId: tsOld.version_number } }, placement: "bepinex", requires: [], incompatible: [], root: true };
  const pinnedVh: FamilyInstaller = { ...valheimInstaller, resolve: async () => ({ packages: [pkgVh], notes: [] }) };
  const r2 = await installOrUpdate(pinnedVh, catalogFacts(jt), serverFacts(vh as never, "valheim"), { fs: fsVh, fetcher: safeFetch });
  console.log("install old Jotunn:", r2.ok ? r2.changed : r2.error);
  await db.serverMod.upsert({ where: { serverId_modId: { serverId: vh.id, modId: jt.id } }, create: { serverId: vh.id, modId: jt.id, status: "INSTALLED", version: tsOld.version_number }, update: { status: "INSTALLED", version: tsOld.version_number } });

  for (const s of [mc, vh]) await db.modAutoUpdateSettings.upsert({ where: { serverId: s.id }, create: { serverId: s.id, mode: "AUTO", windowStart: 0, windowEnd: 0 }, update: { mode: "AUTO", windowStart: 0, windowEnd: 0, lastCheckAt: null, nextEligibleAt: null, profileHash: null } });
  await db.job.deleteMany({ where: { serverId: { in: [mc.id, vh.id] } } });

  // ── sweep enqueues, handler runs ──
  const sw = await modAutoUpdateSweep();
  console.log("sweep:", sw);
  const jobs = await db.job.findMany({ where: { type: "GAME_MOD_AUTOUPDATE", status: "QUEUED" } });
  for (const j of jobs) {
    await db.job.update({ where: { id: j.id }, data: { status: "RUNNING" } });
    await gameModAutoUpdate(j);
    await db.job.update({ where: { id: j.id }, data: { status: "DONE" } });
  }
  for (const s of [mc, vh]) {
    console.log(`\n=== ${s.hostname}`);
    for (const r of await db.modUpdateRun.findMany({ where: { serverId: s.id }, orderBy: { startedAt: "asc" } })) console.log(`run ${r.status} [${r.trigger}]: ${r.summary}\n   applied=${JSON.stringify(r.applied)} snapshot=${r.snapshotPath}`);
    for (const m of await db.serverMod.findMany({ where: { serverId: s.id }, include: { mod: { select: { name: true } } } })) console.log(`mod ${m.mod.name}: v${m.version} available=${m.availableVersion} client=${m.clientRequired} (${m.clientReason})\n   reason: ${m.availableReason}`);
    for (const p of await db.modClientProfile.findMany({ where: { serverId: s.id } })) console.log(`profile ${p.kind} ${p.fileName} ${p.data.length}B notes=${p.notes ?? "-"}`);
    const st = await loadState(new LocalGuestFs(sandboxGuestRoot(s.id)), s.id === mc.id ? "minecraft" : "valheim");
    console.log("guest state:", Object.values(st.packages).map((p) => `${p.key}@${p.version} files=${p.files.map((x) => path.basename(x.path)).join(",")}`).join(" | "));
    for (const n of await db.notification.findMany({ where: { userId: user.id }, orderBy: { createdAt: "asc" } })) if (n.href?.includes(s.id)) console.log(`notification: ${n.title} — ${n.body}`);
  }
  console.log("\nMC plugins dir:", readdirSync(path.join(sandboxGuestRoot(mc.id), "opt/mc/plugins")));
  console.log("MC snapshots:", readdirSync(path.join(sandboxGuestRoot(mc.id), "root/.nxeon-mods/autoupdate")).join(", "));
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

