/* TEMPORARY verification script — NOT committed. Valheim manual apply + profile dump, throwaway DB, SANDBOX. */
import { db } from "../lib/db";
import { gameModAutoUpdate } from "../worker/mod-autoupdate";
import { loadState } from "../lib/mods/engine";
import { LocalGuestFs, sandboxGuestRoot } from "../lib/mods/guest-fs";
import { readZip } from "../lib/mods/archive";
import { writeFileSync } from "node:fs";

async function main() {
  if (!/nxeon_agt_modupdate/.test(process.env.DATABASE_URL ?? "") || process.env.NXEON_SANDBOX !== "1") throw new Error("throwaway sandbox only");
  const vh = await db.server.findUniqueOrThrow({ where: { hostname: "modupd-vh-1" } });
  const job = await db.job.create({ data: { type: "GAME_MOD_AUTOUPDATE", serverId: vh.id, status: "RUNNING", payload: { trigger: "manual", apply: true } } });
  await gameModAutoUpdate(job);
  await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
  const run = await db.modUpdateRun.findFirst({ where: { serverId: vh.id }, orderBy: { startedAt: "desc" } });
  console.log(`run ${run?.status} [${run?.trigger}]: ${run?.summary}\n applied=${JSON.stringify(run?.applied)}`);
  const st = await loadState(new LocalGuestFs(sandboxGuestRoot(vh.id)), "valheim");
  console.log("guest:", Object.values(st.packages).map((p) => `${p.key}@${p.version}`));
  for (const p of await db.modClientProfile.findMany({ where: { serverId: vh.id } })) {
    const out = `${process.env.OUT_DIR}/${p.fileName}`;
    writeFileSync(out, Buffer.from(p.data));
    console.log(`--- ${p.kind} -> ${out} (${p.data.length}B)`);
    if (p.kind === "r2z") for (const e of readZip(Buffer.from(p.data))) console.log(e.path.join("/") + ":\n" + e.data.toString("utf8"));
    if (p.kind === "checklist") console.log(Buffer.from(p.data).toString("utf8"));
  }
  const n = await db.notification.findFirst({ where: { href: { contains: vh.id } }, orderBy: { createdAt: "desc" } });
  console.log("notification:", n?.title, "—", n?.body);
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

