const { chromium } = require("/opt/nxeon/node_modules/playwright");
const { SignJWT } = require("/opt/nxeon/node_modules/jose");
const OUT = process.env.OUT;
const [mc, vh] = [process.env.MC, process.env.VH];

(async () => {
  const token = await new SignJWT({ sub: process.env.UID, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(new TextEncoder().encode(process.env.AUTH_SECRET));
  const browser = await chromium.launch();
  const errors = [];
  for (const [label, vp] of [["desktop", { width: 1440, height: 1000 }], ["mobile", { width: 390, height: 844 }]]) {
    const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: 1 });
    await ctx.addCookies([
      { name: "nxeon_session", value: token, domain: "localhost", path: "/" },
      { name: "nxeon_session", value: token, domain: "127.0.0.1", path: "/" },
    ]);
    const page = await ctx.newPage();
    page.on("pageerror", (e) => errors.push(`${label} pageerror: ${e.message}`));
    page.on("console", (m) => { if (m.type() === "error") errors.push(`${label} console: ${m.text().slice(0, 200)}`); });
    for (const [name, id] of [["vh", vh], ["mc", mc]]) {
      await page.goto(`http://localhost:3077/dashboard/servers/${id}?tab=mods`, { waitUntil: "domcontentloaded", timeout: 240000 });
      await page.waitForSelector("#mod-updates h3", { timeout: 240000 });
      await page.waitForTimeout(1500);
      const el = page.locator("#mod-updates");
      await el.scrollIntoViewIfNeeded();
      if (name === "vh") {
        await page.getByRole("button", { name: "Give this to your players" }).click();
        await page.waitForTimeout(400);
      }
      await el.screenshot({ path: `${OUT}/${name}-${label}.png` });
      const w = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      if (w > 0) errors.push(`${label} ${name}: horizontal overflow ${w}px`);
      if (label === "desktop" && name === "vh") {
        await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
        await page.waitForTimeout(300);
        await el.screenshot({ path: `${OUT}/${name}-${label}-light.png` });
        await page.evaluate(() => document.documentElement.setAttribute("data-theme", "dark"));
        // opt-in dialog
        await page.getByRole("button", { name: "Auto-update these too…" }).click();
        await page.waitForTimeout(300);
        await page.screenshot({ path: `${OUT}/vh-optin-dialog.png` });
        const disabled = await page.getByRole("button", { name: "Turn on" }).isDisabled();
        if (!disabled) errors.push("opt-in button enabled without phrase");
        await page.keyboard.press("Escape");
        // download route
        const r = await page.request.get(`http://localhost:3077/api/servers/${vh}/mod-profile/r2z`);
        console.log("r2z download:", r.status(), r.headers()["content-type"], (await r.body()).length, "bytes");
        const r404 = await page.request.get(`http://localhost:3077/api/servers/${vh}/mod-profile/mrpack`);
        console.log("mrpack (not generated for Valheim):", r404.status());
      }
    }
    if (label === "desktop") {
      await page.goto(`http://127.0.0.1:3077/admin/mod-updates`, { waitUntil: "domcontentloaded", timeout: 240000 });
      await page.waitForSelector("text=Mod auto-update", { timeout: 240000 });
      await page.waitForTimeout(800);
      await page.screenshot({ path: `${OUT}/admin.png`, fullPage: true });
